window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_010"]={"n":"顾璘","dyn":"明","poems":[{"t":"登高丘而望远海","f":"五言古诗","c":["豋高而望远，不见天地端。","日月互上下，东西如跳丸。","长风自何起，瀛海翻波澜。","六鳌正抃舞，五岳无时安。","恍惚青天中，仙人跨飞鸾。","邀我谒帝室，金门郁盘桓。","青龙对人怒，玉女倾笑欢。","彷徨返故路，北斗方阑干。","坐地仰天叹，三日不能餐。"]},{"t":"伤歌行","f":"古风","c":["青春欲去不可留，白日欲落花含愁。","银鞍白马分明别，故苑夫容伤素秋。","不惜红颜坐凋歇，可怜君恩难再得。","夜簟香销巫峡云，寒衣泪落秦关雪。","掩却青铜镜，不忍生尘埃。","且留兰膏烛，有心莫成灰。","风吹蓬枝往复回，去年团扇今年开。","小物无情尚如此，何独君恩无去来。","买赋无黄金，挑丝不成锦。","欲因魂梦逐车轮，愿君莫恶珊瑚枕。"]},{"t":"春日行","f":"七言古诗","c":["汉家三十六离宫，桃花树树摇春风。","武皇当年正好武，天马七尺如飞龙。","清晨蹋鞠过新市，薄暮鸣鞘入禁中。","中人尽戴鵔鸃冠，猛士半跨黄金鞍。","弯弓向云仰射雁，一发两禽皆道难。","大官赐酒砗磲瓯，一春击尽千肥牛。","撞钟伐鼓献奇舞，灯前变幻鱼龙浮。","宫门沉沉金钥收，明月挂在城西楼，东方渐高复来游。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，水多泥滑。","泥滑道阻，伤我车毂。","持膏作烛，将以照夜。","虚花掩光，不逮槃下。","猛虎在山，百兽畏威。","陷阱三日，垂首诉饥。","铁生矿中，入冶为器。","剑负威神，锤则委地。","男儿生身，万事纲纪。","突梯无施，不如女子。"]},{"t":"塞下曲 其一","f":"七言绝句","c":["千里骅骝丈八矛，男儿画地取封侯。","黄昏塞上传烽火，一夜吹笳坐戍楼。"]},{"t":"塞下曲 其二","f":"七言绝句","c":["百战摧胡未许强，马前生缚左贤王。","麟符鹊印须臾事，只博凌烟字一行。"]},{"t":"塞下曲 其三","f":"七言绝句","c":["黄河冰厚马横行，朔气棱棱古铁明。","恨杀夜来风雪紧，匈奴逃出受降城。"]},{"t":"古壮士歌","f":"七言古诗","c":["山西壮士何才雄，虬须燕颔生英风。","青春挟槊三边外，白昼探丸九市中。","一身列侍麒麟殿，跨出龙驹万人羡。","狐腋朝裁赵客裘，鹈膏夜淬吴王剑。","生年十五事横行，肯学操觚记姓名。","当衢贾勇万乘避，临危重义一身轻。","田文鸡狗真馀子，有足不曳春申履。","眼前国士稍倾心，慷慨桥阴为君死。"]},{"t":"长相思曲","f":"古风","c":["长相思，在何处，吴岫云深隔江树。","江树临春花正荣，人今已向天涯去。","璚楼绣户横兰烟，中有绿鬟金骨仙。","星河隐约秋期杳，坐捲朱帘望月圆。"]},{"t":"夜雨叹","f":"七言古诗","c":["朔风吹雨西北来，南山昼晦夜不开。","寒声悲凄杂霰落，暮色黯惨兼云回。","仰窥箕斗不辨影，俯眺八极弥黄埃。","群鸡啁啾登树语，城角断续馀音哀。","此时野人正愁郁，短漏颇柰铜龙催。","残灯微明鼠上下，兀坐自画炉中灰。","北漠群胡践边垒，西江狂贼生祸胎。","主上动色念沟壑，何况司马诸行台。","长星流天火堕地，荧惑扰纪何为哉。","去年三吴遭赤旱，万户鬻子无遗孩。","今年州司索官帑，肉瘠不救疮痍灾。","空田苍茫飞鸟尽，野水震荡惊鳞摧。","备民谁继子产智，足国正望夷吾才。","龙鸣剑匣壮士老，黄金台古空崔嵬。","海内故人掩关坐，尺书累岁谁为裁。","阳春何时动群蛰，九域浩荡扬风雷。","江河倒洗皇路净，台省洞达无嫌猜。","花明草媚日杲杲，男耕女织天恢恢。","野人多病有归处，养鸡牧豕王城隈。"]},{"t":"武皇南巡旧京歌 其一","f":"七言绝句","c":["紫盖黄旗拥六军，金陵王气日氤氲。","龙君涉海移三岛，凤女排空结五云。"]},{"t":"武皇南巡旧京歌 其二","f":"七言绝句","c":["北固江涛控海门，南都山势叠昆崙。","金宫暂启双龙见，玉帐遥临万马屯。"]},{"t":"武皇南巡旧京歌 其四","f":"七言绝句","c":["绿水朱楼佳丽城，君王行处彩云生。","烟花一望三千里，遥送春风入镐京。"]},{"t":"武皇南巡旧京歌 其六","f":"七言绝句","c":["千年宝历自南开，八叶神孙暂北来。","日月更临龙虎阜，云霞重抱凤凰台。"]},{"t":"武皇南巡旧京歌 其八","f":"七言绝句","c":["青龙山北接飞猱，白鹭洲东射海鳌。","不为芳春浪行幸，寝园聊待荐含桃。"]},{"t":"武皇南巡旧京歌 其十","f":"七言绝句","c":["旧都何让古新丰，父老称觞拜舞同。","金马词臣休候直，独宣京兆问民风。"]},{"t":"武皇南巡旧京歌 其十二","f":"七言绝句","c":["白发梨园老乐师，锦胸花帽对弹丝。","行宫只奏中和调，解厌南朝《玉树》词。"]},{"t":"武皇南巡旧京歌 其十三","f":"七言绝句","c":["石壁斜临玄武湖，中开天府贮民图。","文鱼在藻承皇泽，来傍龙舟夜吐珠。"]},{"t":"武皇南巡旧京歌 其十五","f":"七言绝句","c":["朱雀桥连翠柳衢，银鞍丝鞚锦模糊。","君王行乐千人出，遥认飞龙天马驹。"]},{"t":"武皇南巡旧京歌 其十六","f":"七言绝句","c":["六代繁华何足誇，而今四海共为家。","暂看吴苑环城水，终忆燕台夹路花。"]},{"t":"宫中词 其一","f":"五言律诗","c":["太液红云重，昭阳素月斜。","龙香浮蕙草，凤辇过桃花。","翠扇摇歌席，银屏隐卧车。","双双紫鸾羽，飞上玉皇家。"]},{"t":"宫中词 其二","f":"五言律诗","c":["复道通瀛海，周垣隐洞天。","云随珠佩女，霞覆羽衣仙。","秀艳疏丹粉，潜悲咽管弦。","春光閒永巷，愁坐惜流年。"]},{"t":"宫中词 其三","f":"五言律诗","c":["诏省长杨猎，虞人夜启关。","霜鹰腾紫籞，天马跃朱闲。","宝剑秋莲色，雕弓朔月弯。","非熊谁协兆，看载后车还。"]},{"t":"宫中词 其四","f":"五言律诗","c":["绮阁延朱夏，花阴昼漏长。","研砂养蜥蜴，刺绣学鸳鸯。","细字中官扇，奇熏外国香。","午窗兰玉梦，惊起谢君王。"]},{"t":"拟宫怨 其一","f":"七言律诗","c":["水殿夫容隐暗霜，夜临新月自焚香。","窗间画扇含秋思，帐里华灯隔御光。","四壁椒涂花霭散，六宫莲漏水声长。","君恩未必缘歌舞，无那昭阳掌上狂。"]},{"t":"拟宫怨 其二","f":"七言律诗","c":["紫殿繁华梦已沉，掖庭苔色晚阴阴。","浮云变态随君意，朗月流辉鉴妾心。","屈戍横门金锁冷，辘轳牵井玉瓶深。","空将锦瑟传哀怨，寂寞谁听空外音。"]},{"t":"拟宫怨 其三","f":"七言律诗","c":["翠靥金蝉入帝家，拟将新宠属铅华。","君王自信图中貌，静女虚迎梦里车。","帐殿秋阴生角枕，屧廊空响应琵琶。","含情独倚朱阑暮，满院微风动落花。"]},{"t":"拟宫怨 其四","f":"七言律诗","c":["汉皇宫殿月明时，曾侍宸游百子池。","舞马登床春进酒，盘龙衔烛夜观棋。","御前却辇言无忌，众里当熊死不辞。","旧恨飘零同落叶，春风空绕万年枝。"]},{"t":"拟宫怨 其五","f":"七言律诗","c":["咫尺长门万里遥，耻将裙绶曳纤腰。","盈盈璧月沉鸾镜，渺渺银河断鹊桥。","上苑旌旗回夜猎，建章钟鼓散晨朝。","此身不及双栖凤，处处随君听九《韶》。"]},{"t":"拟宫怨 其六","f":"七言律诗","c":["流苏帐冷璅窗虚，云月差差度玉除。","百岁精灵悲故剑，九重恩宠附前鱼。","莲花有恨凝芳履，竹叶无光引属车。","人意已疏言更浅，莫将词赋倚相如。"]},{"t":"拟宫怨 其七","f":"七言律诗","c":["不见彤墀日月旂，庭隅草木掩清辉。","金舆到处无新故，玉貌从来有是非。","暮雨楼台双燕入，春寒池馆百花稀。","监宫一去无人语，独自含颦咏绿衣。"]},{"t":"拟夏日宫中行乐词 其一","f":"七言绝句","c":["紫霄不与下方同，秋爽常回六月中。","风羽对摇云母榻，冰池全浸水晶宫。"]},{"t":"拟夏日宫中行乐词 其二","f":"七言绝句","c":["玉面朱唇映月明，影娥池畔绕花行。","夫容不耐凋残色，祇恐新凉一夜生。"]},{"t":"拟夏日宫中行乐词 其三","f":"七言绝句","c":["雾縠云绡细欲无，倚风临水弱须扶。","玉鱼疗渴辞盘露，纨扇伤秋对井梧。"]},{"t":"申思三首 其一","f":"五言古诗","c":["戚戚岁云暮，我行适潇湘。","兄弟持我泣，父母泪纵横。","云有薄田畴，卒岁具粢梁。","胡为去万里，骨肉相乖张。","局蹐诉父母，儿自恋家乡。","举事触明宪，置理窜南荒。","程期若星火，不得少留行。","勿复远思念，兄弟善持将。","吞声出门闾，沉痛绝衷肠。"]},{"t":"申思三首 其二","f":"五言古诗","c":["白日匿西景，扶桑复东辉。","岐路南以北，往来更践之。","人生百年内，赋命良不齐。","凤凰翔九霄，闻韶下来仪。","朝食丹山粟，夕饮天汉涯。","驽骀服鞭策，曲阪驱且驰。","驱驰岂遑恤，所嗟意乖违。","一为北山叹，听者心伤悲。","苍天高无极，悠悠当诉谁。"]},{"t":"申思三首 其三","f":"五言古诗","c":["南征上衡岳，长顾望旧都。","日月光回薄，钟陵郁苍梧。","朱凤何葳蕤，竹实日摧芜。","虎豹对我号，枭鸱噭相呼。","我行迫日暮，驽马忽匍匐。","战兢伤心魂，慄慄忧道途。","朅投主人舍，胁息告勤劬。","怜我客异县，携我就大巫。","服我勾漏砂，佩我太乙符。","再拜谢主人，归来始安居。","弃置勿复道，多忧令人老。"]},{"t":"自龙江发舟至京口江水如镜呈陈大鲁南","f":"七言律诗","c":["海门东下大江平，画舸夷犹尽日程。","绿树倏过瓜步堰，青山背指石头城。","离筵醉酒思高枕，独客辞家慰远行。","况有故人同晚泊，西津相引看潮生。"]},{"t":"行药至溪南偶成","f":"五言古诗","c":["抱痾掩荆扉，出户已寒节。","新晴步南溪，草际见残雪。","仰视日光微，始惊天气冽。","敝裘有馀温，浊酒堪独啜。","羸躯苟能存，暄月会当别。"]},{"t":"碧溪","f":"五言古诗","c":["落落高梧阴，俯瞰寒流碧。","微云过疏雨，秋容澹无迹。","鱼游绿藻晴，鸟下青芜夕。","兴至每垂纶，歌罢还岸帻。","渔父两三人，时来共争席。"]},{"t":"赠孙思和","f":"五言律诗","c":["东林一片石，绿藓生秋痕。","时招葛巾客，对坐倾匏尊。","俯爱涧下水，仰观枝上猿。","谁能策羸马，日夕依朱门。"]},{"t":"东郑生","f":"五言律诗","c":["图史聊足娱，胡为苦多营。","经旬谢宾客，春草当门生。","白发午未栉，青山时独行。","萧萧树上瓢，莫与风俱鸣。"]},{"t":"赠吴山人","f":"五言古诗","c":["昔游洞庭麓，萝阴覆君堂。","开窗湖水绿，举酒橙花香。","别来婴时网，欲济苦无梁。","东风送君至，烟霞满衣裳。","泠泠泉石谈，洗我尘土肠。","山僧忽已化，阶树今渐长。","叹息浮世事，因之念沧浪。"]},{"t":"徐学士子容薜荔园十二首 其六 蔷微洞","f":"五言律诗","c":["百丈蔷薇枝，缭绕成洞房。","密叶翠帷重，秾花红锦张。","对著玉局棋，遣此朱夏长。","香云落衣袂，一月留馀芳。"]},{"t":"徐学士子容薜荔园十二首 其八 柏屏","f":"五言律诗","c":["壁立青玉屏，下见古柏根。","相怜岁寒叶，郁作苍云屯。","贞姿洗霜雪，老气横乾坤。","名园非此种，谁可当君门。"]},{"t":"徐学士子容薜荔园十二首 其四 蕉石亭","f":"五言律诗","c":["怪石如笔格，上植蕉叶青。","苍然太古色，得尔增娉婷。","欲携一斗墨，叶底书《黄庭》。","拂拭坐盘薄，风雨秋冥冥。"]},{"t":"和泾川公纳凉以五平属上去入声作三诗 其一","f":"五言古诗","c":["烦心如枯鱼，展转想斗水。","凉飙从西来，猛雨爽我耳。","初临前轩看，返洒已满几。","青松披鲜云，野景晚转美。","庭花瑶簪长，韡韡拟缟李。","谁怀逢秋悲，且展解暑喜。","泾川神仙才，匪与朽腐比。","新辞敷烟霞，缥缈起短纸。"]},{"t":"和泾川公纳凉以五平属上去入声作三诗 其二","f":"五言古诗","c":["劳劳南州符，讵遂闭户卧。","休衙经旬居，茂树恣意坐。","生涯嗟蓬飘，世事付甑破。","民忧疮弥深，岁序梦易过。","江鸥邀东还，戏棹见万个。","长风驱洪波，聚散互荡簸。","高人逃深岩，静啸厌众和。","阳城何其愚，计驾奏下课。"]},{"t":"和泾川公纳凉以五平属上去入声作三诗 其三","f":"五言古诗","c":["蓬莱从灵仙，绝粒食白石。","何如临清秋，忽释触热厄。","江云翻鸣涛，洑沫雪一尺。","疏篁摇凉飔，隔屋叶摵摵。","清泠留侯居，月阁辟七夕。","陶情时开尊，博剧或设弈。","伊余婴离忧，契阔薄物役。","公毋怀南征，卒乞别北客。"]},{"t":"答徐昌谷博士","f":"七言律诗","c":["前年共饮燕京酒，高楼雪花三尺厚。","酣歌彻夜惊四邻，世事浮沉果何有。","一为法吏少书来，心结愁云惨不开。","昨传学省移新籍，坐啸空斋日几回。"]},{"t":"周别驾宅看花","f":"七言古诗","c":["周侯方庭大如案，四叙种花香不断。","日高散衙一事无，手汲清池自浇灌。","鲜英的皪赤瑛珠，密萼纷披紫丝幔。","芳根异种多难识，粉蝶黄蜂暗相唤。","西邻迂叟饶闲情，叩户时来索花看。","一来一醉酒千钟，月俸依稀费多半。","君侯莫厌频来过，人生乐少忧患多。","与君聚散同落叶，不醉花前将奈何。"]},{"t":"张司徒所画山国图歌","f":"古风","c":["滇南一道盘云上，永昌巍巍更相望。","水流直下洱海深，陆地夫容矗相向。","小石纷磊磊，大石高盘陀。","连空互撑叠，仰睇青嵯峨。","攒峰插牛斗，飞涧悬天河。","崩崖倾断下无地，但见猿猱挂罥号烟萝。","丹砂空青，的皪岩阿。","宝玉夜烱，灵光荡摩。","天门洞开，紫宫逶迤。","玉女对侍，星官骈罗。","至高之极始见此，辽绝下奈诸方何。","马蹄缄铁尚不得度，行人跛鳖焉能过。","我生水国多见水，不图山高乃如此。","画家山水贵相半，吁嗟谁悉寰区理。","南园大老司徒公，维山降神为世雄。","晚张能事发新格，尽吐磈礧之心胸。","引缣迅扫鸣长风，颠林倒壑貌不同。","苍云黯惨喧霹雳，白日照耀开鸿濛。","蛟龙盘拿古木死，蝀螮漂疾飞梁通。","千峦万嶂堆墨华，忽然平旷披风沙。","楪榆开凿巂君国，桃源点缀秦人家。","孤城四面削玄壁，危楼仄立明丹霞。","时清颇知官府静，化远亦爱蛮夷嘉。","老翁戏猎逐黄犬，娇女明妆簪素花。","形胜分明在指顾，风俗想像增咨嗟。","腾冲靡莫馀千里，部落微茫分远迩。","更挥淡墨洒馀姿，遂使天涯穷尺纸。","昨逢伯子示此图，瞠目惊叹从前无。","乃知山岳气磅礴，不用滥漫谈江湖。","今之好山有二老，太原司马吴门都。","见此寄书定相索，公乎公乎须写数本万里络绎传吾徒。"]},{"t":"八月十三夜与文济时范质甫城西泛舟达秦淮三首 其一","f":"五言律诗","c":["落日清川里，轻风已自凉。","秋怀生白舫，山翠扑胡床。","问路疑天上，停杯待月光。","何人横铁笛，吹过斗牛傍。"]},{"t":"八月十三夜与文济时范质甫城西泛舟达秦淮三首 其二","f":"五言律诗","c":["六代烟华地，狂歌得夜游。","山河横王气，水月弄清秋。","木落长干寺，云残太白楼。","共君须痛饮，沉醉傍沧洲。"]},{"t":"吴都台东湖书屋八首 其二","f":"五言律诗","c":["水汇苍梧郭，天开绿野堂。","云山秋滴翠，冰井夏生凉。","药满寻诗径，花垂点易床。","少须康济罢，散发任徜徉。"]},{"t":"赠何司空子元","f":"五言律诗","c":["白日难回照，丹心尽此生。","司空官岂左，集议礼多名。","国是归牵引，皇衷自圣明。","玉阶沾泣日，真见老臣情。"]},{"t":"赠徐堂","f":"五言律诗","c":["小阮龙驹子，长途拂剑归。","毗陵三尺雪，寒满黑貂衣。","骨肉行踪散，风尘客鬓稀。","平原招不起，豪士竟谁依。"]},{"t":"除夕和边太常庭实","f":"五言律诗","c":["守岁椒盘宴，欢然傍老亲。","诵诗从稚子，分肉遍邻人。","菽水惭三釜，柴荆寄一身。","青灯能送喜，金蕊夜开频。"]},{"t":"正旦","f":"五言律诗","c":["乾坤仍献岁，车骑正归休。","礼乐今王作，门庭旧客留。","老馀耽酒癖，贫有卖书谋。","所愿皇舆正，吾生岂浪愁。"]},{"t":"宿宜兴东坡祠下","f":"五言律诗","c":["先生聊一念，遗庙竟千年。","不返辽东鹤，长悲阳羡田。","月高群木影，人语一溪烟。","世事皆春梦，吾今且醉眠。"]},{"t":"赠子鱼","f":"五言律诗","c":["与子三年别，重来鬓已苍。","论心风雨夕，下榻水云乡。","画阁灯花煖，秋杯竹叶凉。","匆匆行止意，相对两彷徨。"]},{"t":"共泛东潭饯望之","f":"五言律诗","c":["高人同野兴，移棹水西东。","岸仄垂萝古，沙虚积蓼红。","哀筝悽断壑，轻帻倚秋风。","更有浮萍感，俱忘痛饮中。"]},{"t":"庚辰元日","f":"七言律诗","c":["诸侯玉帛会长安，天子旌旗下楚关。","共想正元趋紫殿，翻劳边将从金鞍。","沧江饮马波先静，黄竹回銮雪正乾。","北极巍巍天咫尺，五云长护凤楼寒。"]},{"t":"春忆野亭少傅","f":"七言律诗","c":["夷门回首限风烟，遥夜天涯有梦悬。","颂德敢言三代下，受恩今忆十年前。","安危海内占容鬓，贫乏山中倚俸钱。","早晚上书辞郡绂，野堂还借片云眠。"]},{"t":"侯城里 其一","f":"七言律诗","c":["万壑千厓控海门，愁云不散昼长昏。","王裒枉积林间泪，荀息难招阙下魂。","直以孤忠悬日月，不劳遗草落乾坤。","椒浆欲奠知何处，古木含风自吐吞。"]},{"t":"侯城里 其二","f":"七言律诗","c":["一点麻衣入帝庭，九天风雨昼冥冥。","云迷杜宇游魂黑，草染苌弘野血青。","四海衣冠收节槩，万年宗社属神灵。","英雄已去心难死，长倚南箕化列星。"]},{"t":"寄许州七弟瑮","f":"七言律诗","c":["千官扈从羡能文，谪牧新声天下闻。","落魄吾家苏季子，风流南郡小冯君。","鱼龙路怯黄河险，鸿雁声愁碧海分。","莫上吹台瞻越峤，五湖回首隔重云。"]},{"t":"登清凉寺后西塞山亭四首 其二","f":"七言律诗","c":["晚上高亭对落晖，万山寒翠湿秋衣。","江流一道杯中泻，云树千门鸟外微。","古寺频来僧尽老，重阳欲近蟹争肥。","霜枫恶作萧条色，故弄残红绕客飞。"]},{"t":"试院呈同事陶判府","f":"七言律诗","c":["归心遥下楚江东，尘鞅犹牵粤徼中。","兴在山林如倦鸟，老持文墨愧雕虫。","流光坐数经檐日，秋思争随落叶风。","不有多情陶判府，雅唫高论与谁同。"]},{"t":"归自灌阳望湘山口占","f":"五言绝句","c":["十日别湘山，见如故人面。","何况石头城，是侬旧乡县。"]},{"t":"遣怀绝句 其一","f":"五言绝句","c":["月落猿声苦，风高虎气腥。","山雷春送雪，江雾夜藏星。"]},{"t":"遣怀绝句 其二","f":"五言绝句","c":["花豹金钱背，文鹇蜀锦毛。","厨泉山笕细，江稻水车高。"]},{"t":"遣怀绝句 其三","f":"五言绝句","c":["猺女招歌剧，蛮郎步射强。","花环垂耳大，竹弩挂腰长。"]},{"t":"遣怀绝句 其四","f":"五言绝句","c":["涧冷菖蒲翠，山春踯躅红。","草惊秋尽火，树厌夜深风。"]},{"t":"遣怀绝句 其五","f":"五言绝句","c":["夜静云生室，春深水到门。","松高多绣顶，兰古自悬根。"]},{"t":"遣怀绝句 其六","f":"五言绝句","c":["野鲜苍兕猛，山鲊鹧鸪香。","市笋挦苞出，仓禾带把藏。"]},{"t":"遣怀绝句 其七","f":"五言绝句","c":["不忌枭鸱暮，何悲杜宇春。","蛩催三月织，鸡报二更晨。"]},{"t":"山行绝句十三首 其十二","f":"五言绝句","c":["槎枒半折树，倾欹欲堕石。","行人如飞仙，渺渺下青壁。"]},{"t":"寄和赵户曹叔鸣西寺游瞩二首 其一","f":"七言律诗","c":["水香花气凤楼西，宿雨初晴御苑泥。","万柳晓含萧寺暗，五云春压汉宫低。","行经绣陌啼莺满，回望苍郊远树齐。","独念江南愁病客，竹窗斜月卧闻鸡。"]},{"t":"度枫木岭","f":"五言古诗","c":["初谓山拂天，飞鸟不可度。","逡巡蹑危磴，乃即我行路。","百折顿攀援，十步九回顾。","高林忽在下，衣襟有云雾。","倒景犹照人，平地黯将暮。","方当日月过，似可捉乌兔。","飞瀑如天河，所少鹊成渡。","东北望故乡，江流莽倾注。","长风动万里，独立难久伫。"]},{"t":"蕉溪岭","f":"五言古诗","c":["蕉岭何嵯峨，峻极侵汉耸。","岩峦势崚嶒，草树影蒙茸。","羊肠仄径回，螺髻尖峰拥。","危讶天与摧，突疑地俄肿。","曦轮仅平过，星纬翻下拱。","罡风劲而冲，游气蓊以壅。","循厓必蹲躬，蹑级难举踵。","联升贯行蚁，疲卧缩僵蛹。","高隼翮每抢，健马息亦恿。","韩愈岂虚哀，王尊乃真勇。","轻舆苦陟降，牵掣资众捧。","虽谢脢腓劳，屡动毛发竦。","昏黄履坦道，虩虩抱馀恐。"]},{"t":"宿排山道院二首 其一","f":"五言律诗","c":["苦厌尘缨缚，欢投道院清。","不逢黄石异，惟见紫芝荣。","涧水增茶品，山光冷宦情。","寒宵得洗耳，金磬杂经声。"]},{"t":"宿排山道院二首 其二","f":"五言律诗","c":["动静不可执，山深生暗喧。","霜寒警怨鹤，风远啸哀猿。","供饭誇云子，为官号漆园。","儒家衡斗政，莫与道人言。"]},{"t":"入宝庆","f":"五言律诗","c":["林稠庐落聚，垄断路岐分。","旷野迎迟日，长天失过云。","金汤城据险，斥堠野屯军。","长吏岑曦似，边笳夜不闻。"]},{"t":"武冈道中雨二首 其一","f":"五言律诗","c":["界石记州名，旗亭报客程。","山行频陟降，春雨易阴晴。","树引荒涂直，花撩客眼明。","蛮方行欲捲，翻忆武昌城。"]},{"t":"初出岳阳期登岳有赋","f":"七言律诗","c":["浮湘未了岳峰缘，梦寐烟霄二十年。","问俗再游荆楚路，乘风须到祝融颠。","神驰沧海看红日，路指朱陵上碧天。","赤帝肯分宾友席，莫教云雨暗山川。"]},{"t":"宿云开堂","f":"七言律诗","c":["难逢魏母彩鸾车，聊试弥明石鼎茶。","翠羽金支云缥缈，紫厓丹洞石㟏岈。","五峰黛色消晴雪，万木灵晖散晚霞。","愿借双公玄鹤羽，月明骑上太清家。"]},{"t":"半山亭","f":"七言律诗","c":["云为衣履石为梯，白日青虚步可跻。","天近祗疑三界合，烟开浑见四方低。","寒松挂雪明前嶂，瀑水轰雷下别溪。","早晚台端捐佩去，诛茆来与道人栖。"]},{"t":"晚投高楼寺读石沙王侍御诗爱其奇戏拟四韵","f":"七言律诗","c":["乘春问俗行何远，望寺停车兴亦奇。","激涧水喧高下石，晚林鸦竞后先枝。","岩藏峭阁鸣钟隐，雨湿流云出树迟。","一样江南风景好，踏青难共美人期。"]},{"t":"出靖州","f":"七言律诗","c":["黄鹤秋云已隔年，五溪春色异风烟。","池心溅墨生科斗，花血流红绽杜鹃。","孤负江南挑菜会，了还天外挂弓缘。","比来湿病全抛酒，且喜家贫省秫田。"]},{"t":"松坞草堂新成杂兴十二首 其二","f":"七言律诗","c":["野日迟迟阴更晴，山人睡起絮袍轻。","松稍宿露因风堕，草际浮云傍水生。","一壑无多堪独往，百年强半复何营。","神仙服食长相误，不及清尊对客倾。"]},{"t":"松坞草堂新成杂兴十二首 其七","f":"七言律诗","c":["衰年多病自宜休，避地栖岩事事幽。","风槛落花催酿酒，雨窗啼鸟唤梳头。","柴桑剩著陶元亮，款段何孤马少游。","野衲村翁俱接近，茗杯香篆足淹留。"]},{"t":"松坞草堂新成杂兴十二首 其十","f":"七言律诗","c":["郭外新移野老家，旧书犹载两牛车。","樽空北海虚耽酒，地薄东陵漫种瓜。","小径冲门分野竹，短篱临水透溪花。","优游行乐元无尽，落魄浮生讵有涯。"]},{"t":"松坞草堂新成杂兴十二首 其十二","f":"七言律诗","c":["手种桃花傍短墙，老人殊自爱年芳。","风晴数蝶穿红蕊，日出孤莺啭绿杨。","薄饭时兼芝菌味，春衣浑带薜萝香。","前朝戴墅知何处，芳草还生麋鹿场。"]},{"t":"同陈鲁南雨饮永宁寺","f":"七言律诗","c":["南山飞雨滴残卮，野寺鸣钟客散迟。","醉眼耐薰红杏色，韶华催换绿杨丝。","衰年感旧重重恨，故苑寻春步步宜。","拟上花台观淑景，湿云横路正低垂。"]},{"t":"游丘常侍山园二首 其二","f":"七言律诗","c":["采芝深谷赋归休，幸有邻庄水竹幽。","画障日开山九叠，素封秋倚橘千头。","长悬片月延僧住，满放闲云伴客游。","桐叶已齐春去久，翻阶红药为谁留。"]},{"t":"山庄即事和周子庚","f":"七言律诗","c":["十年无梦到东周，坦腹高眠杜若洲。","狂吐肺肠投瓮盎，老持骸骨付菟裘。","当楼月上山回昼，接畛风鸣麦弄秋。","笑坐胡床歌散调，不须吹笛也风流。"]},{"t":"漫吟","f":"七言律诗","c":["万事浮云莫问天，发毛元解记流年。","春秋按节投花种，儿女分畦理芋田。","辟地多方求怪石，买山初意为流泉。","城闉自古称佳丽，独笑先生野性偏。"]},{"t":"柴门","f":"七言律诗","c":["翠盖平遮松柏林，画屏分映两青岑。","坐收粳稻三秋色，行踏垂杨一径阴。","雨突烟沈人卧稳，风帘花落燕巢深。","幸无奇字藏书箧，不惹輶轩使者寻。"]},{"t":"摸鱼儿 十二月十四日自衡入永","f":"古风","c":["远山低、半留残雪，望中清景殊绝。","寒云渐逐西风散，村落午烟摇曳。","行路客。","被簿领沈迷，又度隆寒月。","岁尽阳回，何日是春来，早梅花萼，看透几分白。","忆江左，多少关河分隔。","异乡空望明月。","衡阳飞雁都回矣，欲寄音书那得。","情如结。","更断酒抛诗，幽恨凭谁说。","霜髯雪鬓，不奈老年华，禾畦麦垄，觅取旧生业。"]},{"t":"临江仙 雨中柬谭子羽","f":"古风","c":["抱病登楼无意绪，满城寒雨濛濛。","一樽何日与君同。","捲帘芳草碧，呼酒夕阳红。","堪恨赏心多不偶，依然枉却东风。","扁舟归兴莫匆匆。","江梅他自落，别有海棠丛。"]},{"t":"金山寺 其一","f":"五言律诗","c":["俯槛江心寺，涛声两带分。","天晴秋见海，山润午生云。","短棹今重到，名泉昔有闻。","西风吹别酒，斜日未成醺。"]},{"t":"金山寺 其二","f":"五言律诗","c":["云雾空江水，维舟陟翠岑。","坤灵开别岛，佛界净空林。","岩洞攀跻险，鱼龙窟宅深。","行逢黄叶下，秋思转萧森。"]},{"t":"虎邱寺","f":"五言古诗","c":["远游访名山，虎邱得初陟。","溪门乍深隐，石径转崔嶪。","阴壑注鸣泉，风林振疏叶。","岩僧解将引，探古恣幽蹑。","波沉贞娘魂，灰冷生公业。","伤哉剑池名，祗见寒流渫。","酹酒呼干将，千秋激豪侠。"]},{"t":"石湖同陈亨父汎饮","f":"五言古诗","c":["浩渺石湖水，泛舟宜素秋。","群山倒波下，树拂青天流。","白日光荡潏，蛟龙互沉浮。","长风激箫鼓，放歌销人愁。","觞行金逶迤，鸾刀荐群羞。","请君但酣饮，岁月不我留。","越城空黄土，范碑委榛邱。","陵谷恒变易，顾之增烦忧。"]},{"t":"吕翁南庄","f":"五言律诗","c":["渔樵三五户，恬淡自成村。","乱竹深藏宅，平田近绕门。","松高巢水鹤，花老过河豚。","长醉丰年酒，还思零雨恩。"]},{"t":"苕溪同刘西安元瑞话旧并棹至武林港别去 其一","f":"五言律诗","c":["念子苕溪上，孤舟远过从。","去乡身万里，对酒意千重。","岁计看秋稼，离心寄晓钟。","柴荆期白首，何日定行踪。"]},{"t":"苕溪同刘西安元瑞话旧并棹至武林港别去 其二","f":"五言律诗","c":["良晤殊方重，交情晚岁深。","两溪秋并棹，孤烛夜论心。","谑浪输肝胆，飘蓬变语音。","因悲辞骨肉，转忆向山林。"]},{"t":"岘山浮碧亭呈黄湖州子和","f":"七言律诗","c":["平湖短棹镜中来，翠岫红亭罨画开。","雾树散分洲渚断，云峰横带海天回。","登高共续黄花节，藉草仍探白石杯。","传道使君多暇日，每携宾从恣徘徊。"]},{"t":"西湖","f":"五言古诗","c":["群山窈回合，豁尔开洪区。","澄波汇且广，宛在都城隅。","灵秀自天辟，台观绝世无。","虹桥荫芳树，烟渚发红蕖。","兰桡斗转捷，越女夸容姝。","莲歌荡人心，挥金盛中厨。","靡靡即欢宴，岂遑顾菑畬。","但苦白日暮，西风吹水枯。"]},{"t":"游静慈寺因访孙山人一元","f":"五言古诗","c":["晨游招提境，爱此幽胜偏。","南山峙其后，西湖漾其前。","华标凌波起，邃阁承崖悬。","修竹挺寒翠，长松濯秋鲜。","岂惟会禅悦，亦以招灵仙。","吾生厌尘网，久怀奉真诠。","刀圭脱相授，情爱亦易捐。","攀援洪厓侣，翱翔凌紫烟。"]},{"t":"孤山","f":"五言古诗","c":["孤山葱而郁，仰止林逋宅。","舍舟入荒蹊，森森荫松柏。","往代云龙会，夫子戢鸿翮。","皋夔道已沉，巢许心所获。","岂无桃李颜，寒梅自贞白。","皎皎空谷遗，长愧缨冕客。","西瞻岳山坟，悽其暮烟碧。"]},{"t":"灵隐寺","f":"古风","c":["水泛趣已绵，山行路仍窈。","迤?经层峦，花宫冠林杪。","峭壁槩微霄，下映楼观小。","崖倾树孤撑，亭远泉重缭。","萧条僧气閒，肃穆人声悄。","来游属秋暮，蕉叶青袅袅。","入径薰名香，憩涧狎幽鸟。","顾瞻桃源幽，捐佩苦不早。","寄言都城子，来者一何少。","诛茅傥吾遂，庶离寰中扰。"]},{"t":"飞来峰","f":"五言古诗","c":["灵峰自何来，嵚嵜待苍凤。","羽翮不肯敛，时时欲飞动。","海云结轮囷，㟏岈互勾控。","虚房缀悬蜂，横梁亘垂蝀。","巨灵苦雕削，真宰资玩弄。","初临侧躬入，稍深复轩洞。","蹈危若浮槎，瞰空疑覆瓮。","洼深日影坠，谷转风驭送。","阴森絺衣寒，踯躅芒履重。","班荆趺旧席，剜苔纪新颂。","归来眠不稳，一夜劳噩梦。"]},{"t":"岳王坟","f":"五言古诗","c":["崔巍中兴业，浩荡英雄才。","刺身誓日月，驱甲鸣风雷。","艰哉朱仙镇，天地划再开。","君王亦何意，自卷旌旗回。","中原本吾土，突骑胡为来。","家昏鬼蜮啸，国破长城摧。","宰木空南向，厓山益悲哀。","举觞酹宿莽，歌罢魂俱颓。"]},{"t":"桐庐江行寄汪佥宪一夔","f":"五言古诗","c":["晓发富春渚，暮望桐庐宿。","江空寒水净，岸转云峰矗。","孤帆缅逶迤，霁景聊寓目。","渺渺沙际村，浮烟霭丛木。","垂岩杞菊班，覆垄禾黍熟。","兹方静无虞，生理见耕牧。","高贤涖行台，敷政况清肃。","眷尔鸿雁居，幸脱豺虎毒。","沉忧正浩荡，且用慰心曲。"]},{"t":"严子陵祠","f":"七言律诗","c":["垂纶客去今千载，犹见高台对碧流。","几户蓬茅馀凤种，万方戈甲一羊裘。","天空大泽星辰动，露下秋山草木愁。","岂料平生逃绂冕，却遗名姓在乡州。"]},{"t":"常山道中 其一","f":"五言律诗","c":["旅况逢秋尽，山行叹路赊。","旱来无野渡，乱后少人家。","橘柚寒多实，夫容晚自华。","愁云黯无极，肠断楚天涯。"]},{"t":"常山道中 其二","f":"五言律诗","c":["迢递常山道，千岩落木风。","客程忧患里，秋色乱离中。","问俗嗟生理，逢人说战功。","伤心乌桕叶，默默不禁红。"]},{"t":"泊弋阳溪","f":"五言律诗","c":["孤帆逗何处，残月弋阳溪。","晚水澹相照，寒鸦惊自啼。","远游惭薄养，多病忆幽栖。","岂是怀荣禄，来过楚水西。"]},{"t":"寄广信朱太守亨之","f":"七言律诗","c":["南州腰笏始经年，美政相传过昔贤。","洞寇买牛捐带剑，野人无吏索租钱。","霜前禾黍孤城雨，月下弦歌万井烟。","惭愧樗材亦何用，皇恩又遣到湘川。"]},{"t":"雨中溪行杂诗 其一","f":"五言绝句","c":["十日溪中舟，格格响溪石。","孤篷过鸣雨，忽失沙上脊。"]},{"t":"雨中溪行杂诗 其二","f":"五言绝句","c":["暮雨寒溪急，秋烟远岫微。","扁舟冲浪去，何日顺潮归。"]},{"t":"雨中溪行杂诗 其三","f":"五言绝句","c":["暮程投野镇，逆旅恋乡人。","怕有金陵客，逢舟借问津。"]},{"t":"雨中溪行杂诗 其四","f":"五言绝句","c":["悬薄者谁室，宛在水边居。","停舟试借问，高人或姓徐。"]},{"t":"雨中溪行杂诗 其五","f":"五言绝句","c":["秋容殊可悦，客棹且须迟。","霜叶飞红雨，烟岑抹黛眉。"]},{"t":"雨中溪行杂诗 其六","f":"五言绝句","c":["小舟乱如叶，沉雅深渊中。","衔鱼自飞起，不敢惊蛟龙。"]},{"t":"雨中溪行杂诗 其七","f":"五言绝句","c":["尽知为客恶，还见别家多。","风雨空愁在，山林奈晚何。"]},{"t":"雨中溪行杂诗 其八","f":"五言绝句","c":["楚天寒信迟，况入小春月。","冉冉横山烟，青青缀林叶。"]},{"t":"雨中溪行杂诗 其九","f":"五言绝句","c":["远客经时节，孤舟积雨寒。","无心争道路，嬴得梦魂安。"]},{"t":"雨中溪行杂诗 其十","f":"五言绝句","c":["沧波生暮霭，渺渺钓船归。","细雨寒蓑重，斜风并棹稀。"]},{"t":"雨中溪行杂诗 其十一","f":"五言绝句","c":["艰难伤物役，澹泊爱舟居。","晚饭客遗酒，夜灯儿读书。"]},{"t":"雨中溪行杂诗 其十二","f":"五言绝句","c":["云断雨声歇，水清天影流。","苦吟双短鬓，高枕一扁舟。"]},{"t":"雨中溪行杂诗 其十三","f":"五言绝句","c":["山水行踪美，风霜岁序阑。","高堂遥送喜，游子且加餐。"]},{"t":"雨中溪行杂诗 其十四","f":"五言绝句","c":["日暮争渡喧，天阴野风急。","孤客来何迟，萧萧荷锄立。"]},{"t":"雨中溪行杂诗 其十五","f":"五言绝句","c":["晚云横树薄，寒雨入帘微。","川净鱼堪数，人间鹭不飞。"]},{"t":"过馀干","f":"七言律诗","c":["古城云暝草萧萧，废井人稀昼寂寥。","三户凋零伤旧楚，百年熙皞忆先朝。","江头白骨乌鸢噪，洞里黄巾虎豹骄。","闻道将军饶战略，不应多垒遍苍郊。"]},{"t":"独吟 其一","f":"七言律诗","c":["湘浦孤舟玉露寒，戌楼鸣鼓烛花残。","青云怅望孙弘阁，白首飘零子夏冠。","秋梦过家惟伏枕，月华临水独凭栏。","参差欲就淮南隐，已见山中桂树团。"]},{"t":"独吟 其二","f":"七言律诗","c":["平川渺渺客愁生，极浦丹枫映晚晴。","江水正连杨子渡，离人何赖楚歌声。","天涯一郡空劳梦，云里千峰不辨名。","长路栖迟阳月尽，繁霜摇落瘴烟清。"]},{"t":"独吟 其三","f":"七言律诗","c":["戎马中原鬓已华，一麾迢递向天涯。","荒城白屋犹征税，故国青山更别家。","秋梦南归江汉阔，暮程西望斗牛斜。","扁舟独宿空滩冷，野戌悲风急夜笳。"]},{"t":"章江留别李宪副献吉屠少参文魁","f":"五言古诗","c":["恻恻伤远别，眷此清江流。","悲风激长薄，浮云隐重洲。","去家邈千里，惘然增百忧。","弭棹适洪都，果谐心所求。","良友始邂逅，道言互赓酬。","感叹风波事，委曲舟车谋。","倾觞远饯送，毕景情未休。","嘉晤殊慰悦，旅泊何淹留。"]},{"t":"豫章江上逢方大参文玉","f":"七言古诗","c":["瓷罂酒湛碧玉浆，雕盘鸡割黄金肪。","故人停舟劝我饮，捲帘四座临苍茫。","江山信美客抱豁，白日未午空罍觞。","气酣谈剧增叹息，悲歌起舞江云黄。","忆昔先朝侍东署，冠簪济济朝明堂。","芝兰閒馆重交结，金玉艺苑腾文章。","一朝风尘忽澒洞，故旧转盼多凋伤。","纷纭群盗乱中土，大夫负剑从戎行。","与君相逢江水上，值予憔悴流南荒。","赠予荆南玉练纸，相邀作赋庐山阳。","羁怀龌龊那能尔，明朝拂曙下潇湘。"]},{"t":"临江丛竹间虎","f":"古风","c":["西林白日暮，溪上无村坞。","牵夫仓皇啼入舟，幽丛虓虎几噬汝。","舣舟侧望白额狞，双睛㸌电对人怒。","吁嗟尔虎太不武，近渚鼋鼍肉磈礨，岩穴豺狼饱而舞。","尔何不往搏食之，顾来溪头惊我小儿女。","惜哉我无蛇弓雕羽箭，一发毙尔腊为脯。","呜呼豫章猛士千百群，安知无一李将军。"]},{"t":"暮泛秀江 其一","f":"五言律诗","c":["桂岭望何极，孤舟行转迷。","秀江斜景里，衡岳乱云西。","宿雁冲帆起，哀猿傍客啼。","多愁厌乡梦，夜坐听鸣鸡。"]},{"t":"暮泛秀江 其二","f":"五言律诗","c":["游梁方失意，适楚更悠悠。","寒野牛羊夕，空江雁鹜秋。","腐儒悲末路，幽兴狎扁舟。","欲向桃花水，垂纶待白头。"]},{"t":"暮泛秀江 其三","f":"五言律诗","c":["路转清江外，舟移锦石中。","爪香分绿橘，目艳对丹枫。","检药防山瘴，陈诗叙国风。","冒霜梳短发，应愧鹿门翁。"]},{"t":"暮泛秀江 其四","f":"五言律诗","c":["石壁攒江狭，风樯逆浪飞。","渐看湘国近，转与客心违。","芳桂临波发，遥岑隔雾微。","明妆浣纱女，妍笑竞斜晖。"]},{"t":"暮泛秀江 其五","f":"五言律诗","c":["蓬舠依濑转，筦簟枕肱眠。","急浪鸣舷过，危峰就幕悬。","茭蒲时碍楫，鱼鳖不论钱。","自喜幽襟洽，浑忘物役牵。"]},{"t":"严太史惟中东堂","f":"七言律诗","c":["新堂诛茅仍故墟，寒溪度郭鸣阶除。","春风入帘语巢燕，朝日映户坐看书。","酒熟时来长者辙，山深何厌廛中居。","诗筒独驱一黄犬，尘壁宛挂双银鱼。"]},{"t":"宣风馆题壁和王大伯安","f":"七言律诗","c":["候馆哦诗销烛痕，地炉煮茗恶溪浑。","叩门乞火有邻父，打鼓报更还近村。","仲冬寂寂野霜落，残更凄凄山月昏。","苦遭砧杵远相聒，独忆故园伤旅魂。"]},{"t":"浯溪","f":"五言古诗","c":["系舟浯溪下，策杖登崇台。","嵚崟石壁古，手拨苍云开。","娲皇彩烟灭，遗此青瑶瑰。","元公性奇崛，首发雕锼灾。","灵光落台斗，照耀衡湘隈。","白日映寒野，旷望江流回。","山僧指陈迹，故宅久已灰。","污尊依然好，饮者安在哉。","感叹惜形役，长歌下崔嵬。"]},{"t":"初至全州","f":"五言古诗","c":["跋涉既累月，始闻及清湘。","长风卷舟幕，忽见湘山苍。","黄发数老叟，迎予具壶浆。","面色颇黧瘦，草际各跄跄。","拜起问生理，辄言困兵荒。","云望使君至，冀免沟壑殃。","我闻老叟言，垂涕意彷徨。","比岁牧梁宋，兵戈剧流亡。","逮此越万里，民瘼乃同方。","忆昔始观国，徒行不赍粮。","皇舆非改辙，惠泽恒汪洋。","闵兹丰俭故，所罪吏非良。","噬肤遂及髓，割肉救疮疡。","天高不能愬，仰失日月光。","矧予既朽废，岂有仁风扬。","登途入城府，恻恻心自伤。"]},{"t":"答孟望之侍御时谪桂林郡博","f":"七言律诗","c":["燕台对酒感离群，麓口移舟更失君。","万里飘零同落叶，孤城惆怅各停云。","书回桂水交情切，人对星岩藻思芬。","遥想高斋长隐几，应怜案牍日纷纭。"]},{"t":"积雪 其一","f":"五言律诗","c":["楚水浮烟敛，湘山积雪晴。","瑶华垂古木，素月满寒城。","吏散公庭静，溪喧客棹轻。","仆夫早严驾，吾欲访袁生。"]},{"t":"积雪 其二","f":"五言律诗","c":["南雪旧希见，苦寒今乍逢。","空林愁虎豹，积水喜鱼龙。","瘴疠全宽客，祯祥复慰农。","千山如削玉，长望倚庭松。"]},{"t":"再答孟侍御期予入桂林之作","f":"七言律诗","c":["春风桂岭忆同游，腊雪湘江独倚楼。","星汉依微天北极，岁华摇落水东流。","山藏散吏衣冠懒，云掩荒城鼓角愁。","正月望君骢马色，纫兰搴芷共淹留。"]},{"t":"除夕喜金曼甫至","f":"七言律诗","c":["天涯除夕倍凄然，客舍逢君转自怜。","瘴海风霜凋旧质，荒城鸡黍对新年。","来时闾井人多换，谪地音书雁少传。","华胄正须扬藻业，腐儒惟欲傍瓜田。"]},{"t":"同金曼甫饮儿屿呈诗乃和之 其一","f":"五言律诗","c":["圣世思柔远，孤臣敢爱身。","中年为客倦，寒梦到家频。","道废伤新岁，颜衰愧古人。","乡园今万里，梅蕊为谁春。"]},{"t":"同金曼甫饮儿屿呈诗乃和之 其二","f":"五言律诗","c":["杜陵飘泊日，骥子远游身。","夜读居家惯，羁吟对客频。","流年非孺子，乡国有贤人。","桃李无贞性，繁华祗竞春。"]},{"t":"上元十二夜饮蒋方伯诚之第观灯","f":"古风","c":["日色渐落天宇澄，月华滟滟东方升。","锦堂鸣钟集嘉客，玳筵珠履纷相承。","饮君天台沆瀣之玉醴，观君钱唐错采之华灯。","佳辰高会感人意，清歌绕梁乐何胜。","君家贵盛不可言，于今海内称德门。","公居岳牧领全蜀，次公秉钧调化元。","英雄想望见颜色，愧我流落叨攀援。","歌牛枉侧桓公听，弃马虚伤田子魂。","青云轗轲徒垂翅，白日留连且举樽。","公将整驾登西路，予亦怀乡欲归去。","共惜相逢不可长，它年一笑知何处。"]},{"t":"春日寄徐伯川兼柬孟侍御","f":"七言律诗","c":["寻花东郭傍残曛，伐木空山动鸟群。","高士难逢徐孺子，故人犹恋孟尝君。","虚疑鬓发经年老，屡喜诗篇向客闻。","已办盘飧开竹径，会须车马驻江濆。"]},{"t":"正月乡饮赋一首","f":"五言古诗","c":["国典崇先训，礼饮及元辰。","鼓钟閟宫间，乐兹黄发宾。","牺尊湛醇醴，肴核旅百陈。","鹿鸣侑行爵，献拜敷皇仁。","缅彼虞周代，养老叙彝伦。","执匕躬馈酱，天子屈其尊。","四海渐美俗，负戴不及亲。","蹇予负明谴，具位牧斯民。","顾惭唯风德，何能冀兴仁。","爰申孝弟义，庶以诏邦人。"]},{"t":"湘山初游","f":"七言律诗","c":["湘国湘山天下稀，青春幽览历岩扉。","云疏列岫攒空起，雨歇新泉出树飞。","石势参差依酒案，佛香清净绕人衣。","南迁得就长歌地，不用凭高叹未归。"]},{"t":"春思 其一","f":"七言绝句","c":["正月湘南春可怜，李花如雪柳垂烟。","殊乡剩借芳菲节，莫向东风惜酒钱。"]},{"t":"春思 其二","f":"七言绝句","c":["粟家渡头春草齐，柳侯祠下早莺啼。","傍人莫笑山公醉，请看城头白日低。"]},{"t":"春思 其三","f":"七言绝句","c":["来时江草带霜华，忽往城南杏已花。","把酒对花如建业，离人何事不思家。"]},{"t":"春思 其四","f":"七言绝句","c":["庭前古松高百尺，屈干回姿如老龙。","我欲据床还散发，簿书堆案不从容。"]},{"t":"吊宋刺史柳仲涂书院废址","f":"五言古诗","c":["昔贤政多暇，学道恒山居。","遗构俨像设，流风激乡闾。","时代屡迁易，胜观鞠为墟。","居人伐嘉树，野火灰堂庐。","有作不肯述，益叹今人疏。","始闻慕芳躅，既来乃重歔。","指顾亭台迹，叹息经营初。","林涧有馀愤，曲水但空渠。","誓将理荒秽，心远力不如。","勖哉同官客，勿俾初愿虚。"]},{"t":"送鲊孟侍御孟有歌罢无鱼之句因嘲之","f":"七言绝句","c":["广文今在桂林居，徒壁曾无担石储。","我儗封筒遥送鲊，君毋弹铗更歌鱼。"]},{"t":"春日磐石江上","f":"五言律诗","c":["历历春山色，留人坐不归。","空园花自发，芳草雉争飞。","多病怀乡切，端居出郭稀。","尘冠将白首，无乃负渔矶。"]},{"t":"夜归值雨","f":"五言律诗","c":["沉沉城郭近，咫尺路行难。","静夜千山雨，长林二月寒。","石泉惊马住，野水溅衣残。","未睹明蟾色，何因厚土乾。"]},{"t":"郡圃桃花为风雨所败","f":"七言绝句","c":["寂寞山城二月阑，桃花无数倚春寒。","可堪绰约风吹急，更著离披雨打残。"]},{"t":"游龙岩","f":"七言律诗","c":["龙飞何日起苍岑，洞壑蜿蜒窟宅深。","玉乳垂花春不尽，石田承雨昼长阴。","盘云座古留仙迹，流水声寒净客心。","拟约东风重载酒，碧桃迷路恐难寻。"]},{"t":"题龙岩额有赋","f":"五言古诗","c":["苍崖积铁古，中空若天开。","轩豁容万夫，窈曲千丈回。","不知寒泉水，潺湲自何来。","向非神龙力，山鬼空虺隤。","石田莽重叠，上有仙人台。","淋漓湿元气，玉黍长蓓蕾。","青春始来游，桃花映樽罍。","主人邀痛饮，酣歌日西颓。","独扫菁茅帚，书破岩上苔。","巨灵拍掌笑，大劫俱扬灰。","吾意在山水，短长安计哉。"]},{"t":"寄西蜀郭佥宪鲁瞻","f":"七言律诗","c":["长歌寒女素丝诗，直道难逢郭泰机。","白简威名西蜀远，青云朝省故人非。","身危独洒潇湘泪，道拙空怀草木衣。","东望乡关万馀里，归心江汉转依依。"]},{"t":"怀王车驾钦佩","f":"五言律诗","c":["落落王车驾，门庭不可私。","官联同故国，离别已多时。","艺绝围棋赋，情閒洗墨池。","唯应谢太傅，风雨共幽期。"]},{"t":"怀陈文学鲁南","f":"五言律诗","c":["金马文章署，斯人气不群。","玉阶今对策，吐论动明君。","惜别钱唐水，怀乡桂岭云。","几时书札到，踪迹慰相闻。"]},{"t":"寄罗八廷尉质甫","f":"五言律诗","c":["万里乡园地，音书望不来。","桃花三月暮，客思转悠哉。","江动卢龙树，春深凤鸟台。","时时一舟楫，遥向梦中回。"]},{"t":"古意送蒋中丞抚赣州 其一","f":"五言古诗","c":["峨峨衡山岳，奠彼朱方尊。","洪濛判清浊，屹与三光存。","旷视眇六合，泰华相弟昆。","培塿一拳石，琐细安足论。","蹇予窜南粤，始获窥㠝岏。","穷高历参井，大观惊心魂。","仰凌云汉阔，俯厌匡庐繁。","匪见东海若，讵惭河伯源。"]},{"t":"古意送蒋中丞抚赣州 其二","f":"五言古诗","c":["驺虞含利齿，噬肉不戕生。","麒麟虽有足，罔蹑春草茎。","仁者贵物命，重德靡淫刑。","中山放麑叟，乃获秉钧衡。","斯鞅屠黔首，伤哉国同倾。","茫茫楚粤会，圭组罗百城。","春阳彻幽照，草木咸敷荣。","但恐豺虎吼，鸿雁靡时宁。","我愿化咆哮，允谐鸾凤鸣。","毋遗沟壑下，恻恻吞悲声。"]},{"t":"古意送蒋中丞抚赣州 其三","f":"五言古诗","c":["直道易摧折，烈士匪阿亲。","志义苟不达，抱关甘隐沦。","往昔股肱宰，吐哺接贤人。","所以风云气，长随龙虎身。","四岳举明圣，天下称尧仁。","鲍公进仲父，齐桓霸图新。","圣朝理文化，群材登凤麟。","东方列城士，承风望车尘。","愿公广末照，勿弃舆台臣。"]},{"t":"饮柳山上 其一","f":"五言律诗","c":["白日空山静，青春结驷来。","江横群水合，野阔万峰开。","柳子弦歌室，章公射饮台。","并馀芳草色，默默对衔杯。"]},{"t":"饮柳山上 其二","f":"五言律诗","c":["把酒高台畔，青山落案前。","飞花三月雨，垂柳万株烟。","胜地堪吾醉，清风愧昔贤。","尘缨何处濯，深涧有寒泉。"]},{"t":"春日湘江偶泛 其一","f":"七言律诗","c":["春日湘江江水深，春风荡桨一开襟。","群山夹浦青无尽，芳树摇波绿更沉。","细雨忽来沾客鬓，啼莺何事响前林。","长歌漫倒清尊酒，独坐终伤异域心。"]},{"t":"春日湘江偶泛 其二","f":"七言律诗","c":["下马江亭入画船，绿波芳草媚阳天。","娟娟秀石垂萝上，泛泛轻鸥远照前。","胜赏并催幽兴发，高辞空羡古人传。","驱驰已负深春月，潦倒空悲谪宦年。"]},{"t":"首夏江上 其一","f":"七言律诗","c":["万里归心倚钓丝，空舟无伴独吟时。","江涵远树沈沈净，岸隐高帆默默移。","白发行藏愁对酒，黄尘悲喜笑观棋。","古来竹帛苍天事，惟有陶公老不疑。"]},{"t":"首夏江上 其二","f":"七言律诗","c":["不见春花忆故乡，更愁炎月滞炎方。","柴门旧对沧江迥，野服无如白苧凉。","海内形容犹道路，天涯恩泽更农桑。","何时挂却尘冠去，散发行歌与世忘。"]},{"t":"首夏江上 其三","f":"七言律诗","c":["落日子规啼近林，空江愁坐独沾襟。","古人旷放岂复及，壮岁飘零违寸心。","诏发金鸡何日到，梦投朱鸟万峰深。","青鱼白饭殊堪饱，去国辞家自不禁。"]},{"t":"同海阳舒教谕登湘山绝顶因赠别","f":"古风","c":["兀坐不快意，起登湘山头。","九疑峥嵘忽到眼，洞庭湘浦遥争流。","盘空苍磴路险绝，四月爽气疑清秋。","波涛微茫指海南，彷佛十二仙人楼。","欲行更止魂惕慄，声动河汉惊牵牛。","舒君好奇更豪宕，攀援绝壁枝撑幽。","拂拭苔花坐崖石，把酒长笑观潮州。","下窥城郭弹丸小，但听两耳风飕飗。","西瞻苍梧吊虞舜，满江泪竹湘灵愁。","尉佗孤坟竟谁是，纷纷白草埋荒邱。","忆昔楼船下南粤，连天雪甲横戈矛。","祇今陵谷已非昔，况乃杨仆诸王侯。","古今成败等翻掌，天地逆旅俱蜉蝣。","与君且醉苍玉瓯，对面但喜莫复忧。","明朝解缆灵川水，却望湘山思旧游。"]},{"t":"寄七弟英玉登科 其一","f":"五言律诗","c":["爱尔能文早，吾家玉树枝。","年居三十下，名动九重知。","礼乐开黄卷，衣冠上赤墀。","泥金遥送喜，万里慰流离。"]},{"t":"寄七弟英玉登科 其二","f":"五言律诗","c":["兹晨金马诏，复尔映蓬门。","耕读吾家业，蒐罗圣主恩。","蜚腾才岂乏，盛满戒俱存。","莫向青云上，徒惭简册言。"]},{"t":"答孟望之 其一","f":"五言律诗","c":["长忆孟夫子，题诗过郡山。","舟樯春不到，庭馆昼长閒。","瘴海身飘泊，云溪梦往还。","何时薜萝月，双照逐臣颜。"]},{"t":"答孟望之 其二","f":"五言律诗","c":["葡萄阴夏院，急雨响深更。","醉里忘乡国，天涯恋友朋。","高斋回夜爽，虚阁殷滩声。","无限幽居意，怀君百感生。"]},{"t":"夏季试诸生作","f":"五言古诗","c":["朱炎启长夏，悦兹天宇新。","公庭幸休暇，展席招儒绅。","群材竞崇术，挥毫各融神。","摛文析疑义，吐气干青旻。","皇皇宣尼业，六籍秘道真。","蠖伏继删述，龙跃思经纶。","穷达委大运，所贵在一身。","曹刘惑初驾，竟汨班马尘。","斯意倘有获，要我于迷津。"]},{"t":"磐石崖下泛舟 其一","f":"七言律诗","c":["磐石江头景殊绝，放舟幽兴几人同。","风飘鼓角晴波外，雨洗峰峦夕照中。","狼籍椰樽浮酒白，清泠冰碗削瓜红。","寻僧更访山腰阁，半醉题诗峭壁东。"]},{"t":"磐石崖下泛舟 其二","f":"七言律诗","c":["群峰积翠水萦回，仙舸分明画里来。","百丈澄潭摇草树，半空磐磴见楼台。","风流赤壁谁应继，潦倒沧洲晚未回。","闻道西畴秋稼好，不妨迂叟日衔杯。"]},{"t":"送舒教谕赴海阳 其一","f":"五言律诗","c":["憔悴行吟地，逢君意洒然。","同歌湘水曲，何啻竹林边。","待月收银烛，鸣箫转画船。","莫言春色尽，长觉野情偏。"]},{"t":"送舒教谕赴海阳 其二","f":"五言律诗","c":["荒郡少人事，清筵时对君。","投壶惊涧鸟，题石扫山云。","暂喜羁愁减，俄闻去路分。","转嗟尘世短，离恨日纷纷。"]},{"t":"送舒教谕赴海阳 其三","f":"五言律诗","c":["沧海潮阳郡，青山刺史祠。","遗文真作者，直道更吾师。","采藻怀明荐，歌芹托盛时。","寥寥前圣统，无使后生疑。"]},{"t":"次孟侍御酬何舍人仲默见寄之作","f":"五言律诗","c":["京洛何平叔，传诗动我哀。","同时座上侣，共向岭南来。","暮笛梅花落，秋醅竹叶开。","相期不相见，怅望碧梧台。"]},{"t":"秋怀三首 其一","f":"五言古诗","c":["久客怀骨肉，况尔临秋风。","公馀辟閒馆，举目惊衰桐。","附书南飞雁，何时至江东。"]},{"t":"秋怀三首 其二","f":"五言古诗","c":["秋风西北起，浮云终日低。","悲哉金天气，万物惨以凄。","独客对湘峡，中夜闻猿啼。"]},{"t":"秋怀三首 其三","f":"五言古诗","c":["落叶随去水，回风或停之。","风止且复流，赴海终有时。","嗟我系此乡，郁郁无还期。"]},{"t":"移疾 其一","f":"七言绝句","c":["独卧藜床懒报衙，古槐啼鸟似山家。","愁中不记秋深浅，起看东园桂子花。"]},{"t":"移疾 其二","f":"七言绝句","c":["山头雨晴泉入池，黑牵牛花开满篱。","闭门三日簿书歇，恰值远人来问奇。"]},{"t":"移疾 其三","f":"七言绝句","c":["药裹蛛丝手自开，湘帘摇浪动高斋。","吴僧独在山中住，也著袈裟问疾来。"]},{"t":"移疾 其四","f":"七言绝句","c":["秋至一月暑仍酷，西风忽振庭梧飞。","白雨连山云匝地，满城儿女觅秋衣。"]},{"t":"柳山诸诗八首 其一 静观寺","f":"五言律诗","c":["独游秋山静，偃蹇群松苍。","田家谷新熟，平郊散牛羊。","野草摇众色，寒花净孤芳。","悠然忽终日，尘鞅聊相忘。"]},{"t":"柳山诸诗八首 其二 咏归亭","f":"五言律诗","c":["爱此群石秀，披襟就清风。","羽觞泛回涧，不觉匏樽空。","醉歌幽兰曲，行穿疏竹丛。","浴沂有遗叟，俯仰将无同。"]},{"t":"柳山诸诗八首 其三 杏坛","f":"五言律诗","c":["渔父讥仲尼，孤凤遂辞楚。","谁留坛树枝，摇花映江渚。","明明虞夏谟，白首困行旅。","临河歌猗兰，千载复谁语。"]},{"t":"柳山诸诗八首 其四 熙熙亭","f":"五言律诗","c":["亭下涧水清，亭上高云浮。","鱼鸟各有托，遂此岩居幽。","虑澹已忘遣，境空复何求。","相期碧草色，共对苍山秋。"]},{"t":"柳山诸诗八首 其五 俟贤亭","f":"五言律诗","c":["古人不可作，高亭复谁俟。","赭衣供井税，寂寞循良事。","白日照闾阎，凭高堕清泪。","春风杂花低，何因见驯雉。"]},{"t":"柳山诸诗八首 其六 登春台","f":"五言律诗","c":["高台倚青嶂，下顾城郭间。","茅居散花竹，雨馀春意閒。","相将理农务，朝耕暮来还。","寄言长民者，勿使惠爱悭。"]},{"t":"柳山诸诗八首 其七 仰高亭","f":"五言律诗","c":["缘云陟盘磴，俯见飞鸟脊。","侧身最高峰，去天不盈尺。","星陈上皇宫，风举神仙舄。","长啸落遗音，沈沈洞庭碧。"]},{"t":"柳山诸诗八首 其八 极高明亭","f":"五言律诗","c":["倚杖绝壁上，烈风从空来。","苍梧亘千里，万壑秋阴哀。","思将谒虞舜，上历金银台。","浮云暗南极，为我须臾开。"]},{"t":"去年予谪湘源朱升之副使以二诗寄慰兹闻升之调按滇南凄然奉答 其一","f":"七言律诗","c":["题诗慰我潇湘谪，洒泪看君巂外行。","怅望故山俱万里，苦吟秋月向孤城。","风摧羽翼青云隔，尘满头颅白发生。","世事近来无所爱，溪门春起欲归耕。"]},{"t":"去年予谪湘源朱升之副使以二诗寄慰兹闻升之调按滇南凄然奉答 其二","f":"七言律诗","c":["曾摇彩笔歌天马，更借单车访碧鸡。","栈道西盘秦塞险，滇池东压楚宫低。","行台日月无来信，世路风波少定栖。","莫向空山求薏苡，马援祠庙使人悽。"]},{"t":"宿灵家山僧居","f":"五言律诗","c":["夜宿招提舍，秋云冷石堂。","天河斜挂户，瀑水静依床。","叠岭攀跻险，虚空梦寐凉。","明朝登宝顶，期与玩神光。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其一 灵家山","f":"七言绝句","c":["灌木攒云猿啸悲，崩崖截涧马来迟。","庞眉老衲忘人世，只取朝山记岁时。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其二 苦鍊庵","f":"七言绝句","c":["竹里流泉殷地喧，古堂犹是给孤园。","山厨笕水深龙穴，石岭寻蹊听鸟言。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其三 七十二峰","f":"七言绝句","c":["七十二峰高下悬，天梯云栈互勾连。","芒鞋竹杖空林里，一路行吟破暝烟。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其四 大峰","f":"七言绝句","c":["城中遥望碧氤氲，拟是瑶空一片云。","来上峰头看气象，分明平对玉宸君。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其五 小峰","f":"七言绝句","c":["天低石角云长拥，风掠岩腰树半摧。","秋气忽寒高隼避，午阴将合老龙回。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其六 定心桥","f":"七言绝句","c":["石壁上接浮云齐，下临不测之回溪。","道人来往浑閒事，时有惊猿落树啼。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其七 扫阶竹","f":"七言绝句","c":["高岩短竹馀一尺，纤叶袅袅青鸾毛。","空山无人月华冷，西风满地秋萧骚。"]},{"t":"游覆釜山诸诗八首乃无量主人成果地也 其八 神灯","f":"七言绝句","c":["云间疏焰冷光凝，千古空门不尽灯。","一宿林中惊乍见，却留残语付山僧。"]},{"t":"九日登柳山","f":"七言律诗","c":["佳节登临感岁华，苍梧云影向秋赊。","高空独鹤翻风去，返照澄江抱郭斜。","南国音书催白雁，东篱归兴倚黄花。","衰迟自爱茱萸酒，瘴疠谁悲薏苡车。"]},{"t":"湘山杂诗十首 其一 古塔","f":"五言绝句","c":["古塔已千载，白骨为黄金。","寒灯耿不灭，照见西来心。"]},{"t":"湘山杂诗十首 其二 云归庵","f":"五言绝句","c":["松林有茅宇，白云往还来。","山僧爱云好，柴门夜长开。"]},{"t":"湘山杂诗十首 其三 飞来石","f":"五言绝句","c":["谁骑苍鸾来，啄破苔花碧。","经年不归去，化作山头石。"]},{"t":"湘山杂诗十首 其四 甲亭","f":"五言绝句","c":["不信湘中好，江山天下稀。","如何万里客，终岁澹忘归。"]},{"t":"湘山杂诗十首 其五 卓锡泉","f":"五言绝句","c":["老禅卓锡处，石上泉犹清。","红尘不相染，唯有苍苔生。"]},{"t":"湘山杂诗十首 其六 玉虹泉","f":"古风","c":["一条寒泉色，迤?穿石下。","秋雨何处寻，犹馀白虹挂。"]},{"t":"湘山杂诗十首 其七 法华泉","f":"五言绝句","c":["寂寂空山深，荒泉四时冷。","唯馀月明夜，山猿弄孤影。"]},{"t":"湘山杂诗十首 其八 玄通洞","f":"五言绝句","c":["下窥杳无极，仰视白日微。","山人把火入，照见石燕飞。"]},{"t":"湘山杂诗十首 其九 狮岩","f":"五言绝句","c":["绿草断行迹，鍧然石门开。","分明洞天里，不遇仙人回。"]},{"t":"湘山杂诗十首 其十 露胜亭","f":"五言绝句","c":["高亭行处尽，远岫望中微。","日月开禅观，云霞护客衣。"]},{"t":"寄大梁贾道诚兼简王左诸贤 其一","f":"五言律诗","c":["不见贾生久，天南空断肠。","雅文清庙瑟，儒术仲尼堂。","心事疏鸿雁，贤罗失凤凰。","乾坤正澒洞，愁绝尔摧藏。"]},{"t":"寄大梁贾道诚兼简王左诸贤 其二","f":"五言律诗","c":["秋至梁王苑，何人赋最多。","传书堪白首，欹枕即黄河。","兴忆登台饮，悲怜击筑歌。","无端洞庭渚，终岁浩烟波。"]},{"t":"寄贺长史王景旸乃子登科","f":"五言律诗","c":["董傅儒流重，韦郎世业新。","陈诗閒白昼，学礼富青春。","大府高槐色，皇都走马尘。","此时金殿上，直欲醉逡巡。"]},{"t":"湘中送荣老还金陵永宁寺","f":"五言古诗","c":["摇落三湘外，经年爱尔来。","故人书总至，异域眼俱开。","放逐怜亲友，悲欢向酒杯。","衲衣经雨暗，横笛伴秋哀。","试问寻风洞，何如对凤台。","寺幽词客满，松古老师栽。","梦寐惟吾土，羁累愧不才。","江山孤兴减，瘴疠暮颜摧。","澧浦难捐佩，龙门异曝鳃。","相看移去棹，转见脱尘埃。","烟水滔滔地，随缘易往回。"]},{"t":"奉答乔衡州","f":"五言律诗","c":["荒城闻系马，使者有题封。","尺牍惊文古，绨袍感意浓。","霜清楚泽水，云霁祝融峰。","咫尺神交地，经年阻过从。"]},{"t":"甲戌除夕 其一","f":"五言律诗","c":["南郡迎春律，东风罢雪花。","毳衣辞冷节，蓬鬓受年华。","性僻为邦简，身危去国赊。","祗应与田父，归种故园瓜。"]},{"t":"甲戌除夕 其二","f":"五言律诗","c":["堂吏封州印，家儿献岁盘。","春兼梅蕊浅，兴落酒杯宽。","瘴疠全生足，驱驰向晚难。","不遑将父母，何以慰承欢。"]},{"t":"甲戌除夕 其三","f":"五言律诗","c":["岭雪初消臈，红泉已动春。","两年迁客地，万里独吟身。","黄鹄长垂翅，苍鹰不附人。","山林无限好，犹自恋风尘。"]},{"t":"甲戌除夕 其四","f":"五言律诗","c":["细雨知冬尽，催花故媚春。","潇湘逢献岁，幽独正愁人。","岭海犹迁客，乾坤有战尘。","何时一尊酒，相对白头亲。"]},{"t":"湘江行寄孟侍御","f":"七言古诗","c":["逐臣远系湘江上，散发行歌日悲壮。","郡门江水急东流，廨宇山云作炎瘴。","去年花发悲阳春，今岁花开更泥人。","种瓜不及青门客，怀橘空思白发亲。","少年意气干云起，中路摧藏乃如此。","徒劳殴血走风尘，不救折腰临督史。","桂林夫子旧同心，献玉君门共陆沈。","千首楚歌犹跌宕，一瓢颜巷自萧森。","春风闭户意何如，遥遣娇儿奉素书。","倘蒙大府明公檄，莫惜荒城使者车。"]},{"t":"寄蒋中丞","f":"七言绝句","c":["山拥罗浮万仞青，水涵章贡混沧溟。","春深乌府文书简，白日垂帘诵五经。"]},{"t":"春夜歌立春夜试灯同张陈二进士饮后作","f":"古风","c":["东郊春旗平旦回，泰坛灯光夜复开。","太平天子运元极，佳辰令节参差来。","湘南小臣复何有，阳和亦到寒城柳。","巷陌罗幡挂玉叙，楼台画烛临朱牖。","家家夜坐吹笙竽，对此忘却居边隅。","千金斗酒不爱惜，五夜宴客同欢娱。","陈孟公，张子房，两枝玉树临中堂。","高才八韵并倾座，少年百步能穿杨。","驷马初过桑梓里，双星更度银河水。","日射金屏孔雀飞，池开锦浪鸳鸯喜。","洗觥酌君君莫辞，人生难得似君时。","且趁春花欲烂熳，与君终日醉如泥。"]},{"t":"相忆行寄鲁南钦佩","f":"七言古诗","c":["金陵帝城行乐多，荏苒独奈春宵何。","楼台压空云构丽，通衢曲巷相盘佗。","城头月起光如日，万户华灯映街出。","风窗雾阁隐玲珑，宝马香车意非一。","虎头桥下是吾庐，清夜邀宾乐有馀。","漏转几回飘火树，酒酣千遍倒砗磲。","座中高客让陈王，风雅纷纭翰墨场。","学士争观杜陵赋，尚书不怪孟公狂。","嗟予中路忽分飞，戢羽湘江久未归。","明朝客舍逢元夕，独坐思君泪满衣。"]},{"t":"元夜","f":"五言律诗","c":["明月满千门，时清乐事繁。","酒香浮夜市，花影袅春幡。","漏静鸣箫远，灯辉狭室温。","苦吟酬节序，飘泊任乾坤。"]},{"t":"春寒","f":"五言律诗","c":["燕寝文书静，春寒物候迟。","满庭犹宿草，何日且黄鹂。","云远三华树，江深二女祠。","不须添细雨，愁绪已如丝。"]},{"t":"柬陈宋卿","f":"五言律诗","c":["颇怪陈无已，寻诗日闭门。","空庭疏系马，细雨负清尊。","节序过梅萼，春阴积藓痕。","不嫌官舍冷，烧烛对黄昏。"]},{"t":"东园分菊苗有作","f":"五言古诗","c":["解带理荒圃，及兹春雨馀。","丛菊被嘉泽，芳苗郁以舒。","伐根辨众色，间植周前除。","汲涧沃新壤，秉锄散故苴。","匪惜悁勤意，爱尔气清殊。","秋华既幽靓，夏叶亦扶疏。","霭霭轩楹侧，颇慰陶潜居。"]},{"t":"湘南二月大雪戏作春雪歌 其一","f":"七言绝句","c":["桂岭长年冬郁蒸，湘江今岁积春冰。","北人饮酒歌黄竹，愁杀桃花与葛藤。"]},{"t":"湘南二月大雪戏作春雪歌 其二","f":"七言绝句","c":["二月雪花飞楚关，浑如李白对燕山。","祗愁晓日融城湿，讵惜飞花罥鬓斑。"]},{"t":"湘南二月大雪戏作春雪歌 其三","f":"七言绝句","c":["山郭桃花且未红，扑檐柳絮太匆匆。","山公久醉浑颠倒，不记湘南二月中。"]},{"t":"湘南二月大雪戏作春雪歌 其四","f":"七言绝句","c":["四野荒云接地齐，雪花如掌下寒溪。","招邀白鹭翩翩舞，孤负黄鹂恰恰啼。"]},{"t":"湘南二月大雪戏作春雪歌 其五","f":"七言绝句","c":["绕郭千峰玉作台，连林素缬尽妆梅。","同谁跨马腰弓箭，山口盘旋射鹿来。"]},{"t":"湘南二月大雪戏作春雪歌 其六","f":"七言绝句","c":["南方食麦胜食土，瓦砾不救饥肠苦。","今年春雪如陇西，蒸饵家家作端午。"]},{"t":"雪霁登湘山露胜亭","f":"五言律诗","c":["胜地意何限，新晴还独过。","众山残雪满，孤嶂烈风多。","浪迹留岩壑，幽襟到薜萝。","俗尘休见染，欲此问维摩。"]},{"t":"得徐伯雨太平书奉答","f":"七言律诗","c":["残腊江门望使车，新春忽枉丽江书。","嗟予已作三湘别，念尔那堪万里馀。","绝域风烟居暂定，深山官府事应疏。","绝怜雅兴耽诗律，满纸琼瑶愧不如。"]},{"t":"赠周典膳","f":"七言律诗","c":["宁亲西下马蹄劳，文采惊人一凤毛。","南粤江山归陆贾，梁王宾客羡枚皋。","薇堂祝寿花明酒，风动题诗月满袍。","异域逢君又伤别，离心春水共滔滔。"]},{"t":"送张进士自全州成婚归桂林","f":"七言律诗","c":["马卿持节下江乡，鸾镜新欢得孟光。","宝剑龙鳞横北斗，金屏雀影照东床。","九天礼乐周京盛，三月烟花粤徼香。","采服即看宜寿酒，门楣还喜映岩廊。"]},{"t":"清明病中作","f":"五言律诗","c":["万里清明节，三年放逐臣。","已无花共照，况有药相亲。","岭徼饶蒸雾，江湖一病身。","圣朝容腐朽，归去老垂纶。"]},{"t":"偶题","f":"五言律诗","c":["道穷何叹拙，身病始知衰。","座有青山对，门无俗客来。","浮名消短鬓，雅兴寄深杯。","颇笑刘伶辈，沈冥负尔怀。"]},{"t":"卧病四首寄诸兄弟 其一","f":"七言律诗","c":["南州瘴雾三年客，西塞清江万里家。","春断壶觞疏竹叶，病移衾枕失桃花。","英雄自分填沟壑，魑魅空劳砺齿牙。","独有苍天能料理，底须医卜浪矜誇。"]},{"t":"卧病四首寄诸兄弟 其二","f":"七言律诗","c":["江汉滔滔绕上阳，五龙京阙拱高皇。","舆图四塞青山固，陵寝千秋翠柏长。","绮丽春风开画障，郁葱佳气护金汤。","苍苔白石青溪曲，爱有巢由旧草堂。"]},{"t":"卧病四首寄诸兄弟 其三","f":"七言律诗","c":["细雨浓花思不禁，春山何处独登临。","高鸿实寄传书泪，老马虚驰伏枥心。","肺病闭门聊稳睡，穷愁抱膝且长吟。","閒情已逐归云尽，独奈人间枳棘林。"]},{"t":"卧病四首寄诸兄弟 其四","f":"七言律诗","c":["十日春阴槲叶齐，午窗吟坐到鸡栖。","归期漫阻桃花水，客泪重沾燕子泥。","万里弟兄空梦寐，百年岐路尚东西。","请看舍侧垂杨树，已映东桥旧钓溪。"]},{"t":"病中忆鲁南钦佩","f":"七言律诗","c":["空斋高卧动经旬，远梦天涯忆故人。","典礼近闻刘向起，草玄犹柰子云贫。","江楼积雨鸣长夜，山郭馀花堕晚春。","人世几何将白发，年年离恨独伤神。"]},{"t":"寄文徵仲","f":"七言律诗","c":["儒林挥笔掩群贤，湖海倾心二十年。","藻鉴尘埃无伯乐，规模乡国有颜渊。","黄花别泪临湖水，白雁乡书断楚天。","山馆穷愁欹枕日，拭君图画转凄然。"]},{"t":"送阳春歌和陈宋卿","f":"古风","c":["南风吹春辞九垓，百舌怨诉黄鹂哀。","老夫卧病亦强起，把酒劝花俱一杯。","我家旧住金陵曲，开门正对梁王台。","桃花盈蹊柳映地，年年爱见春风来。","千金买鞍装骏马，山高堆粟成新醅。","云台功名不足取，富贵于我如蒿莱。","古人白骨穴蝼蚁，亦知王乔安在哉。","一从弃掷向湘水，辕驹局促惭非才。","羁栖厌见春色至，教儿刬却东园梅。","纵有韶华满郊薮，弄花斗草随婴孩。","青春尔今去，勿为吾徘徊。","吾衰今久矣吾视，天地万物真浮埃。"]},{"t":"湘山寺同客作","f":"七言古诗","c":["一麾迢递天南头，名山颇惬平生游。","日饱窗中列岫色，更起策杖穷岩幽。","窈曲烟霞入空翠，招邀不识神灵意。","自从窜逐得逍遥，始叹风尘昔蒙昧。","升堂笑问无量师，尔住青山今几时。","翻经愿从弟子列，洗钵愧乏头陀姿。","诛茅小乞岩前地，痛饮狂歌日来去。","听法閒看虎伏时，怀乡莫近猿啼处。","幽花细竹俱堪怜，烧丹服药期长年。","费公未启王屋鼎，华老谬语天池泉。","神仙渺茫竟难测，古往今来岂终极。","但愿道路风波平，江上故园归即得。"]},{"t":"楚歌二首 其一 天吴","f":"楚辞体","c":["灵淼淼兮焉穷，下无极兮幽宫。","登岷峨兮远望，波龙鳞兮扬风。","赤螭兮黄鼍，喷雾雨兮骈罗。","望子之驾兮伊迩，交不缔兮奈何。","眷予心兮东归，君不顾兮畴依。","将以承兮巧笑，揆皇道兮虑非。","荪壁兮兰堂，结桂枝兮芬芳。","羌离合兮有期，聊容与兮徜徉。"]},{"t":"楚歌二首 其二 洞庭君","f":"楚辞体","c":["坎坎兮击鼓，望君山兮屡舞。","陈烦辞兮仰空，渺夫君兮何所。","波四漫兮汤汤，会百川兮同量。","津无梁兮不可以涉，测地弥广兮度天愈长。","驾兰桡兮扬桂旗，飘风起兮又汩之。","浮余瓠兮水际，理余佩兮川湄。","众纷纭兮磔肥牛，顾玄醴兮增余羞。","陟虚坛兮伫立，徒终岁兮离忧。"]},{"t":"和英玉览柳山图见寄之作","f":"五言律诗","c":["昔人弦诵地，古木已如兹。","惠泽宛犹在，池台空尔为。","棠花依涧发，薜荔绕墙垂。","更扫苍厓石，新镌水部诗。"]},{"t":"闻英玉拜南京屯田主事戏寄","f":"七言律诗","c":["二月除书飞帝京，屯田新注省郎名。","亲庭乡国总在眼，把酒赋诗无限情。","三径盘桓花历乱，九关开阖虎纵横。","金门大隐无人识，方朔应传笑贾生。"]},{"t":"答乔衡州汝修 其一","f":"五言律诗","c":["传道衡山郡，棠花满路春。","寂寥循吏传，将老见斯人。","玄发丹青地，孤标玉雪身。","平生倾倒意，绝域为谁亲。"]},{"t":"答乔衡州汝修 其二","f":"五言律诗","c":["鲍叔元知我，陶潜久悟非。","身经畏途老，梦想故园归。","失路沾青眼，馀生乞采衣。","相过知不远，长望岳云飞。"]},{"t":"寄内并示二儿 其一","f":"七言绝句","c":["满堂风雨烛花残，独客思归坐夜寒。","遥想故园当此夕，画楼明月影团团。"]},{"t":"寄内并示二儿 其二","f":"七言绝句","c":["小阁书声夜漏稀，东归潘岳奉慈闱。","湘南山水虽云美，不及桥阴旧钓矶。"]},{"t":"和英玉闻秋佳亭新移怅然作兼简王礼部钦佩","f":"七言律诗","c":["秋佳亭子临秋水，伐木新移向近陂。","小径有时迷客入，长杨无数绕檐垂。","即看野鹊春来喜，莫怪群鸥晚下疑。","寄语东邻王礼部，好携樽酒数追随。"]},{"t":"答李川甫二首 其一","f":"五言古诗","c":["昔予牧大梁，庠序多俊民。","峨冠列广座，雅论何彬彬。","思慕信陵义，密尔申交亲。","输心誓白日，永怀越千春。","惊风西北起，奄忽暗流尘。","巾车一何迫，泣别长河滨。","生死忽乖隔，泪下沾衣绅。"]},{"t":"答李川甫二首 其二","f":"五言古诗","c":["南迁度湘渚，湘渚阻且深。","蛟鱼凌波起，骇浪如高岑。","岩峦仄无地，草木多毒淫。","三岁栖绝域，长恐遂幽沈。","鸣雁自北来，衔书置庭阴。","开椷览流藻，乃是潇湘吟。","薄俗昧交义，贵贱异中襟。","与子绝会面，庶以明远心。"]},{"t":"杨仪宾东皋","f":"五言律诗","c":["路转漓江曲，林间逸士家。","避人成独往，隐几坐无哗。","舞鹤穿行径，游鱼傍钓车。","时闻萧史辈，驻此共餐霞。"]},{"t":"江上送马锦衣按事回 其一","f":"古风","c":["贞士不可见，凄凉饮冰言。","徒惭金吾使，万里驰輶轩。","马君伏波之子孙，西观桐柱迹犹存。","江上相逢多意气，高歌一曲下湘沅。"]},{"t":"江上送马锦衣按事回 其二","f":"古风","c":["雅歌皇华诗，送行倾玉卮。","薰风吹船下湘渚，回首谁怜斑竹枝。","君来安坐人莫窥，判如南山何可移。","汉庭贤士虽无数，四海偏誇张释之。"]},{"t":"初闻望之量移汶上","f":"五言律诗","c":["逐客承优诏，宁亲得近居。","主恩天地大，臣节死生馀。","鲁邑鸡初割，长沙鵩已袪。","馀欢兼旧侣，应免葬江鱼。"]},{"t":"江上迎望之逆风舟不得进","f":"古风","c":["两年望君君不来，渴心捲水生黄埃。","昨闻津吏报君至，秉烛传更夜无寐。","晓雨移樽江上迎，南风吹船船倒行。","五里停篙十里泊，侧听鼓角前湾声。","君乘画舫荡双楫，涧壑下泻滩流平。","眼中迟速亦复尔，何况出处关人生。","万事未须问，会面安可轻。","与君月出共舟去，山水湘南无限情。"]},{"t":"江上感秋呈望之","f":"古风","c":["昨日梧叶落，今日蘋花开。","秋光向人不相贷，客子感物令心哀。","三湘水阔高云凝，群峰雨馀游气澄。","岂无清欢待尔至，转恐欲别愁难胜。","我留绝域更谁依，君望家山只欲归。","若到襄阳骑马处，闺人应理旧斑衣。"]},{"t":"赠别望之兼寄诸相知十首 其一","f":"五言律诗","c":["五岭炎蒸地，三年共谪居。","送君南鲁去，予意独何如。","大舶依流水，归心指故庐。","江门今夜月，相对暂踟蹰。"]},{"t":"赠别望之兼寄诸相知十首 其二","f":"五言律诗","c":["相逢殊不易，相别且从容。","落日留羁鸟，惊雷起卧龙。","独吟江路永，多难故情浓。","回首伤心地，无劳望桂峰。"]},{"t":"赠别望之兼寄诸相知十首 其三","f":"五言律诗","c":["白发倚门久，清江催棹频。","荣枯知圣泽，瘴疠脱危津。","乌鸟心偏苦，骅骝气有神。","风烟千万里，愁杀未归人。"]},{"t":"赠别望之兼寄诸相知十首 其四","f":"五言律诗","c":["何处瞻飞舄，秋风汶水波。","黄尘清市井，明月照弦歌。","宓子非凡吏，宣尼有四科。","平生霄汉意，摧折未蹉跎。"]},{"t":"赠别望之兼寄诸相知十首 其五","f":"五言律诗","c":["直道台端谪，清风岭外还。","诸生依日月，雅兴发江山。","痛饮神逾炯，哀歌鬓已斑。","看君置心迹，浑在古人间。"]},{"t":"赠别望之兼寄诸相知十首 其六","f":"五言律诗","c":["昔别空同子，封书发豫章。","君今还汝水，渠已客襄阳。","苦别交亲老，时名岁月长。","斯人常坎坷，天意竟茫茫。"]},{"t":"赠别望之兼寄诸相知十首 其七","f":"五言律诗","c":["不见边丞久，于今更四年。","衡湘悲雁绝，台省贺莺迁。","屡梦攀嵇叔，无诗寄郑虔。","经过问消息，漂泊已华颠。"]},{"t":"赠别望之兼寄诸相知十首 其八","f":"五言律诗","c":["旧游纷雨散，京国祗崔何。","东观摛辞贵，南天洒泪多。","云深愁问信，月好忆联珂。","赠别留长句，时时发醉歌。"]},{"t":"赠别望之兼寄诸相知十首 其九","f":"五言律诗","c":["汶阳临大道，喜近赵东曹。","窜地传书数，他乡念我劳。","名高连泰岳，心远折江涛。","拟共观周礼，无因接誉髦。"]},{"t":"赠别望之兼寄诸相知十首 其十","f":"五言律诗","c":["吾生堪太息，世路易浮沉。","物色悲游子，风波损壮心。","同人桂林少，积水洞庭深。","渺渺伤神极，还愁老欲侵。"]},{"t":"夏日雨中与客饮朱别驾宅","f":"七言律诗","c":["閒馆投壶白昼长，桤林鸣雨送飞觞。","千山湿翠云垂地，万壑平流水映堂。","尘世几回逢酩酊，瘴乡三伏遂清凉。","休辞枥马喧东道，爱对庭中短烛光。"]},{"t":"赠靖江王孙 其一","f":"五言律诗","c":["大雅诗书志，高情洞壑居。","风流宜鹤氅，云气绕鸾舆。","摛辞过梁宋，召客得应徐。","投簪吾未老，犹可曳长裾。"]},{"t":"赠靖江王孙 其二","f":"五言律诗","c":["紫阁投朱绂，青山卧白云。","凤笙流秘曲，鸿宝枕灵文。","近得临邛客，飘然思不群。","时传古词赋，为我洗尘氛。"]},{"t":"快哉行","f":"七言古诗","c":["东方日出晓衙集，壮士冲关突然入。","背负猛虎手强弩，短镞棱棱血犹湿。","斑文白额委中庭，空闪金眸洒寒泣。","我嘉壮士饮之酒，拔剑刲羊发仍立。","观者如墙方笑呼，杀声落日喧城隅。","众豪复提一虎至，洞胸直贯长蛇殳。","垂头狼藉类黄犬，猛物失势堪嗟吁。","快哉二害同日尽，何啻并殛凶饕徒。","田家儿女开户寝，馀惠况及犬与猪。","可怜尔虎何太愚，鸷害自古遭神诛。","尔类好杀终亡躯，胡不早走深岩居。","转易猛性为驺虞，为民献瑞登王都。"]},{"t":"月","f":"五言律诗","c":["秋月光如洗，高台夜转寒。","江流铺雪去，松壁影龙蟠。","玉兔栖难稳，苍猿泪欲乾。","楚天多雾雨，坐对判更阑。"]},{"t":"题张东海草书后","f":"五言律诗","c":["绝代风流远，名家草圣传。","龙蛇馀万纸，鸾凤渺孤骞。","俊拔归张旭，萧条老郑虔。","天南看旧帖，三复叹前贤。"]},{"t":"挽李将军","f":"五言古诗","c":["早穷黄石略，远佐伏波军。","入幕推英选，横戈策壮勋。","驱驰仍白首，特达且青云。","逝水悲雄剑，长星落古坟。","范增心未已，李广命何屯。","阀阅遗骠骑，文章起凤群。","将门收藻色，史阁播清芬。","偃蹇蓬蒿子，那能百代闻。"]},{"t":"寄上司马白岩乔公","f":"七言古诗","c":["北斗枢衡控上都，南台司马握兵符。","河山地正乾坤位，雨露春融造化垆。","分陕雅推周有道，戍江应笑晋非图。","朝廷白发忧相倚，寰海苍生望已苏。","幕府吁谟趋老将，锦堂觞咏列文儒。","心当大任何曾动，身致升平得自娱。","谢墅赌棋花正好，秦淮吹笛月同孤。","王风伫听歌麟趾，公子振振见玉颅。"]},{"t":"将赴灌阳","f":"五言律诗","c":["累岁倦行役，兹晨仍灌川。","路危缠岭脊，草盛隐人肩。","逐客穷愁地，荒城大有年。","不才宽罪谴，何以报皇天。"]},{"t":"入金盆山访唐孝子 其一","f":"五言律诗","c":["旧闻刲股事，今见结庐情。","笃行关风俗，残躯效死生。","秋原双泪苦，春草寸心倾。","独夜悲风切，偏闻宰树声。"]},{"t":"入金盆山访唐孝子 其二","f":"五言律诗","c":["秋日观风地，青山五马庄。","荒庐依大冢，乌鸟泣衰杨。","孝子人伦重，高贤世绪昌。","磨崖传故事，林壑借馀光。"]},{"t":"至灌阳平赋作","f":"古风","c":["我闻黄虞民，罔识官师名。","老翁被素发，壤歌如孩婴。","季世广法令，民心始忡?。","马牛急租税，鸡犬纷斗争。","兹邑苦穷僻，曾巘纾荒城。","谓云华胥国，颇遂桃源耕。","咨诹逮幽隐，转痛闾阎情。","山深吏治猛，里胥日纵横。","执热不以濯，煎膏难及明。","府帖增新役，赋籍何由平。","水枯网罟乱，孰使鱼不惊。","投笔坐长叹，泪下沾緌缨。"]},{"t":"中秋日学宫试诸生","f":"五言古诗","c":["宴坐中秋日，云晴灌水阳。","玉麟横郭见，文笔映波长。","隐几饶幽胜，登堂总俊良。","英灵占萃聚，神采爱舒张。","颇讶遗珠远，谁云古道荒。","多闻沾柳教，妙悟近周乡。","僻壤缘人胜，儒绅贵志强。","嗟予牵世网，垂老觅亡羊。"]},{"t":"学舍见紫薇花","f":"七言绝句","c":["学宫古苔满阴壁，一株紫薇当户新。","矜持幽意故远俗，点缀秋光时近人。"]},{"t":"中秋县署值雨 其一","f":"五言律诗","c":["此夕中秋月，他乡两度圆。","孤云生夜翳，万象失秋妍。","雨气饶侵客，风期又隔年。","谁能揽明镜，烂熳挂青天。"]},{"t":"中秋县署值雨 其二","f":"五言律诗","c":["独客佳辰思，空山积雨愁。","纵能斟绿蚁，何处望琼楼。","岩桂萧萧落，江云冉冉浮。","愿馀吴地影，聊破老亲忧。"]},{"t":"华山对雨寄陈鲁南索画","f":"七言绝句","c":["众壑行云递有无，灌潭秋影照人孤。","题诗寄向王摩诘，乞写华山对雨图。"]},{"t":"灌江见夫容因忆王礼部钦佩许予作此赋未至聊寄一首","f":"七言绝句","c":["两度湘江见尔开，水清沙远转悠哉。","池头旧日西风面，正对东邻作赋才。"]},{"t":"闻灌人云有柳子厚遗迹因策马往寻历大源塘入仙源洞不得其处而返","f":"五言古诗","c":["柳侯昔放逐，颇好山水事。","观其著文词，动以喻来世。","逮今岁月改，陵谷莽迁异。","我行徂灌川，闻有招隐地。","怀贤慰遐想，吊古积幽思。","尘馆休吏衙，秋原散游骑。","度岭疲登顿，涉溪苦沾渍。","空潭激哀流，古木堕馀翠。","穷搜尽阳景，屡剔断碑字。","岂无会心观，往往悖图志。","兴尽且须返，聊以展同致。"]},{"t":"寻山","f":"七言律诗","c":["曲坂凌虚度七盘，仙源何处问三韩。","溪门古木苍云湿，涧道疏花白雪寒。","短发漫冲霜霰老，青山聊拨簿书看。","须知野兴秋难禁，莫怪岩阴日易残。"]},{"t":"华山舜祠","f":"七言律诗","c":["隐隐苍梧映郭门，滔滔江水抱山根。","群峰独捧重华庙，大地谁言五岳尊。","云暗九疑迷葬地，月明孤竹见啼痕。","长将涧藻修寅祀，愿就琴薰仰德温。"]},{"t":"访仙源洞得道人蒋馨故栖石题","f":"五言律诗","c":["水曲桃花暗，灵岩信有仙。","虫书留古洞，鹤驾去何年。","白犬眠金灶，苍龙饮玉泉。","愧非嵇叔夜，来此竟空旋。"]},{"t":"小泛得黄楼诸山之胜","f":"五言律诗","c":["不奈城中役，重寻水上游。","秋光俱白舫，山翠忽黄楼。","竹覆溪门净，云藏石洞幽。","诛茅饶野意，留语报沙鸥。"]},{"t":"游通真岩与数子商作思柳亭","f":"五言古诗","c":["荡舟缘西溪，风物始虚爽。","忽得通真岩，众喜得奇赏。","石壁倒千仞，洪涛漱中广。","通天贯灵窍，云气恣来往。","玉髓堕阴滴，莲花抱烟长。","居然神仙窟，所愧系尘鞅。","缅怀柳愚溪，千载寄幽想。","其人虽已没，精华尚星朗。","愿言作新亭，延此烟月党。","今古两悠悠，江波日东响。"]},{"t":"出灌江峡","f":"七言律诗","c":["群山高束灌江流，雪浪清秋洒客舟。","古木倒垂云上下，乱滩交泻石沈浮。","猖狂阮籍穷途哭，浩荡王阳度坂愁。","料乏云台酬马革，愿携霜鬓老狐邱。"]},{"t":"宿白水渡","f":"五言律诗","c":["积水吞寒濑，孤舟宿暮烟。","邀人壶蚁泛，作赋烛花悬。","发变风波境，神惊四十年。","壮心空感激，夜起拂龙泉。"]},{"t":"白露","f":"古风","c":["白露凄凄，原草具腓。","日月于迈，载授我衣。","北山有堂，江注其麓。","薄言出游，以写心曲。","山木斓斑，江云差池。","乐以旨酒，委蛇委蛇。","尔樵尔渔，来往无怒。","尔农获斯，黍稷如岵。","戋戋守臣，实蹈百愆。","何以逭之，曰维丰年。","丰年伊何，维民之德。","民之颂之，天子之泽。"]},{"t":"寄叶澄","f":"古风","c":["高士多异标，骅骝隐奇骨。","拙匠昧玄理，纷纷写毛发。","曹霸画马权奇高，裴公之面飘三毛。","始知能事贵得意，耻与形相论纤毫。","燕山叶子心目灵，少年刻意工丹青。","闭门解衣日盘礴，兴起落笔通幽冥。","我谒南曹大司马，五岳峥嵘走堂下。","烟霞㸌目不敢前，熟视乃知是君写。","一谪潇湘今几秋，思君不见增烦忧。","绝怜山水最奇处，苦乏妙笔移沧洲。","覆釜峰，湘江水，世传蓬壶无乃是。","我有长绡寄向君，烦君写入茅庐里，欲访形容问吾子。"]},{"t":"磐石秋望","f":"七言律诗","c":["信美江山映郭西，清秋羁客思凄凄。","黑波跳雨蛟龙斗，苍峡摧云虎豹啼。","万里辞家饶白发，一邱归卧有黄齑。","蛮烟毒雾伤心地，马援何因到五溪。"]},{"t":"酬王钦佩见怀之作","f":"七言律诗","c":["长忆西邻海雪庄，主人从宦日徜徉。","穿花跨马趋东省，斸笋烹鱼上北堂。","静室幽兰无限意，小山丛桂几回芳。","天涯逐客归期远，岁暮怀君枉断肠。"]},{"t":"酬陈鲁南见寄青溪看月之作","f":"七言律诗","c":["青溪明月引长唫，湘浦寒云滞客心。","归思不堪枫叶尽，故情俱向楚江深。","荒城寂历山当户，旧叶凋零鹊绕林。","身世与君同未达，却怜霜鬓映疏襟。"]},{"t":"酬刘元瑞黄州见寄之作","f":"七言律诗","c":["秋风旌节过黄州，杪岁椷书到岭陬。","交谊死生归气槩，词华今古接风流。","江翻荆口天齐落，山转滇南地半浮。","闻道柏台多暇日，况逢陶谢好同游。"]},{"t":"奉次司马泾川张公打鱼短歌","f":"七言古诗","c":["渔舟晓集澄江湾，设栅布网如重关。","两曹分张鼓齐发，风雷簸荡波涛间。","大鱼踉跄浮额鼻，挺叉入水喧群蛮。","小鱼往往脱疏目，获少不怪阳侯悭。","割鲜矠藁总民力，地利在余焉敢匿。","载登鼎俎享群公，退食庶几无赧色。","羡馀颇餍仆隶腹，细琐亦任渔人得。","堪叹结绳遗祸阶，物命公然恣人食。","南台司马初辞官，香粳细脍且加餐。","倘闻涸辙遗枯鲋，更借西江万顷宽。"]},{"t":"对雪","f":"七言律诗","c":["山郭阴沈雪片稠，冻云重叠傍城楼。","风回乱木飞花合，夜静寒窗素月流。","北望自谁旋气轴，南迁今始问冬裘。","欲留蚁酒临春赏，正恐鹑衣彻夜愁。"]},{"t":"谢平乐张太守惠莲花酒","f":"古风","c":["暮冬雪寒风飘飘，湘城冻酒甜如蜜。","倾杯欲饮复推去，空对江山坐终日。","漓江太守神仙人，双罂远致莲花春。","开轩晓起试三爵，顿洗百斛胸中尘。","高歌梁甫曲，脱却渊明巾。","眼前万事底须问，且从烂醉陶吾真。"]},{"t":"连陪诸公柳山春游 其一","f":"七言律诗","c":["湘州城北古堂幽，十日春晴两度游。","山畔数亭俱可醉，林间孤涧亦销忧。","岩峦气色迎车发，草树风光绕郭浮。","况与群公陪胜践，岂输山简习池头。"]},{"t":"连陪诸公柳山春游 其二","f":"七言律诗","c":["春雪初晴翔凤楼，春烟已飏赏花眸。","江山面面因亭胜，物色年年赖酒酬。","异代风流如昨日，几人迁放得沧洲。","柳丝桃萼参差暖，堂上疏帘渐可钩。"]},{"t":"赠陈宋卿","f":"五言律诗","c":["落落青云器，天南一凤麟。","诗书过目得，孝友发情真。","旧笏传华胄，高词见古人。","腐儒迁谪地，幽抱为谁新。"]},{"t":"以奇石献泾川公辱报长歌辄答一首","f":"七言古诗","c":["湘西石洞涵杳冥，湿云倒结莲花青。","山童采斲送官舍，风雨黑夜号山灵。","蛰龙惊雷耸头角，怒豸蹲岩犹扑朔。","峥嵘石柱高几许，眼底分明瞻华岳。","簿书堆案烟霞愁，尘颜龌龊真可羞。","碧山学士负仙骨，此物正合供幽求。","绿蒲朱草映涟漪，净几疏帘日咏诗。","不誇醒酒千金价，独玩通灵五色芝。"]},{"t":"悼李千骑","f":"五言古诗","c":["渭滨久寂莫，何人应非熊。","不识一丁字，空持六钧弓。","桓桓李将军，诗书浩填胸。","草檄鞍马畔，折冲樽俎中。","虽孤云台画，至今称英雄。"]},{"t":"赠别陈宋卿","f":"五言律诗","c":["把酒夭桃下，飞花逐浪流。","湘江春二月，无奈别离愁。","钓渚衔沙岸，书堂枕石邱。","明朝怀旧赏，独倚郡南楼。"]},{"t":"柳山石壁凹深泾川公每至坐卧其中余遂表为司马岩并纪一诗","f":"五言古诗","c":["北山多幽踪，灵怪具兹石。","窈曲壶峰房，巉岩老蛟脊。","寒泉界遥青，烟萝缀疏碧。","云构俨成居，神仙合来宅。","司马真天人，辅世应帝谪。","税驾归故乡，徜徉此投迹。","草树徵文章，烟霞卫巾舄。","俯仰皆有馀，动静随所适。","我愿标嘉名，大刻示无易。","盛美垂千秋，留光照山泽。"]},{"t":"观玉柱岩作","f":"五言古诗","c":["列炬窥玄府，搴裳步紫坛。","石田云子白，龙井玉浆寒。","巨栋垂千尺，幽房隐百盘。","仙灵多幻化，造物自雕刊。","异境今初辟，清游午未还。","烂柯如有遇，何用恋尘寰。"]},{"t":"辩蛤和泾川公","f":"五言古诗","c":["渔海穷潏泬，猎山历㟏岈。","生人胡多劳，养此六六牙。","圣哲著礼经，细不遗蚁蛙。","食鼋不染指，因以倾厥家。","末俗贵珍异，载籍纷喧哗。","美哉尔石蛤，奚免网与叉。","黄鹄终见炙，安可矜高遐。","修胫雪长荇，腴中剖团瓜。","烹以实下豆，亦慰宾筵嘉。","南荒盛虫族，大者蛇与蟆。","琐细及百种，射影兼含沙。","食者苦呕泄，伤者困疮瘕。","例举混美恶，颇笑昌黎差。","幸蒙匕箸赏，重以褒辞加。","河豚自此贱，况复论鱼虾。"]},{"t":"辱泾川公惠诗谈止足之分奉答三章 其一","f":"五言古诗","c":["汎览前古志，衋然增中酸。","贤圣困胼胝，黠侠炙人肝。","门雀叹贵贱，市犬惊悲欢。","是非乱无定，千载劳铅丹。","徒令腐儒辈，怒发时冲冠。","璘也生最晚，履道惭孤寒。","南迁济湘水，始陟横渠坛。","玄功无弃物，朽骨蒙雕刊。","孤羁恋恩义，逆境知忧患。","鹪鹩自云微，冀饱鼠壤残。","营营飞蛾翼，竟为烈火燔。","近枉大雅什，益闻达生言。","如病居膏肓，得投俞扁丸。","波涛息中境，魂梦寂以安。","朅闻青春尽，期诣西园观。","遥携林中弈，试洗花间盘。","斯游漫成阻，后约良非难。","蒲轮颇安稳，何必忧轾轩。"]},{"t":"辱泾川公惠诗谈止足之分奉答三章 其二","f":"五言古诗","c":["泾公鼎鼐器，一德调咸酸。","委身奉明主，即事恒披肝。","云龙际嘉会，鱼水投至欢。","秉笏四十载，寸衷晚逾丹。","班马记言笔，房杜进贤冠。","所至见挺直，凛凛奸谀寒。","朅来守留京，建节上将坛。","军容一时肃，政蠹随手刊。","遂令鸿雁居，悉远豺狼患。","翻然忆莼鲈，匪谓伤秋残。","叩阍累十疏，缨冕先自燔。","止足不殆辱，永怀伯阳言。","回驾太勇决，何啻如转丸。","至今四海心，忽忽忧危安。","嗟予愧河伯，谬向东海观。","时沾勺水益，已足盈盂盘。","曲士束小教，语大固所难。","且愿待函丈，日听歌虞轩。"]},{"t":"辱泾川公惠诗谈止足之分奉答三章 其三","f":"五言古诗","c":["食桂亦足辛，食梅亦足酸。","至味贵适口，安用珍龙肝。","夸毗好怪异，旁观损人欢。","杨雄抱清静，车毂恶朱丹。","杜钦事薄游，龌龊簪小冠。","有名映千古，何必论饥寒。","赫赫卫与霍，巡游扈祠坛。","出师燕然北，功成竟镌刊。","高明鬼所瞰，竟致倾覆患。","鹊巢岂不高，飘风自见残。","象齿徒云长，厥身因以燔。","所贵儒者事，功德与立言。","富贵真小物，一掷轻弹丸。","贤哉大司马，遗子独以安。","戒酒虽短章，齐物因大观。","巨细罔玷缺，完此白玉盘。","高朗惟日月，自卑仰弥难。","发蒙及小子，志气豁且轩。"]},{"t":"晚庭纳凉作五平诗呈泾川公","f":"五言古诗","c":["林风摇高梧，山云飘秋霖。","飞泉摇城西，声垂湘江深。","空庭当凉宵，端居清人心。","齐纨停轻挥，絺衣开疏襟。","遥钟从何来，悠然流馀音。","琴丝烦空弹，壶浆慵孤斟。","檀烟生陶垆，閒忧几销沈。","高歌昌黎诗，千秋期追寻。"]},{"t":"八月一日舟下漓江","f":"七言律诗","c":["云间千壑泻漓川，日下孤帆出晓烟。","万里行踪始安岭，九秋晴望泬寥天。","江山故作殊方色，道路今酬逐客缘。","风洞星岩应可到，还家嬴取故人怜。"]},{"t":"兴安陡江口号","f":"五言绝句","c":["江擘山头出，舟骑石背行。","问君缘个事，辛苦作南征。"]},{"t":"夜游韶音洞同徐萧二君","f":"五言古诗","c":["重华昔南狩，乘云苍梧岑。","元德被千载，山川渺崇深。","伊谁慕遗迹，号此空江浔。","坤灵启虚窦，孤嶂丛篁森。","南风从中来，锵然协韶音。","上有孤凤皇，扬采仪青林。","游览值初夜，盘桓剧幽寻。","二子兴不浅，高歌五弦唫。","榜舟涉水府，秉烛跻嵚崟。","依微历石径，寒露清人襟。","照壁颂古文，虫书黯销沈。","感之叹陵谷，浊酒聊共斟。","赋诗亦何谓，祗以昭遐心。"]},{"t":"北觐将归呈泾川公","f":"七言律诗","c":["紫微高拱五云端，清夜焚香正北看。","幸履阶墀瞻日月，敢辞舟楫犯波澜。","江湖自笑虞翻老，故旧谁怜范叔寒。","卧病山城长闭阁，临岐空惜岁华阑。"]},{"t":"奉和总制陈公江西平贼诗 其一","f":"七言律诗","c":["柏府勋名冠两京，淮西还仗白旄行。","登坛气色无群盗，报国谟谋有太平。","万壑鼓鼙声震叠，五营刁斗令分明。","纷纷骄将皆儿戏，岂识辕门节制兵。"]},{"t":"奉和总制陈公江西平贼诗 其二","f":"七言律诗","c":["春风花发楚江西，犁鼻峰阴罢鼓鼙。","已见妖狐青冢血，不辞归马锦障泥。","东溟倒洗群方净，北斗高悬万象低。","为喜洪钧开泰运，庙谟仍报定燕齐。"]},{"t":"奉和总制陈公江西平贼诗 其三","f":"七言律诗","c":["南国同歌时雨施，丈人威德称行师。","风云气胜旌旗转，日月功高带砺垂。","金马史臣争点笔，杜陵辞客莫忧时。","衣冠不改先朝乐，长捧龙光集凤池。"]},{"t":"奉和总制陈公江西平贼诗 其四","f":"七言律诗","c":["白扇閒麾野翯翎，前军佳气贯台星。","班超虎食元殊相，吕望鹰扬独暮龄。","忠荩向天回太白，英雄于宝胜空青。","从来康济关吾道，莫叹频年辙未停。"]},{"t":"奉和总制陈公江西平贼诗 其五","f":"七言律诗","c":["海岳分明属吐吞，太阿聊尔试盘根。","江湖尽转澄清色，豺虎潜沾肃杀恩。","凯奏金笳翻旧曲，功铭铜柱勒新痕。","遥闻献馘龙楼下，赤羽雕戈丽午门。"]},{"t":"登石鼓书院合江亭","f":"五言律诗","c":["滚滚双流合，棱棱独渚高。","亭台含气色，城郭俯波涛。","望岳川途迥，怀贤意绪劳。","江风吹客鬓，秋思两萧条。"]},{"t":"长沙阻风呈陆郡伯良弼","f":"五言律诗","c":["五日长沙浦，颠风滞客舟。","江神吁可怪，地主幸堪留。","乡梦摇灯影，閒情倚钓钩。","若无文酒乐，何以慰羁愁。"]},{"t":"谒岳麓书院","f":"五言古诗","c":["瞻彼衡岳麓，松柏何青青。","苍云被曾阜，石室延空冥。","朱张命世儒，潜兹考遗经。","悠悠过化迹，仰止犹华星。","蹇予泊湘渚，风涛限扬舲。","挂帆决所济，杖策临幽扃。","薰香谒虚位，周览循阶庭。","物色信多美，山川郁钟灵。","后贤力绍述，堂构递经营。","群植拟孔林，曲池方兰亭。","既云备游息，亦以宏高明。","兹方盛才彦，礼乐遵仪刑。","精修诣阃奥，庶续千秋盟。","母为汩尘土，永以羞岩峒。"]},{"t":"一丛花 湘南见池上梅花作二首 其一","f":"古风","c":["东风花发小池边。","移种是何年。","江南旧日看花处，更回首、多少山川。","聊折一枝，瓦瓶斜插，惆怅早春天。"]},{"t":"一丛花 湘南见池上梅花作二首 其二","f":"古风","c":["凌波何处见铢衣。","池畔月明时。","春风莫作颠狂态，好堪耐、璚雪葳蕤。","楼上笛残，陇头书远，人在楚云西。"]},{"t":"采桑子 其一 甲戌正月十三夜风雨作","f":"古风","c":["华灯光射银屏影，斗起春光。","月转回廊。","罗绮风飘满路香。","金陵自古豪华地，不似殊方。","堪笑潘郎。","流落天涯独举觞。"]},{"t":"采桑子 其二 甲戌正月十三夜风雨作","f":"古风","c":["春城箫鼓无端闹，说近元宵。","华烛高烧。","偏对良辰更寂寥。","斜风细雨敲窗户，又送萧条。","愁病无聊。","何日行歌白下桥。"]},{"t":"摸鱼儿 春寒作","f":"古风","c":["向小园、花丛飞数蝶，懊恼又飘轻雪。","倚画栏、独望湘山影，缥缈半峰残月。","风料峭、罗袂生寒，默默愁难说。","家乡万里，想绿草池塘，碧桃院落。","更自伤、离别柔情结。","看湘娥、旧恨班班，竹上难灭。","问东皇、何日金乌扑帐，春云热。","扁舟独自归去，高堂菽水同欢悦。","班衣笑舞，再莫道、中朝绯袍金印，门前建旌节。"]},{"t":"诉衷情 桂林徐伯川屡约不至有词见寄作此答之","f":"古风","c":["瑶笺新调写乌丝。","字字说相思。","传闻几度来也，又盼过、落花时。","停画舫，驻金羁。","枉参差。","干天何事，伏雨阑风，故误佳期。"]},{"t":"念奴娇 湘山怀古","f":"古风","c":["振衣嵂?，洗长空、初过一天新雨。","万壑千峰，争耸秀、犹有微云吞吐。","扑地闾阎，横江城郭，总是閒尘土。","寺前松桧，让渠曾见今古。","漫说衡岳巡游，郁林开拓身，后还谁主。","泪竹斑斑，空洒血、玉辇而今何处。","水底灵均，江边刺史蔓，草埋荒宇。","举觞浮白，竟须烂醉休语。"]},{"t":"初至山中","f":"五言古诗","c":["杨子疲执戟，庞公息岩阿。","所志既匪同，仕隐乃殊科。","蹇余究坟素，弱冠挂贤罗。","一往四十年，功鲜忧患多。","朅来返初服，城郭困经过。","眷兹空山曲，阒寂患微痾。","乔松周四厓，嘉谷被前坡。","鸣禽戏丛筱，游鱼泳清波。","尘氛一以远，形神稍相和。","况有旧田庐，偃仰可婆娑。","疏食苟无恙，永言憩烟萝。"]},{"t":"新理松坞草堂","f":"五言古诗","c":["家世本吴趋，明代徙东楚。","服勤传素业，展转力田亩。","逮余薄劣资，怀笔干斗釜。","鴳翼希鹏图，抢榆唯自苦。","眇哉竹帛心，仰负三圣主。","解龟返田园，荒凉旧茅宇。","羸躯倦城邑，衰志慕林薮。","伐木理摧栋，荷杵筑环堵。","苟完栖故书，所重守先墓。","岩崿倏生姿，卉木咸就序。","流云畅疏襟，清风待挥麈。","但恐尼父讥，垂老学农圃。"]},{"t":"松坞草堂新成杂兴十二首 其一","f":"七言律诗","c":["空山卜筑敢辞烦，城郭逢迎太近喧。","老病移家唯药物，野人乘兴自丘樊。","频来白鹤如求友，旧种青松巧护垣。","已办鹿车供出入，竹林多类辟疆园。"]},{"t":"松坞草堂新成杂兴十二首 其三","f":"七言律诗","c":["山畔堂成祇自怜，凭高送目慰馀年。","江横木末风帆转，寺隐峰西午磬传。","野兴夤缘双短屐，斋居颠倒一青毡。","嘉宾莫为忧岑寂，涧溜园禽尽管弦。"]},{"t":"松坞草堂新成杂兴十二首 其四","f":"七言律诗","c":["何代新亭动客悲，皇都高拱控华夷。","梁陈割据今谁数，王谢风流空尔为。","王气接连天北极，江流襟带海东涯。","平冈极目烟霄迥，鸿鹄冥冥信所之。"]},{"t":"松坞草堂新成杂兴十二首 其五","f":"七言律诗","c":["投簪本意弄斑衣，痛哭郊原万事非。","玄壤遗封空石马，白头残喘尚荆扉。","乾坤有恨身同尽，五十无闻愿已违。","细雨山前新草长，寸心何以报春晖。"]},{"t":"松坞草堂新成杂兴十二首 其六","f":"七言律诗","c":["牛峰东南高触天，大石小石西苍然。","疏帘对隐乌皮几，浊酒閒吟白雪篇。","六代英雄埋野草，一川花柳媚江烟。","无端人世升沈事，莫近山翁醉舞边。"]},{"t":"松坞草堂新成杂兴十二首 其八","f":"七言律诗","c":["万峰云气入高斋，谷口冥冥细雨来。","实喜芳春能润物，虚疑残腊早闻雷。","谁家健犊临田出，无数寒鸦绕树哀。","已约新晴扶杖去，东风留绽野塘梅。"]},{"t":"松坞草堂新成杂兴十二首 其九","f":"七言律诗","c":["茅庐寂寂倚双峰，懒散无心拟卧龙。","阶下水流分细涧，檐前云宿拥高松。","何颙独有谈禅癖，阮籍偏于作吏慵。","早识人间行路恶，肯因书剑误明农。"]},{"t":"松坞草堂新成杂兴十二首 其十一","f":"七言律诗","c":["五岳殊方谁竟游，诛茅吾自爱吾丘。","林峦历历罗窗户，竹树萧萧拥道周。","梁燕每惊春梦破，野云能伴醉乡留。","欲看明月生秋海，指点东岩架石楼。"]},{"t":"种柳","f":"五言古诗","c":["桓公居汉南，睹树感摇落。","而我濒衰年，甫植数枝弱。","来者方无穷，何必在身乐。"]},{"t":"移松","f":"五言古诗","c":["小松擢新茎，春雨欣初移。","从今逮何日，始见虬龙姿。","峨峨栋梁具，念此乃知奇。"]},{"t":"引涧","f":"五言古诗","c":["山涧雨新溢，黄流浩纵横。","晨兴事疏引，下汇方池清。","物理各有因，匪人曷由成。"]},{"t":"洗竹","f":"五言古诗","c":["林竹有佳色，蔽翳空山阿。","一为伐榛莽，遂露青瑶柯。","幽怀寡相契，落目聊行歌。"]},{"t":"落梅篇","f":"古风","c":["金陵野老栖空山，肺病养恬长闭关。","端居十日阻春雨，梅花零落溪山间。","老干横烟惨难诉，残英覆地嗟谁数。","蜂黏香粉下苍苔，鸟啄璚瑶涴黄土。","城中看花长恨迟，来时池水含冰澌。","冷蕊犹封去年雪，韶华未动新春枝。","准拟入山开病眼，一日绕花千百转。","酿酒期邀友朋至，插篱苦避儿童剪。","丘壑萧条还自爱，荣华飘落那相待。","始知春厌衰病人，转觉天厚雄豪辈。","君不见五侯七贵开名园，梅花当春如雪繁。","和风丽日依期至，玉笛银筝对酒喧。","开时令鼓催青阳，飞处仙娥点靓妆。","花将地主相矜盛，人助花神剩斗狂。","物性随人异哀乐，我心与尔甘寂寞。","且寻世外逍遥游，开落荣枯付冥漠。"]},{"t":"夜雨","f":"五言律诗","c":["夜雨卧山斋，山空百泉响。","飞岚度虚棂，孤灯煨幽幌。","馀花愁尽落，细草忻初长。","春梦莽缠绵，独绕丘原上。"]},{"t":"晨起新霁","f":"五言律诗","c":["朝日出松际，幽禽语窗间。","盥栉事从缓，行坐意弥閒。","方沼水新绿，曲栏苔旧斑。","林风会人意，远送孤云还。"]},{"t":"复雨","f":"五言律诗","c":["新晴动方起，复雨静更嘉。","反关向幽室，焚香诵楞伽。","白日隐重云，青松坐群鸦。","明晦齐一观，嗒尔何咨嗟。"]},{"t":"对雨 其一","f":"五言律诗","c":["密密春林雨，沈沈昼日云。","阴阳随气序，膏泽自吾君。","积水鸥凫下，条风草木欣。","残躯胜耒耜，何敢废耕耘。"]},{"t":"对雨 其二","f":"五言律诗","c":["山迥雷声近，春深节气殊。","江天云雾湿，林壑画屏纡。","鸟困投檐户，溪狂掠坐隅。","老夫不出户，无意问泥涂。"]},{"t":"对雨 其三","f":"五言律诗","c":["春睡起何迟，茆厨湿未炊。","竹梢欹拂水，花片舞过篱。","老病消浮念，迂疏冷旧知。","独怜山郭雨，能与静相期。"]},{"t":"宗伯严公枉驾草堂惠诗因谢","f":"五言律诗","c":["寂寞山人宅，能劳长者寻。","烹葵同薄饭，刻竹动高吟。","草藉星辰履，云谐鸾鹤心。","寄言泉石畔，曾见几华簪。"]},{"t":"遣兴和三弟舜玉","f":"七言律诗","c":["三月馀寒散缊袍，夕阳行药过东皋。","金花抱雨松枝重，紫箨穿云竹笋高。","远蹑烟霞逃世网，细吟风月调朋曹。","春来病骨殊轻健，尽日登山未觉劳。"]},{"t":"幽居和徐禹亮","f":"七言律诗","c":["弱云横路飐游丝，春去山花不自知。","门巷草深玄鹿乳，池塘烟暝白鸥饥。","风鸣竹屿寒潇洒，日照荷衣翠陆离。","多病迩来人事减，深岩高卧复何为。"]},{"t":"苦疡出息东郊田舍二首 其一","f":"五言古诗","c":["东庄久不至，偃蹇废田作。","新桃堪系马，旧树已巢鹊。","儿童诧相问，黄犬吠颇恶。","自缘容鬓改，敢怪尔辈错。","吾生知有涯，尘鞅苦自缚。","每云遗冠裳，乃复恋城郭。","疮疡非我灾，相邀就林壑。","心源倏以静，口味日应薄。","循畦摘嘉蔬，披草采灵药。","患去四体轻，尘远六根脱。","溪流日洗耳，保此长寂寞。"]},{"t":"苦疡出息东郊田舍二首 其二","f":"五言古诗","c":["明月入我帷，照见床头书。","揽之起坐读，冥心向黄虞。","君王既神圣，黎庶俨如愚。","礼乐少虚文，法令颇宽舒。","民力尽耕凿，暇乃事畋渔。","生无冻饥苦，死也何羡馀。","浩荡宇宙间，聚散任所如。","周公太多事，六典过爬梳。","遂令斯鞅辈，展转生虫蛆。","燎原日以甚，伊谁之过欤。"]},{"t":"幽居十二咏和鲁南 其一 煮茗","f":"五言绝句","c":["为有馀酲在，还牵睡思繁。","汲泉敲石火，先试小龙团。"]},{"t":"幽居十二咏和鲁南 其二 焚香","f":"五言绝句","c":["烟生沈水细，火宿博山温。","鼻观自相媚，无劳矜返魂。"]},{"t":"幽居十二咏和鲁南 其三 洗砚","f":"五言绝句","c":["旧污涤乃去，新美净乃留。","清清池水侧，与尔勤交修。"]},{"t":"幽居十二咏和鲁南 其四 检书","f":"五言绝句","c":["眼迷四库籍，手倦三绝编。","愿寻橐驼传，送此龙钟年。"]},{"t":"幽居十二咏和鲁南 其五 扫径","f":"五言绝句","c":["清心唯素月，满意祇苍苔。","落叶时相妒，那能不扫开。"]},{"t":"幽居十二咏和鲁南 其六 捲幔","f":"五言绝句","c":["每报庭花发，烦余捲幔看。","东风先会意，吹搭小阑干。"]},{"t":"幽居十二咏和鲁南 其七 移榻","f":"五言绝句","c":["花开前后圃，月照东西檐。","总为怜花月，移床不自嫌。"]},{"t":"幽居十二咏和鲁南 其八 拭几","f":"五言绝句","c":["游尘彼何物，暗我净几光。","拂拭诚多劳，憎爱各有常。"]},{"t":"幽居十二咏和鲁南 其九 养蒲","f":"五言绝句","c":["芳根恶浮尘，纤叶爱澄露。","它生愿化汝，濯濯居净土。"]},{"t":"幽居十二咏和鲁南 其十 灌花","f":"五言绝句","c":["众芳植庭曲，地润花自饶。","物情苟相赖，可惮抱瓮劳。"]},{"t":"幽居十二咏和鲁南 其十一 摘蔬","f":"五言绝句","c":["右丞斋露葵，拾遗饭苍葈。","朱门竞肥秾，野老独宜此。"]},{"t":"幽居十二咏和鲁南 其十二 种树","f":"五言绝句","c":["种树取柔条，人言老难待。","所贵适目前，胡为计身外。"]},{"t":"喜雨柬东邻陈叟","f":"七言律诗","c":["草阁平池细点分，柴门杂树乱声闻。","游龙倒吸沧江水，舞鹤低翻紫阜云。","田舍病来怀稔岁，山瓶喜极判沈醺。","莫欺老手扶犁怯，荷策驱牛未让君。"]},{"t":"复雨","f":"七言律诗","c":["松林云气拂人流，茅屋雨声鸣不休。","庭潦旋添鹅鸭喜，稻苗先慰雁鸿谋。","疏帘寂静宜书卷，野壑苍茫忆钓舟。","寄语邻翁多酿酒，放歌沈醉送清秋。"]},{"t":"作亭后丘之上名清旷系之短吟","f":"七言古诗","c":["蓬莱微茫不可求，匡庐迢遰非易游。","掌中佳景任揽撷，不如后圃登吾丘。","吾丘清旷招远风，谢客妙语遗山翁。","古今乐事留宇内，天地于我何终穷。","天印苍苍钟陵紫，左右倒影山杯里。","白鸟南穿楚岫云，片帆东落吴江水。","卢鸿草堂何处开，陶令柴车日往来。","花间筑室支丹灶，石底穿池立钓台。","形胜随心动生趣，讴吟触口皆成句。","无官迹已混樵渔，有家誓不关婚娶。","高空雕鹗横秋目，近舍流莺鸣夏木。","但愿丰年秫米熟，山翁烂醉死亦足。"]},{"t":"午日","f":"七言律诗","c":["五月五日在田舍，城郭风光应自新。","燕女綵丝缠蝎尾，吴儿画楫斗龙鳞。","山中祇见榴无色，病后初知艾有神。","落日一杯桑柘底，邻翁相对野情真。"]},{"t":"东郊田舍戏占","f":"七言古诗","c":["北望紫山横紫烟，南窥天印削青天。","柴门古木行荒径，柳堰回溪抱野田。","蕉叶舞墙凡几处，藤根萦石自何年。","穿巢鸟鹊初将子，落簇红蚕已上绵。","行客卖茶微雨里，农夫依饷古槐边。","身抛岁月何须记，地远尘埃亦自怜。","卖却异书多买犊，收将狂性且逃禅。","申屠即树成居屋，陶令逢人馈酒钱。","云至剩添閒伴侣，花开新得小婵娟。","眠惊鹤啄弹琴石，坐爱鱼吞洗墨泉。","四大有生皆梦幻，一真无累即清玄。","所希畏垒庚桑子，莫羡丹阳葛稚川。"]},{"t":"忧旱二首 其一","f":"五言律诗","c":["南国久无雨，皇皇六月交。","池乾鱼伏网，林热鸟移巢。","淬魃临祠庙，迎龙就涧坳。","祇愁秋稼尽，何以度衡茅。"]},{"t":"忧旱二首 其二","f":"五言律诗","c":["野人遗世虑，水旱独关渠。","垤鹳鸣何验，江龙饮亦虚。","田畴堪一哭，祷祀竟何如。","夜坐看星月，临风益叹歔。"]},{"t":"松坞答鲁南对月见忆之作","f":"七言律诗","c":["良宵爱对空山月，赤旱愁侵独坐人。","江鹳不将时雨至，林乌还带晚霞新。","家依百亩心同切，地隔孤峰梦亦频。","野寺相随又相别，人间离合本无因。"]},{"t":"秋至亭上","f":"五言律诗","c":["关心唯碧树，豁目更苍岑。","雨喜蜻蜓出，秋惊蟋蟀吟。","狂歌穿竹响，瘦影照池深。","岂好逃城市，喧嚣自不禁。"]},{"t":"屏山田舍","f":"七言律诗","c":["小溪风露带渔舲，曲坞松杉接草亭。","夜久野云横树白，秋高山色过江青。","长亲拙政知农事，暂学清斋适性灵。","独笑吴中狂处士，强将身比少微星。"]},{"t":"食菌","f":"五言古诗","c":["嵇康食石髓，安期枣如瓜。","虚无不可致，想像生咨嗟。","深谷隐松桂，雨露抽灵芽。","名齐金光草，品异仙掌茶。","采采供晨飧，色瑩味亦嘉。","金膏溢齿颊，五内生云霞。","腥腐一以荡，神明发精华。","吾闻古灵仙，饵芝乃升遐。","从兹谢厚味，服尔登云车。"]},{"t":"中秋山中夜起玩月","f":"五言古诗","c":["中秋万古月，城阙玩每同。","今年展奇观，对此空山中。","圆魄出东岭，海气开洪濛。","长风扫浮翳，清辉荡遥空。","吴山翠千点，错列指顾中。","澄江动虚影，下彻鼋鼍宫。","天地同一色，苍茫浩无穷。","顾兔露其爪，冥冥避高鸿。","把酒发商歌，声激河汉东。","古今一瞬息，过客犹转蓬。","而我寓宇内，薨薨侣微虫。","生存不自乐，溘死徒忡忡。","鸡鸣且莫寝，坐迟初阳红。"]},{"t":"山夜","f":"五言律诗","c":["秋气振庭枝，山空响易悲。","草寒蛩语涩，树老鹊巢危。","古道因书得，衰颜赖酒持。","未忘蝉蜕念，真笑虎头痴。"]},{"t":"积雨","f":"七言律诗","c":["积雨蓬门客过稀，野人吹火炙寒衣。","禾畴乳鸭鸣相乱，柳径愁鸦坐不飞。","抱膝漫吟梁父曲，劳心真厌汉阴机。","清泉白石从吾好，驷马高车悟昨非。"]},{"t":"秋思","f":"七言律诗","c":["露下风高燕雁斜，秋光平落楚江涯。","霞绡堕树飘枫叶，雪浪排溪涨苇花。","爱酒虽贫多酿黍，避人无事远移家。","经旬积雨怜衰病，断绝门前问字车。"]},{"t":"野步","f":"五言律诗","c":["出郭病身健，还山秋日长。","云光漏疏木，岚翠集虚堂。","远害愁防虎，全生拟牧羊。","那知岩壑外，随步有康庄。"]},{"t":"野兴三首 其一","f":"五言古诗","c":["花岩控牛岭，连峰碧嵯峨。","秀色亘千古，我生能几何。","行几苦难屡，筑室枕其阿。","坐卧长对之，所获庶可多。","朝云结丹绮，夕月流金波。","采之鍊真液，永以蠲沈痾。"]},{"t":"野兴三首 其二","f":"五言古诗","c":["落日满秋野，独步登平丘。","山经夜来雨，寒泉出溪流。","缅怀古时人，开荒广良畴。","深山寡人力，劳此千岁谋。","去者水长逝，存者纤云浮。","往来但瞬息，百虑徒煎忧。","不如饮美酒，坐啸空岩幽。"]},{"t":"野兴三首 其三","f":"五言古诗","c":["苍隼摩天飞，黄鹄志千里。","秋空莽寥阔，快尔南溟徙。","浮云东北生，风雨飒然至。","六翮困沾湿，吹之堕寒水。","南山松桂阴，西畴稻粱美。","万事难预期，不如早栖止。"]},{"t":"夜坐","f":"五言古诗","c":["白露中夜寒，蟋蟀鸣床下。","簌簌葛衣裳，惨淡谢炎夏。","闺人戒机杼，田畯课场稼。","眷此岁载阴，蹇予日多暇。","朱颜黯以苍，短发不盈把。","商战讵能肥，蘧年未知化。","兀兀迷陈编，何以酬夙夜。"]},{"t":"邻叟见过","f":"五言古诗","c":["场雀惊且飞，篱犬隔树嘷。","开门见田父，饷我携浊醪。","寒暄甫及席，首陈入城劳。","继云太庙灾，策免数大僚。","京兆岁大比，荐拔多英豪。","请君望泰阶，清平在崇朝。","闻言谢田父，野语胡大谬。","我袖恨不长，无以掩君口。","进退国大政，柄在相与后。","挥霍如云雷，小民但奔走。","尔我服稼穑，所忧唯百亩。","出位而妄言，它人恐相诟。","山厨蒸藜熟，与君酌君酒。","明月生东山，移床就衰柳。"]},{"t":"幽怀二首 其一","f":"五言古诗","c":["文章经纬业，制作贵有程。","六籍出元圣，道奥非华英。","自从删述来，尔雅存西京。","马迁缀古史，笔力驱沧溟。","苏李起介胄，诗辞霭和平。","今观宇宙间，日月垂天明。","小儒竞绮丽，琐屑如繁星。","吾衰志未泯，愿缔诸贤盟。","扬雄强模拟，何啻苍蝇声。"]},{"t":"幽怀二首 其二","f":"五言古诗","c":["昌黎文章伯，后代罕俦匹。","李杜虽云雄，气格差甲乙。","奈何赋长篇，退让如自失。","想像巨刃扬，魂魄生战慄。","乃知作者苦，穷探极幽密。","譬对百战场，动静慎师律。","守正兼设奇，变化贵神出。","左车井陉谋，淮阴几见绌。","多畏乃胜人，名家有深术。"]},{"t":"散步","f":"五言律诗","c":["理生就田畴，辞喧出闾里。","自叹乏高风，时归念妻子。","栖鸦迷夕岚，浮雁唳寒水。","散步数群峰，日从天阙始。"]},{"t":"中秋对月和罗女文","f":"七言律诗","c":["高秋明月满天凉，露坐风生薜荔裳。","蟋蟀近床还独语，蟾蜍离海已深藏。","人间忽敞清虚府，地上平铺雪霰光。","笑玩素娥敲药杵，不劳银汉问舟航。"]},{"t":"雨后漫兴柬罗女文","f":"七言律诗","c":["春花落尽垂杨低，竹林鸣鸠相应啼。","夜来久旱得微雨，门前细草青萋萋。","饮虹桥头西日落，桥下水光摇草阁。","莫嫌野客杖藜来，瀹茗摊书殊不恶。"]},{"t":"东野 其一","f":"七言绝句","c":["天印山如天斲方，秦淮水萦练带长。","夜坐船头看明月，垂虹斜挂几飞梁。"]},{"t":"东野 其二","f":"七言绝句","c":["东山茅屋野人家，谢傅蔷薇春著花。","入市懒骑从事马，开园时种故侯瓜。"]},{"t":"新凉夜坐次彦明二首 其一","f":"五言律诗","c":["独鹤夜何事，松头栖复迁。","树凉占老态，禾熟受丰年。","细竹枝枝袅，明星个个悬。","年来知物化，无意更求仙。"]},{"t":"新凉夜坐次彦明二首 其二","f":"五言律诗","c":["残暑金风改，中宵白露寒。","秋期来朔雁，野服罢齐纨。","蛩响喧阴壁，萤光点石栏。","荷衰叶更起，留伴蓼花看。"]},{"t":"八月四日热","f":"七言律诗","c":["八月江南毒热新，火云郁郁尚蒸人。","井梧叶落太伤早，庭户蚊喧难及晨。","不见金天流素月，思沾玉露洗黄尘。","重寻箧笥开纨扇，始笑西风误认真。"]},{"t":"许彦明过荒斋看菊","f":"五言律诗","c":["寂寂柴桑宅，黄花但满园。","相将秋意晚，无奈晓霜繁。","珍重殊方种，艰危隔岁根。","玩来终澹泊，莫向美人言。"]},{"t":"雪中承刘司马许顾二司徒见过","f":"七言律诗","c":["北风吹雪拥篱根，高驾翩翩午扣门。","倒屣自怜庭户湿，围炉同待酒瓶温。","江山积素看松翠，闾井占年喜麦蕃。","茆舍萧条虚盛赏，殷勤烧烛伴黄昏。"]},{"t":"宪府王公载卿命酒期过草堂阻雪不至奉简一首","f":"七言律诗","c":["不诵清诗三十年，晚城佳会又虚传。","书来送酒春生户，兴尽回舟雪满天。","独向琼枝劳怅望，非干霜简绝攀缘。","江梅近暖参差发，还拟乘骢野水边。"]},{"t":"和陈鲁南遂初斋漫兴","f":"五言律诗","c":["投老书千卷，栖真屋数楹。","放形依鸟宿，仰面看云行。","雪棹谁乘兴，风瓢莫弄声。","归来追往事，无味是浮名。"]},{"t":"除夕二首和女文鲁南 其一","f":"七言律诗","c":["时序惊心独倚栏，敝裘犹耐故年寒。","饧糕饷节乡风旧，秫米逢秋酒债宽。","萱叶向阳铺砌绿，茶花冲雪透林丹。","青山已结登临约，且喜篮舆老更安。"]},{"t":"除夕二首和女文鲁南 其二","f":"七言律诗","c":["条风中夜转东方，醉恋残年更举觞。","白发空添寿者相，朱衣曾玷大夫行。","贪闻雪垄遗蝗陨，爱见春林旧柳长。","闾里高人多典则，追随何忝郑公乡。"]},{"t":"除夕","f":"七言律诗","c":["桃茢驱傩画荜门，椒花颂寿泻芳樽。","生涯喜傍农夫老，社会惭登大父尊。","长有蟹螯持左手，更添莺舌弄前轩。","天时代谢非吾事，莫为增年意转烦。"]},{"t":"和徐子仁除夕","f":"七言律诗","c":["蓬鬓休嗟老不堪，馀生都已付沈酣。","身旋蛙井元无几，岁历龙飞又十三。","江草向人寒更绿，塞鸿何事早辞南。","年来结念投禅寂，且喜维摩屡放参。"]},{"t":"和舜玉春日偶题","f":"古风","c":["小园泉石占清华，竹坞松堂静不哗。","悬薄护寒藏橘实，曲池?水灌兰芽。","缁衣老衲时求饭，纱帽幽人共煮茶。","门外东风摇五柳，居邻閒拟似陶家。"]},{"t":"和鲁南元夜雪","f":"七言律诗","c":["雪飞元夜玉盈除，灯射玻瓈烛影虚。","林借月华疑宿鸟，池添冰力困游鱼。","春愁正赖寒欺酒，老眼空劳夜照书。","火树银花交映地，留欢休问五更初。"]},{"t":"雪夜观灯和彦明二首 其一","f":"七言律诗","c":["春夜邀宾景物宜，雪华灯燄两争奇。","鹤翻玉羽迷仙驾，龙吐骊珠照酒池。","乐剧不辞金管噪，坐寒频唤画屏移。","祇缘郢曲高难和，岂是东君赏兴疲。"]},{"t":"雪夜观灯和彦明二首 其二","f":"七言律诗","c":["雪花凝素照虚台，薄暮谁披鹤氅来。","酒熟似邀灯节至，梅开应被笛声催。","临觞幸免当官累，投辖惭非劝客才。","莫笑田家无所献，火轮冰柱亦诗材。"]},{"t":"和鲁南新春","f":"七言律诗","c":["白雪酿寒仍送腊，红灯窥暖巧偷春。","神君綵仗鞭牛早，游女罗幡缀燕新。","泉石投交忘主客，齿牙垂老厌酸辛。","閒门旧友皆星散，唯有陈雷晚更亲。"]},{"t":"閒居四首 其一","f":"七言律诗","c":["太湖之石紫崔嵬，溪上茅斋对尔开。","指点庭心分泰华，依稀岩背宿风雷。","双飞鹊斗穿晴树，百转虫书印古苔。","明月不知吾懒散，夜深来照读书台。"]},{"t":"閒居四首 其二","f":"七言律诗","c":["黄阁朱楼槩太清，江山襟带旧神京。","开园更拟閒居赋，近市非干大隐名。","聊养孤豚供菽水，尚劳群雀恋柴荆。","薰炉药灶真馀物，合伴狂夫过此生。"]},{"t":"閒居四首 其三","f":"七言律诗","c":["城郭秋阴袭苧袍，林园稀到长蓬蒿。","蟏蛸傍树生罗网，野鹤临池惜羽毛。","年长渐惊朋辈少，形枯真悔簿书劳。","追欢未断清尊酒，左手犹堪擘蟹螯。"]},{"t":"閒居四首 其四","f":"七言律诗","c":["种柳今春拂地垂，黄鹂来挂最长丝。","高城过水衔青嶂，古树摇花照绿池。","猿鹤忘机堪结侣，马牛多病枉逢时。","扬雄错指玄经好，覆瓿他年总莫知。"]},{"t":"答许彦明见梦二首 其一","f":"五言律诗","c":["浪迹唯方外，劳生总梦中。","远公开净社，玄度有高风。","尘世閒难得，禅机病易通。","所希情性合，何必往来同。"]},{"t":"答许彦明见梦二首 其二","f":"五言律诗","c":["禅宫元寂静，况复雨连阴。","座有僧同饭，门无客见临。","妙香团狭室，远磬落高林。","谁信城中梦，超然契此心。"]},{"t":"和陈太仆生辰二首璘与太仆及惕庵总宪公同生时惕庵亡矣 其一","f":"七言律诗","c":["天当流火生同日，人羡乘车贵一时。","忍望列星悲傅说，愧颦衰貌对西施。","山中学道丹谁授，花底闻歌酒莫辞。","敢谓风云随变化，愿从泉石尽交期。"]},{"t":"和陈太仆生辰二首璘与太仆及惕庵总宪公同生时惕庵亡矣 其二","f":"七言律诗","c":["秋来卧病怀山阁，老去逢生怯酒尊。","拙政幸能追骑省，远游初免怨王孙。","亭亭野鹤閒过砌，寂寂云峰对掩门。","点检交知还自惜，白头今见几人存。"]},{"t":"雪中和王存约刑侍五首 其一","f":"五言律诗","c":["杪岁呈三白，农谈喜及时。","麦传全稔信，松挺后凋枝。","海冻愁龙伯，沙寒泣雁儿。","唯有袁安舍，高眠竟不知。"]},{"t":"雪中和王存约刑侍五首 其二","f":"五言律诗","c":["积素明幽馆，为祥表盛时。","风回先带霰，气煖不封枝。","被鹤无高士，悬鹑有冻儿。","君王忧四海，多少自应知。"]},{"t":"雪中和王存约刑侍五首 其三","f":"五言律诗","c":["天地云同色，江山皓一时。","梅狂花覆野，柳困絮黏枝。","鱼蛰坚冰壑，鸦迷返哺儿。","侯门炙朱火，寒透不曾知。"]},{"t":"雪中和王存约刑侍五首 其四","f":"古风","c":["璚楼无尽地，玉树不移时。","地脉消氛祲，园容发故枝。","裘轻飞猎骑，酒碧?歌儿。","灞涘许情好，惟应野客知。"]},{"t":"雪中和王存约刑侍五首 其五","f":"五言律诗","c":["南国穷阴候，东楼独坐时。","兴牵孤棹水，情绕野梅枝。","爱酒閒中圣，慵书卧遣儿。","衰年疏懒意，还赖故人知。"]},{"t":"春夜饮女文宅大醉翌日病眩负黄怀季之约诗以识过","f":"七言古诗","c":["东桥老人田野客，一生爱酒肠腹窄。","春来忽到罗含家，银瓮盈盈摇琥珀。","倾壶便饮不须劝，连举兕觥过累百。","据案狂歌惊四邻，但笑诸公太拘迫。","玉山欹仄夜方归，不寐坐倚平泉石。","天明始觉中圣人，眼光错莫乱朱碧。","地如车轮忽旋转，欲立还惊足盘躄。","黄公临垆复召我，安得奋飞生羽翮。","乃思旨酒古有戒，人生乐极终何益。"]},{"t":"元夜奉诸公饮瞻辰草堂","f":"七言律诗","c":["老去风情异少年，元宵留客纸灯前。","清筵素月宜觞咏，绣陌香尘隔管弦。","火树远飘烟霭处，星河斜挂雪晴天。","更阑不醉休辞去，回首欢娱易惘然。"]},{"t":"九日亭上独酌六弟送盘飧至有怀","f":"七言律诗","c":["九日山亭独举杯，盘飧远送白衣来。","乾坤大梦堪高枕，林壑衰年切孔怀。","近水脊令还自得，傍厓黄菊未全开。","茱萸且莫迎霜落，后至还期插帽回。"]},{"t":"九日喜何叔皮至山庄","f":"五言古诗","c":["山馆际佳节，川原秋气澄。","白日照禾黍，颇适幽居情。","曳杖登高丘，停车延友生。","契阔良已展，欢悰亦交倾。","浊酒写情愫，三爵匪充盈。","古处道所贵，浇漓安可徵。","风凄碧草变，露湿黄花荣。","感兹时物改，勖尔没齿盟。"]},{"t":"夜观陈鸣野画草堂壁作歌谢之","f":"七言古诗","c":["草堂素壁烛影孤，照君夜作山水图。","墨华如云生手底，高耸山岳卑江湖。","连林老树根株古，蛟龙盘拿撑爪股。","颠厓忽挂飞萝茎，长绳系日垂青冥。","天台石梁宛在眼，武夷幔亭亦非远。","桃源可觅秦人家，竹林似近梁王苑。","爱君胸次多崛奇，灵区胜概任尔移。","荒村每恨少叠嶂，草堂特地生幽姿。","猿惊隐隐号清夜，麋鹿依稀走阶下。","只恐城中好事知，天明户外喧车马。","我有穷愁愁不醒，感君遗我夫容城。","年年酿酒三千斛，闭门独醉云中行。"]},{"t":"望雪怀陈鸣野二首 其一","f":"五言律诗","c":["野雪清如许，高人不见留。","谁家金帐酒，能及剡溪舟。","群木瑶华积，千山素影流。","幽怀狂不定，孤啸一登楼。"]},{"t":"望雪怀陈鸣野二首 其二","f":"古风","c":["风急雪纷纷，楼高野望分。","霏霏过树远，片片洒窗闻。","林冻玄?哭，云迷白鹤群。","正思陶隐士，漉酒共清醺。"]},{"t":"饮女文宅冒雪夜归","f":"七言律诗","c":["醉后那知雪片稠，瑶花千点集貂裘。","清吟乍别梁园宴，豪兴能欺剡曲舟。","素羽风前迷鹭渚，玉鳞云外见龙楼。","颠狂欲上城西阁，坐玩寒江练影流。"]},{"t":"闰十二月三日蒸燠其夜迅雷大雨同鲁南纪变一首","f":"古风","c":["季冬闰月忽暄燠，惊见蚊?当户飞。","自缘雷雨好解作，谁道阴阳难范围。","四时吕览有定令，五事箕畴无少违。","为检金縢看故事，分明人道应天机。"]},{"t":"元夜楼望","f":"七言律诗","c":["夜阁临衢倚醉凭，江南佳丽尚堪称。","春光竟惜千门月，节序仍誇九市灯。","香雾横街人似锦，歌钟何处酒如渑。","长吟秉烛星桥曙，犹记狂夫少日曾。"]},{"t":"登太岗慈善寺","f":"五言古诗","c":["野寺冠山椒，溪门下弘敞。","荒蹊缘涧入，危磴蹑云上。","松花风际飘，麦苗雨中长。","高树倚岩生，特立气森爽。","何年劫火馀，绀殿灭银榜。","徒闻佛道尊，胡乃失龙象。","悠然憩前轩，云峰矗相向。","下有良田畴，平视如指掌。","春莺流远音，脩竹惬幽赏。","何必五台山，始可资静养。","斜阳且归去，暇日期再往。"]},{"t":"宿祝釐寺晚浴","f":"五言古诗","c":["山居少尘事，行吟步高舂。","连林不知远，倏度云间峰。","寺门幽径熟，婉㜻抚长松。","禅老款虚室，情亲色弥恭。","玄论烬华烛，疏食临暮钟。","浴我清净水，形骸缅冲融。","虚襟释滞念，真气生灵宫。","蒲团结跏趺，宛坐青夫容。","就枕忽成寐，梦觉忘所从。","天明返蓬户，日出山烟浓。"]},{"t":"游丘常侍山园二首 其一","f":"七言律诗","c":["山蟠大野翠堪怜，树老深岩忘岁年。","画阁地清临水见，紫泉声远隔花传。","前林别墅通三径，暇日禅床借半毡。","叨际圣明空懒散，狂歌时复和薰弦。"]},{"t":"与陈大鲁南游天宁寺二首 其一","f":"五言律诗","c":["野寺青霄畔，攀厓扣法堂。","山铺平野阔，江绕大都长。","凿石开花坞，梯云架竹房。","城中车马客，谁解就荒凉。"]},{"t":"与陈大鲁南游天宁寺二首 其二","f":"五言律诗","c":["峻岭香台峭，高林夏气清。","山分龙阜色，涧别虎溪名。","野酌临归鸟，昏钟吼卧鲸。","坐依云雾窟，那有市朝情。"]},{"t":"同鲁南祝禧寺结夏八首 其一","f":"五言律诗","c":["酷暑欺吾病，空林共尔寻。","云高群木爽，日落半岩阴。","散发忘宾礼，清心悦梵音。","坐依禅榻畔，幽思自萧森。"]},{"t":"同鲁南祝禧寺结夏八首 其二","f":"五言律诗","c":["断酒狂全减，抛书懒更成。","山深人事息，僧老道心平。","坐石分松影，横琴理涧声。","夜凉清不寐，披草月中行。"]},{"t":"同鲁南祝禧寺结夏八首 其三","f":"五言律诗","c":["身住清凉界，那知有郁蒸。","蒲纤梳翠发，瓜冷嚼红冰。","病退生为我，家忘味近僧。","老禅麾麈尾，时见落青蝇。"]},{"t":"同鲁南祝禧寺结夏八首 其四","f":"五言律诗","c":["爱尔山中静，犹憎蝉噪繁。","松杉气无暑，宾主坐忘言。","翰墨陶真性，瓜蔬点薄餐。","悠然泉石味，难向贵人论。"]},{"t":"同鲁南祝禧寺结夏八首 其五","f":"五言律诗","c":["翻经非有愿，击磬果何心。","偶尔依莲社，翛然近竹林。","松风馀万顷，萝月抵千金。","莫买深山隐，禅关日可寻。"]},{"t":"同鲁南祝禧寺结夏八首 其六","f":"五言律诗","c":["金堂虚隐雾，石壁冻含霜。","坐久收葵扇，吟多问豆浆。","虎眠浑不猛，鹤舞暂为狂。","满目无尘事，虚襟亦自凉。"]},{"t":"同鲁南祝禧寺结夏八首 其七","f":"五言律诗","c":["祇园不尽景，留客易经时。","野竹团寒翠，池莲散素姿。","茶香修夜供，杞菊订秋期。","吾已嗔吾扰，无劳大众知。"]},{"t":"同鲁南祝禧寺结夏八首 其八","f":"五言律诗","c":["净社难求友，高人合在山。","泉甘出石井，树老映苍颜。","暑月谁偏爽，劳生今始閒。","秋风何日至，叠巘拟重攀。"]},{"t":"同诸客雨后登牛山绝顶","f":"五言律诗","c":["晴峦临晚照，悬磴蹑秋空。","地胜群贤集，天清四望通。","猱升攀仄石，鸾啸激悲风。","独仰皇居近，彤云护紫宫。"]},{"t":"登牛首两厓颠","f":"五言古诗","c":["双阙峙天表，巨鳌戴云浮。","秋空气先爽，预惬登高游。","攀缘千仞起，曲折百盘周。","苍林忽在下，手挹河汉流。","累累支机石，荒池饮牵牛。","峥嵘罗众山，俯视但微丘。","北瞻黄金阙，五城十二楼。","高帝圣图远，设险开皇州。","鼎湖不可望，苍梧云影愁。","长江渺一发，孰与吾乘桴。","舒啸振铃阁，诸天风飕飗。","落日下西岭，惨怆增人忧。"]},{"t":"登华岩","f":"五言古诗","c":["花岩久不至，脩竹倏满岭。","息驾大观堂，尘目快秋骋。","短衣陟中峰，仄见西日影。","天低雕鹗近，云重松杉冷。","列嶂难为雄，长江不知永。","牛山亦下对，楼观缀佳景。","庄严侈象教，喧卑薄人境。","扪萝步兢兢，憩石心耿耿。","它生果无因，兹游固何幸。","风林忽暮钟，谡谡动深省。"]},{"t":"祖堂寺逢海天僧","f":"五言古诗","c":["古融始入道，开山此为家。","疏泉策两虎，啮洞驱神蛇。","天龙作人象，献供持岩花。","一闻真空诠，振锡却诸邪。","跏趺了无事，竟乘大牛车。","影堂灯悠悠，白日长西斜。","幽寻入山麓，庭宇忻静嘉。","门深蔽古树，涧冷生青霞。","柿实寒少叶，桂枝蠹仍华。","老僧馀道气，款语谈楞伽。","自言非中孚，请馈仙掌茶。","相送过溪别，归路喧昏鸦。"]},{"t":"宁海寺访达公不遇","f":"五言古诗","c":["禅龛寄林杪，信是高僧居。","蒲团间陶钵，不置贝叶书。","幻火恼维摩，饭蔬长晏如。","诛茅辑佛宇，凿地延僧庐。","有金尽布地，只衲不留馀。","入林拾橡子，一室但空虚。","侍者守松院，迎余驻柴车。","焚香设清供，道念为之舒。","朱门厌腥腐，驷马驰双旟。","岂不羡荣贵，反侧多忧虞。","颓年向短促，薄俗背迂疏。","永愿结莲社，优游度桑榆。"]},{"t":"弘济寺江阁","f":"五言古诗","c":["北山高无极，江水下浤深。","飞阁嵌虚无，宛挂垂萝阴。","危柱袅相拄，棂轩控千寻。","游目信绝奇，蹑足惧弗任。","旁临得平坂，云水际萧森。","参差罗高木，倾仄悬灵岑。","洪波动其前，浩渺空人心。","劳歌不自慰，浊酒时一斟。","天长去鸟没，日落清猿吟。","欲止神悚惕，踟蹰下空林。"]},{"t":"燕子矶","f":"五言古诗","c":["名山意自胜，临水趣转幽。","况兹燕矶秀，复枕澄江流。","孤根托何所，上抱云中楼。","空冥瞰水府，下见鼋鼍游。","冲涛荡危石，翻恐地轴浮。","元气旋混茫，长风吹不休。","西来叠浪色，发自岷峨陬。","杏霭众山影，依微行客舟。","徙倚白日暮，极目令人愁。"]},{"t":"关祠","f":"五言古诗","c":["汉季昔鼎沸，孙曹窃王疆。","帝胄拥剑门，龙虎争奋张。","桓桓万人敌，东盼无荆襄。","运移见倾覆，孰云谋匪臧。","生为吴国仇，死食吴人乡。","烈气横四海，遗灵戴今王。","江边庙门古，松柏寒苍苍。","英爽如有临，风起旌旗翔。","君看祠前水，万古东流长。"]},{"t":"崇化寺梅泉","f":"五言古诗","c":["昔游岩中寺，梅花覆寒泉。","不到三十载，梅摧秖空岩。","陵谷幸无改，岂嗟浮物迁。","清源出细窦，浅草涵微涓。","山僧诵经处，独有龙蜿蜒。","冲襟静相照，尘鞅忽已捐。","漱齿叙幽事，洗钵修净缘。","古殿夕阴起，苍林生远烟。","佳兴不可尽，延伫情悠然。"]},{"t":"嘉善寺观石壁","f":"五言古诗","c":["苍石斲苍云，谁遗空山里。","藤萝覆细路，披烟得奇诡。","巉岩负龙脊，㟏岈露鳌齿。","脩竹照人青，幽花傍泉紫。","树古走危根，欲断不可止。","金陵百名胜，无地可胜此。","老禅堕贪痴，秘匿胡乃尔。","天地终劫灰，况我二三子。","取笏端下拜，托交自今始。"]},{"t":"幕府山望江","f":"五言古诗","c":["昨梦江上游，巨浪动枕前。","今登山头望，江色转可怜。","青峰几千仞，倒卧中流天。","人声落浦溆，树杪浮行船。","物理反相媚，乐意良已偏。","因寻达磨室，仰叩西来禅。","面壁恐心死，渡芦事亦颠。","不如结同好，啸咏攀云烟。","一醉更一醒，明日还复然。"]},{"t":"顾氏北麓草堂","f":"五言古诗","c":["谷口花冥冥，井上梧桐清。","山人筑岩户，避俗兼逃名。","种黍牛犊长，养蚕桑柘成。","野外无别储，浊酒贮瓷罂。","上以奉坟墓，下以延友生。","客来款茆檐，山大了不惊。","大儿富文史，楚楚解将迎。","药院共游衍，松林屡经行。","三宿竟忘返，屐齿缅已平。","乃知隐沦者，秖在王都城。"]},{"t":"登茅山三峰四首 其一","f":"七言律诗","c":["上界灵宫悬碧落，层峦飞步蹑彤霞。","尘身乍礼金银阙，天路疑逢龙虎车。","三洞南盘通海峤，五云西拱见京华。","清游胜览欢无极，却叹人间日易斜。"]},{"t":"登茅山三峰四首 其二","f":"七言律诗","c":["迢遰三峰得峻跻，到宫唯见众山低。","天池水碧苍龙伏，岩树风高白鹄栖。","云际瑶坛开日月，林间丹井隐虹霓。","仙人只在华阳境，松叶桃花咫尺迷。"]},{"t":"登茅山三峰四首 其三","f":"七言律诗","c":["头白游山恨已迟，遍寻灵迹慰幽期。","云根变幻阴晴石，海眼潜通霹雳池。","绝壁传觞临过鸟，深林炊黍茹生芝。","踟踌陵谷伤今古，不见前朝宰相碑。"]},{"t":"登茅山三峰四首 其四","f":"七言律诗","c":["东南佳气拥三山，台殿参差指顾间。","福地岩峦天下胜，神君笙鹤夜深还。","林衔落照秋仍丽，人对寒云意转閒。","晚下前峰明月起，更临幽涧弄潺湲。"]},{"t":"龙池","f":"五言律诗","c":["蛟龙宅大海，山椒非所藏。","吾疑蝘蜓种，野语谁张皇。","祷祠兴云雷，历代纪祯祥。","神物变乃尔，化理焉能详。"]},{"t":"喜客泉","f":"五言律诗","c":["嘉客入门笑，灵泉应之翻。","岂因孟尝死，化此山中魂。","迸珠疑贯缕，罗星或按垣。","喜余果何事，欲叩竟无言。"]},{"t":"华阳洞","f":"五言律诗","c":["穹厓积铁古，下嵌仙人宫。","流观洞天记，渺与林屋通。","把火惊石燕，吹箫动潭龙。","微茫失归路，返照秋林红。"]},{"t":"巧石","f":"五言律诗","c":["三茆奠神皋，灵槩萃兹谷。","怪石非一状，蛟虎争起伏。","苔花烂如绣，藤根走相束。","残醉吾未醒，曲肱枕云宿。"]},{"t":"左纽柏","f":"五言律诗","c":["仙翁鍊金鼎，化自秦汉前。","祠树岁月古，霜皮相纠缠。","道家骋神怪，谩语诬人天。","吾嗔雷君忍，一火无留烟。"]},{"t":"隐居墓","f":"五言律诗","c":["薄俗昧上善，高贤葆清真。","图牛惮为牺，古墓今犹珍。","松风有馀听，草露无长春。","徒使轻举士，依稀慕芳尘。"]},{"t":"曲林歌赠曹君时范十首 其一","f":"七言绝句","c":["华阳隐居空旧名，曲林精舍筑新成。","山头一片青苍石，领略高人万古情。"]},{"t":"曲林歌赠曹君时范十首 其二","f":"七言绝句","c":["大茅峰头多白云，谁能持取赠东君。","高车驷马当年事，海思霞情后代闻。"]},{"t":"曲林歌赠曹君时范十首 其三","f":"七言绝句","c":["灵踪古迹盖江南，中馆居中日可探。","云洞斜封埋壁地，石峰高插积金庵。"]},{"t":"曲林歌赠曹君时范十首 其四","f":"七言绝句","c":["楚王涧前秋水生，泠泠绕舍玉琴鸣。","道人独爱林中静，泻向圆池一镜平。"]},{"t":"曲林歌赠曹君时范十首 其五","f":"七言绝句","c":["山腰石楼风露新，桂枝蕉叶拂游尘。","幸无七贵倾高盖，长礼三峰作大宾。"]},{"t":"曲林歌赠曹君时范十首 其六","f":"七言绝句","c":["元符宫连秋树林，烟峦雾壁昼阴阴。","芝潭对饮斑文鹿，竹坞孤飞雪色禽。"]},{"t":"曲林歌赠曹君时范十首 其七","f":"七言绝句","c":["凋尽山中宰相松，长风无地吼蛟龙。","曹公种子苍髯老，更引寒涛响后峰。"]},{"t":"曲林歌赠曹君时范十首 其八","f":"七言绝句","c":["匡庐江涛不可经，武夷南天空自青。","何似三茅近京国，缠联王气会仙灵。"]},{"t":"曲林歌赠曹君时范十首 其九","f":"七言绝句","c":["曲林主人踪迹奇，前身陶公安可知。","脩殿灵官投化主，朝山香客拜生祠。"]},{"t":"曲林歌赠曹君时范十首 其十","f":"七言绝句","c":["方瞳墨发地行仙，谁信山翁七十年。","兴剧夜游轻猛虎，身轻朝陟俯飞鸢。"]},{"t":"茅山步虚词","f":"五言古诗","c":["太仪拓洪宇，灵山开福庭。","洞天窍华阳，地肺浮金陵。","展公始羽化，茅君遂遐升。","王老发玄旨，上元授真经。","乘风出埃壒，餐霞谢膻腥。","三真登虚府，九锡冠仙卿。","百神镇侍卫，八极恣游行。","金堂日星耀，玉洞烟云冥。","天地咸得一，万古歌清宁。"]},{"t":"还家同金士希诸君游牛首","f":"七言律诗","c":["金陵山水四方闻，天阙嵯峨更不群。","台殿散临云外起，冈峦遥向日边分。","幽人兴发清虚界，正月春生锦绣文。","莫怪还家先到此，他乡魂梦每殷勤。"]},{"t":"早秋过斌公山房和许彦明三首 其一","f":"五言律诗","c":["钟磬花台寂，云霞松坞深。","石林秋不热，水国昼多阴。","结束非吾意，逍遥近佛心。","莫言追往昔，聊喜悟来今。"]},{"t":"早秋过斌公山房和许彦明三首 其二","f":"五言律诗","c":["青嶂白云蒸，高台野客登。","鸟迷方外路，云护定中僧。","对酒狂何在，翻经老尚能。","摩挲岩下石，坐语记吾曾。"]},{"t":"早秋过斌公山房和许彦明三首 其三","f":"五言律诗","c":["济胜无强足，幽寻亦据梧。","僧门远市井，秋色澹菰蒲。","定息看香篆，逃禅托酒壶。","浮名百年祟，遣尽莫重沽。"]},{"t":"永兴寺结夏","f":"五言律诗","c":["濯发莲花水，清风满面吹。","松高迎日早，僧老下床迟。","施食鸟频至，翻经鹤静窥。","物情浑不远，幽兴自相宜。"]},{"t":"九日同太宰严公城西汎舟二首 其一","f":"七言律诗","c":["九日江门芦荻秋，登高何似汎兰舟。","城临曲水天河转，地接仙台苑树浮。","佳节壶觞随酩酊，上公轩盖倍风流。","迂疏独笑陶彭泽，漫插茱萸亦满头。"]},{"t":"九日同太宰严公城西汎舟二首 其二","f":"七言律诗","c":["兰桡东荡曙烟开，菊斝西冲落照回。","夹岸山岚飘几席，绕城波色动楼台。","都人节序遗风旧，词客秋吟发兴哀。","偃仰皇州多胜槩，挥毫何以继仙才。"]},{"t":"次赵克用游灵谷三首 其一","f":"七言律诗","c":["禅宫寄在万松深，绀殿阴阴入紫岑。","古碣长留开士影，颓廊堪惜画师心。","嗟余卧病虚春色，爱尔清斋听梵音。","石室乘凉十年事，诗成幽兴转难禁。"]},{"t":"次赵克用游灵谷三首 其二","f":"七言律诗","c":["入山飞翠满衣襟，一径松萝曲坞深。","龙寝云高横王气，鹤林风定净禅心。","开堂为有真僧出，避地应无俗累侵。","响石灵泉多胜迹，与君扶杖细相寻。"]},{"t":"次赵克用游灵谷三首 其三","f":"七言律诗","c":["紫厓苍巘隐云房，春尽唯闻药草香。","风磴喷泉晴欲雨，石林含露午生凉。","醉怜半落花辞树，坐叹西飞日转廊。","回首碧城灯火乱，淡烟疏柳路微茫。"]},{"t":"同鲁南宿天界竹居","f":"七言律诗","c":["白首同归桑梓日，旧游山水得重过。","聊依僧饭炊菰米，更理渔蓑缀薜萝。","花老不知春事尽，竹深偏爱雨声多。","旁人莫讶追欢剧，岁月翩翩奈尔何。"]},{"t":"同鲁南天界方丈对雨","f":"七言律诗","c":["与子避俗祇园深，高阁雨鸣如洗心。","芳草杜门无马迹，墨云缠树有龙吟。","堪怜把笔临池水，况复衔杯对竹林。","终岁驱驰城郭里，幸于支遁此开襟。"]},{"t":"祝禧寺群公游集二首 其一","f":"五言律诗","c":["桐馆延高驾，霞门集绣裳。","山深寒隐日，松老翠含霜。","共洽壶觞兴，仍探翰墨场。","临风意披豁，飞镝试穿杨。"]},{"t":"祝禧寺群公游集二首 其二","f":"五言律诗","c":["旧国开今代，新亭异昔游。","江山衔日转，宫阙抱云浮。","胜赏群公得，高情百世留。","蹇余丘壑陋，觞咏托名流。"]},{"t":"和徐子仁游虎丘四首 其一","f":"五言律诗","c":["胜地遥相引，清川澹自临。","散怀盘石大，洗耳剑池深。","僧气饶云月，岩居傍竹林。","坐来神易怆，松籁莫哀吟。"]},{"t":"和徐子仁游虎丘四首 其二","f":"五言律诗","c":["溪门藏曲坞，入寺始知奇。","石悟生公法，山传白傅诗。","浮云催短世，裋褐傲清时。","莲社容吾酒，终当共尔期。"]},{"t":"和徐子仁游虎丘四首 其三","f":"五言律诗","c":["漫踏书台路，那逢讲席人。","泉争惠山品，地避子城尘。","幽林云隐见，峭壁玉嶙峋。","本性宜岩穴，劳生负此身。"]},{"t":"和徐子仁游虎丘四首 其四","f":"五言律诗","c":["诗书贫自得，云水老何厌。","世味僧边减，山容雪后添。","狂摩试剑石，醉眺大吴岩。","莫笑归期缓，名蓝客易淹。"]},{"t":"夕阳同王礼部陈太仆过东山僧房","f":"五言律诗","c":["落日过山寺，怀贤伤古今。","谢公去已久，渌水歌声沈。","云壑延高驾，风林净夏襟。","倾杯莫愁晚，明月在东岑。"]},{"t":"和鲁南永福禅房二首 其一","f":"七言律诗","c":["支公本是禅林秀，更爱祇园在近乡。","问柳寻花唯竹杖，解衣支枕有山堂。","云浮世界知空寂，雪满头颅叹老苍。","闻说庵摩罗结果，灯前攀取一开尝。"]},{"t":"和鲁南永福禅房二首 其二","f":"七言律诗","c":["山人每为看山出，唯有山云不待期。","草长乍经春雨后，江明偏近夕阳时。","前林犬吠僧归远，古殿钟鸣客散迟。","除却陶潜贪酒盏，不知莲社复容谁。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其一","f":"七言律诗","c":["秋日端居愁不眠，出门骑马踏苍烟。","衣沾湿翠经厓崿，耳洒寒声接涧泉。","梦到桃源询往代，疑逢石髓见灵仙。","金陵岂独称佳丽，咫尺名山是洞天。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其二","f":"七言律诗","c":["马首遥随碧涧东，人家多住白云中。","龙泉沸处还生虹，虎洞腥来自起风。","向子正当婚嫁毕，阮生休叹路途穷。","曾闻天汉支机石，肯信高岩不可通。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其三","f":"七言律诗","c":["紫山东转接江门，万壑千峰拥孝园。","远结云霞连海岛，回瞻日月蔽昆崙。","牵萝步入岩间寺，选树来倾石上尊。","猿啸正堪淹白昼，鸦栖浑已报黄昏。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其四","f":"七言律诗","c":["鼎邑元当万方会，桥山今集百灵朝。","宫城抱日云常绕，陵树擎霜叶后凋。","衰晚空林从坐卧，太平深谷有歌谣。","此中合共渔樵老，丛桂淮南莫更招。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其五","f":"七言律诗","c":["盘空石路草纤纤，白鹤仙人尚有岩。","松偃即披云作盖，瀑飞还挂水为帘。","采芝绮夏何须出，食蕨夷齐亦太廉。","种黍满田长酿酒，栖迟何叹岁年淹。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其六","f":"七言律诗","c":["六代干戈龙战残，青山依旧绕江干。","石麟不省玄堂改，漆阁徒伤翠柏寒。","庾信归来空有赋，陶弘老去竟何官。","飞鸿欲避林间犬，万里冥冥振羽翰。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其七","f":"七言律诗","c":["官路桥东锦石峰，平原开出玉芙蓉。","高标云雾天中积，远势波涛水上重。","喜近鱼梁堪把钓，拟修丹室预栽松。","紫苔苍藓饶秋色，埋骨它年赖尔封。"]},{"t":"秋日寻城东诸山颇历深险得诗八首 其八","f":"七言律诗","c":["竹杖逶迤蹑紫霞，羊肠山径莽横斜。","林深更隐彭城馆，寺古犹传谢尚家。","阴洞闭云飞石燕，寒藤悬树堕风花。","周颙去后移文在，此地何人领物华。"]},{"t":"冬日同诸公饮凭虚阁","f":"七言律诗","c":["寺阁吟诗腊月中，拥裘行酒气弥雄。","江山过雪生新色，天地凝寒渺太空。","独去鹰鹯迷落日，后凋松柏倚高风。","须知霜月光偏胜，莫道冰林赏易穷。"]},{"t":"卜得彭城乐丘漫赋用鲁南韵","f":"七言律诗","c":["买山初费卖文钱，预卜新丘古涧前。","旧日高人招隐地，此生逆旅待终年。","烟霞寄傲深成癖，去住忘情澹入禅。","白发光阴知几许，紫泉丹壑且夤缘。"]},{"t":"雪后归自南郭","f":"七言律诗","c":["雪后帝京聊骋望，冰天悬影照人寰。","遥瞻丹凤分银阙，周览青龙展玉山。","广野漫铺明月色，白波摇动大江湾。","多情独倚新亭树，更爱长风洒醉颜。"]},{"t":"祝禧寺望积雪","f":"五言律诗","c":["岩谷素华积，禅房朝倚阑。","为怜珠树丽，宛坐雪山寒。","白以空为色，冰因冻作乾。","太阳休见恐，生灭本同观。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其一","f":"五言绝句","c":["门接登山径，窗临洗药泉。","草堂幽意足，况复近皇川。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其二","f":"五言绝句","c":["眺迥苍茫外，探奇紫翠中。","忘机同海鸟，脱迹比云鸿。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其三","f":"五言绝句","c":["清玄非晋代，岩壑胜山阴。","群从差强意，时来醉竹林。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其四","f":"五言绝句","c":["携樽登树饮，抱被枕流眠。","本性疏狂甚，非关慕昔贤。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其五","f":"五言绝句","c":["真閒聊野服，至乐止人寰。","肯为神仙误，虚寻度索山。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其六","f":"五言绝句","c":["新亭高处望，今代异风云。","紫殿开京观，龙成五采文。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其七","f":"五言绝句","c":["星散南山寺，乘春取次登。","封筒来往数，随处得诗僧。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其八","f":"五言绝句","c":["牛峰悬殿阁，对削献花岩。","感慨千年杏，摩挲十丈杉。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其九","f":"五言绝句","c":["江动新林浦，天垂大石峰。","四围山万点，云海濯夫容。"]},{"t":"陈鲁南学士自山东寄遁志十绝和之 其十","f":"五言绝句","c":["旧路石冈僻，新堂松坞深。","春风猿鹤侣，扶杖远相寻。"]},{"t":"寄荅陈大藩参二首 其一","f":"五言律诗","c":["官重今方伯，旬宣事独贤。","情飘五湖外，诗出万人传。","玉署虚仙籍，春江梦钓船。","祇愁凫舄影，难离紫宸天。"]},{"t":"寄荅陈大藩参二首 其二","f":"五言律诗","c":["卧病春山里，劳君省阁思。","衰颜丹鼎笑，晚计白鸥知。","应接才仍拙，渔樵兴颇宜。","万缘空欲尽，犹自未忘诗。"]},{"t":"贻霷僧","f":"七言绝句","c":["埋头不振苍龙锡，合眼犹持白马经。","门外任教双毂转，堂中长对一灯青。"]},{"t":"赠金山僧圆济","f":"五言绝句","c":["山僧扣我门，秀发金山骨。","相见了无言，空庭踏秋月。"]},{"t":"送斌上人游杭州","f":"五言古诗","c":["斌公禅林秀，前身海潭龙。","明珠濯清水，本性长玲珑。","少事大虚老，空门初发蒙。","拜趋陈庄座，金篦刮双瞳。","低心达磨壁，捧钵曹溪宗。","天界大丛林，跏趺坐堂中。","头陀满四座，发难如扣钟。","吾衰谢抖擞，卧疾维摩宫。","与子强荅问，而岂明真空。","支许方外交，聊以息微躬。","今晨告余别，游方海之东。","礼佛普陀岛，参禅雪窦峰。","青莲被寒沼，白月悬秋穹。","行色有佳景，归云无定踪。","我有振衣地，寄在杭万松。","浩渺湖海接，逶迤岩壑重。","尔往结莲社，陶谢将无同。","长谣写心曲，托寄东林风。"]},{"t":"分题得秦淮寿龙致仁","f":"七言古诗","c":["秦人凿淮古城碛，秦时流水今如昔。","地下黄金空自深，天门紫气逾辉赫。","六代烟华涨锦云，龙江鹭渚澄青碧。","形胜今开天子都，风流更隐幽人宅。","幽人抱艺入承明，能使四海传高名。","翻然解组归淮水，笑弄渔舟自濯缨。","闻道舍傍葛仙井，的烁丹砂彻夜明。","与君共泥紫金鼎，手把霓旌游太清。"]},{"t":"寿姚孟恭七十","f":"七言律诗","c":["脩竹老翁何所求，紫芝歌动傲王侯。","逃名岂羡金门贵，学礼仍看玉树稠。","大道长生唯药鼎，清谈终日有茶瓯。","堪誇世范传儒素，已许乡评占胜流。"]},{"t":"寿易太守士美","f":"七言律诗","c":["清修乡国老文儒，后辈跄跄总不如。","黄霸有才聊试郡，伏生从少已传书。","高才晚剖荆山玉，美政新还合浦珠。","林壑光阴方洒落，莫教门外候安车。"]},{"t":"答汪中丞见怀","f":"七言律诗","c":["雅望同归天下贤，知心初附白头年。","拟将东海论交谊，几向西湖费酒钱。","石涧行临三竺水，茅亭吟对万松天。","相望千里能相忆，满纸高情护碧烟。"]},{"t":"送林伯章","f":"七言律诗","c":["金陵帝城天下会，名胜从前特称最。","观风季札自何来，巍冠峨峨垂缓带。","龙山虎阜翠烟浮，曲浦澄江素月流。","唱罢骊歌向人别，城西一访谪仙楼。"]},{"t":"赠秋官叶敬之奏最北上","f":"七言律诗","c":["三年持法白云司，直道人歌张释之。","竹简下帷工旧学，桃花留县有馀思。","每缘正气瞻台岳，幸接交情老鬓丝。","才俊尔来多近侍，看君摇佩入丹墀。"]},{"t":"赠沈少刚","f":"七言律诗","c":["东浦清清连太湖，太湖水光秋可娱。","美人乘舟明月底，戏引骊龙出弄珠。","黄公垆头沽酒醉，一曲吴趋天下无。","请君早出济黔首，归来东浦随吾徒。"]},{"t":"赠胥大夫","f":"七言古诗","c":["洞庭水波混天色，君山嵯峨奠江国。","岳阳楼头一开眼，造化高深坐中得。","紫绶若若方离腰，浮生万事如云飘。","采服诸郎递起舞，醽醁满泛黄金瓢。","醉醒不复问天地，日倚南窗咏松桂。","仙老休传九转丹，大夫自度三千岁。"]},{"t":"雏凤行贺李少宰梦弼生子","f":"古风","c":["雏凤本出西昆崙，百鸟奉之巢帝阍。","大声鼓鸣震海水，羽毛焕烂光朝暾。","衔书献瑞降神德门，乃为少宰之子司徒之孙。","英物生来不嫌晚，秀骨堕地人传喧。","犀顶双开日月角，公侯异种由根源。","邺侯万卷行可展，立地便见乘华轩。","家书飞鞚入东省，看君黄气眉棱鶱。","两乡竞作汤饼宴，莫惜烂醉双金樽。"]},{"t":"相士吴立","f":"七言绝句","c":["希夷漫让麻衣术，禦寇元藏杜德机。","燕颔纷纷食肉相，龙门寂寂钓鱼矶。"]},{"t":"赠谢应午","f":"五言古诗","c":["志士抗高节，末俗寡所谐。","出门各有务，畴能喻中怀。","契合将焉托，眷此庭中槐。","孰谓尔无心，达性乃弗乖。","荣谢委时义，强干屹不摧。","吾志苟如此，何必求形骸。"]},{"t":"赠马大承道超贡上礼部","f":"七言古诗","c":["金膏水碧不易得，马生才华倾众人。","昂藏场屋每脱略，一跃便致青云身。","圣朝礼乐复元古，隋唐科目安足数。","玉阶独对天人篇，举头思与夔龙伍。","乡国从来盛俊英，蹇予乖剌老无成。","拂君宝剑出门去，早取千秋万古名。"]},{"t":"赠恽司勋器之","f":"五言古诗","c":["干将无留割，奇骥刷千里。","磊落恽司勋，天才豁所委。","研精综天人，识微洞玄理。","排荡五行家，力破管郭垒。","领郡懋循良，司农广储峙。","策功龙飞乡，天子知姓氏。","三命登吏曹，士类鉴如水。","古称裴叔则，朗照宛相拟。","奏绩明光宫，履声彻阶戺。","留之置左右，启沃自兹始。"]},{"t":"云厓","f":"楚辞体","c":["匡庐苍苍五老峰，彭湖倒蘸青芙蓉。","峰头云气日五色，散落厓谷生春容。","子晋吹笙紫宫里，拄笏看云时隐几。","云兮云兮心共閒，不逐秋风渡江水。"]},{"t":"赠黄仲实太常","f":"五言古诗","c":["嘉遁息岩壑，朋游寡谐亲。","匪兹慕狷独，动静理自因。","同人念蓬宇，惠然远来臻。","契阔既以展，觞豆亦间陈。","冲襟共披豁，时卉况鲜新。","神圣恢皇纲，朝有明哲臣。","流惠及畎亩，粒食终垂纶。"]},{"t":"赠马督府","f":"五言古诗","c":["将军美白皙，朗然玉山行。","胸填六韬书，胆气森纵横。","往年镇幽朔，军令肃且明。","弯弧插白羽，破的矜骁腾。","设伏杀强虏，开边广屯营。","犬羊悉败北，咋指逃榛荆。","太行竟为险，巀嶪亘长城。","千秋屏翰地，再见李乐生。","时平纳虎竹，袖手居留京。","读书不出户，缓带含馀情。","调笑射杨叶，猿猱屡号惊。","云间鹙鸧羽，往往落虚抨。","把酒登凤台，北望烟云平。","醉拔龙剑舞，绣涩鬼血青。","颇闻燕赵士，踊跃思雄名。","朅来拜新诏，起握南府兵。","骅骝试按辔，无乃枉其能。","近者居延塞，烽火剧流星。","天子日侧席，筹策劳公卿。","君今谒丹陛，嵩呼致忠诚。","何不请长组，奋臂抗先旌。","蛇矛耀白雪，直捣单于庭。","丈夫贵许国，退逊非豪英。","子仪伏回纥，充国制先零。","岂必待擐甲，折冲由先声。","畸人卧山谷，十载怀相倾。","簪盍虽云乐，所希王国宁。"]},{"t":"于淮水东赠徽守王行之二首 其一","f":"五言律诗","c":["王尊元直道，顾凯一狂生。","邂逅风波地，相看义气倾。","云消山自得，秋近水偏清。","握手旗亭暮，那堪去住情。"]},{"t":"于淮水东赠徽守王行之二首 其二","f":"五言律诗","c":["新安江见底，击楫兴如何。","日转双旌影，风传五裤歌。","名高翻借郡，道古拙催科。","此地贤人众，毋辞握发多。"]},{"t":"柬金许二生下第归卧病","f":"七言律诗","c":["二仲来疏榻满尘，青青林竹映阶新。","还家颇恨垂高翼，闭户应怜养谷神。","长路风云难适意，故山薇蕨有馀春。","闻君已断窥园路，更注春秋绍获麟。"]},{"t":"和罗女文悼妾二首 其一","f":"七言律诗","c":["斗帐红罗杂组裯，阳台云散梦无由。","灵飞月殿仙为侣，鬼落星宫命见仇。","金屋旧恩何处所，银河秋望此生休。","欲知清夜伤心地，画烛烧残独倚楼。"]},{"t":"和罗女文悼妾二首 其二","f":"七言律诗","c":["水榭花台失旧踪，新秋风雨罢芙蓉。","也知尤物终先坏，恨杀倾城不再逢。","堕泪难禁团扇赋，埋愁空起若堂封。","魂归莫向家乡去，楚水淮山一万重。"]},{"t":"送广宁伯还京","f":"七言律诗","c":["江上楼船画鹢飞，波摇采眊倍光辉。","功高大室山河誓，令肃行营虎豹威。","白露迎寒沾客旆，彤云开霁引朝衣。","独怜南府多宾从，离恨依依望转迷。"]},{"t":"赠蔡别驾","f":"七言律诗","c":["苏台对酒忽经年，淮水论文更别筵。","丽藻流传都下赋，甘棠歌颂召公贤。","宫袍晓湿钟陵雨，官舸秋回震泽烟。","台内借筹均二税，愿将周礼赞成宣。"]},{"t":"短歌赠罗女文二首 其一","f":"七言古诗","c":["钟山嵯峨入紫冥，百灵献秀开金庭。","大江奔腾龙虎跃，千峰散落南天青。","道人筑室天印下，丘壑重重到茅舍。","谢墅花骄罗绮春，秦淮舟泛星河夜。","人生强健早归来，日月持光送酒杯。","麟阁功名有时命，何须长恋黄金台。","桥东曳杖隐沦客，抱琴来寻莫相绝。"]},{"t":"短歌赠罗女文二首 其二","f":"楚辞体","c":["世路羊肠莽荆棘，江上渔舟独潇洒。","五湖何地非吾家，相逢并是同心者。","北风起兮雪片飞，山川摇落鸿雁饥。","地映吴天白如扫，唯见松柏青依依。","大鱼浪跄飞不得，小鱼僵死手可拾。","妻孥白饭尽一饱，岂向朱门乞残炙。","黄天荡深万鱼聚，我与老翁荡舟去。"]},{"t":"送杨督府还关中","f":"七言律诗","c":["林塘小隐帝城隅，时枉元戎问腐儒。","倾盖交情唯古道，填胸兵甲有阴符。","廉颇去国仍强健，萧相成名在转输。","归去灞陵秋猎晚，莫嗔醉尉夜喧呼。"]},{"t":"送彭年","f":"七言律诗","c":["画舸来自吴江水，皇州踏遍诸名山。","天门表里金银阙，陆海东西虎豹关。","横笛正逢秋月满，题诗浑乱锦苔斑。","柴门久待嵇康驾，愿尔栖迟且勿还。"]},{"t":"寄蔡九逵","f":"七言律诗","c":["缥缈峰高碧雾重，仙人楼阁隐玲珑。","新文出世诸生法，大道行天万古同。","未见江湖徵李泌，每劳卿相问王通。","休誇林屋烟霞胜，霖雨苍生望未穷。"]},{"t":"寄王履吉","f":"七言律诗","c":["石湖东畔草堂低，日日乘舟泛越溪。","鼎转丹砂驱鹤守，匣封雄剑恼鸡啼。","林中饷客蒸黄独，涧下褰裳弄紫霓。","爱尔棣华情不浅，诗成强半忆征西。"]},{"t":"送罗诚甫访新安王太守","f":"七言绝句","c":["黟江水澄清见底，黄山裳发煖薰人。","京华欲问新安政，十月闻君踏早春。"]},{"t":"沈懋学游金陵归杭 其一","f":"七言绝句","c":["王会车书一统尊，神京南北控乾坤。","长江险作雷霆斗，钟阜高为龙虎蹲。"]},{"t":"沈懋学游金陵归杭 其二","f":"七言绝句","c":["吴越千山断续青，西湖那似大江澄。","东来历历看形胜，独见彤云护紫庭。"]},{"t":"沈懋学游金陵归杭 其三","f":"七言绝句","c":["茱萸锦带系吴钩，半醉来登太白楼。","唤取美人歌白苧，任教明月下西洲。"]},{"t":"沈懋学游金陵归杭 其四","f":"七言绝句","c":["君到金陵秋气新，紫萸黄菊照江漘。","崔嵬一片龙山石，又见荆南落帽宾。"]},{"t":"沈懋学游金陵归杭 其五","f":"七言绝句","c":["青山一洗烟华色，徐庾空流怨曲长。","才子来观商邑盛，却歌殷武颂汤王。"]},{"t":"沈懋学游金陵归杭 其六","f":"七言绝句","c":["词锋撇捩鲍参军，画法侵淩郑广文。","长傍牛车歌白石，空传鹓侣满青云。"]},{"t":"赋陆如愚白溪上","f":"五言律诗","c":["倒注银河水，潜通石涧泉。","月寒铺素练，云净濯青天。","照影须眉见，澄心冰玉悬。","时看气五色，隐隐发龙渊。"]},{"t":"送王子新游溧川","f":"五言古诗","c":["王生龙凤姿，夙慕嵇阮踪。","举目局四海，何心顾樊笼。","词标文苑秀，书拟绝代工。","端居不出户，华誉溢金镛。","浩荡五岳怀，婚嫁犹未终。","问讯罨画溪，结想三茅峰。","采芝共谁飧，石髓或可逢。","顾予疲薾人，枯鱼困泥中。","望望紫烟驾，引领溯长风。"]},{"t":"送许彦明往松江二首 其一","f":"五言古诗","c":["结友不知心，履綦空累百。","与君山林交，心迹两无隔。","不见辄相思，相见终昕夕。","岁暮诚寡徒，缱绻荷三益。","今晨叩蓬户，车马有行色。","臣恣山水游，亦以衣食役。","畬田间三泖，霜落事秋穫。","言念四体勤，顾此十口迫。","浮生寡欢悰，玄发亦已白。","天寒早返驾，勿作久游客。"]},{"t":"送许彦明往松江二首 其二","f":"五言古诗","c":["东吴多胜友，远念因君劳。","累岁不一见，每惭平生交。","扁舟过苏台，览胜虎山桥。","笠泽控海口，登丘望云涛。","高词竞摛锦，古意相投胶。","水国早寒夜，雾尽霜月高。","清宴出美酒，鲈鱼解鸾刀。","窈窕子夜歌，依稀白云谣。","因之发幽兴，并令尘虑消。"]},{"t":"赠汪生然水","f":"五言律诗","c":["爱尔温如玉，丁年即善诗。","名从三辟重，身作五侯师。","醉月淹京国，观涛历海涯。","还家事幽讨，长下读书帷。"]},{"t":"题濯足图寿陈隐翁","f":"七言古诗","c":["尹山山下湖水浮，仙人高居湖上头。","岁取灌田供薄饭，时来濯足弄扁舟。","尘埃濯尽玉体清，手攀琼树踏云行。","子孙学文兼学稼，咫尺不入夫差城。","我心爱之恨莫从，茑萝空思附长松。","遥持海上千年酒，寄向湖东七十峰。"]},{"t":"赠雪舫君","f":"五言古诗","c":["北风天地肃，大雪何缤纷。","长江夹万山，千里同一云。","江水东北流，素光霭氤氲。","恍如黄天荡，历乱鸥鹭群。","又如海门口，白蜺驾龙君。","道人发高兴，放舟龙江濆。","燕矶风飘飘，石帆浪沄沄。","中流自鼓楫，前浦金焦分。","手持一斗酒，坐玩波涛文。","浩歌黄竹篇，十斗乃微醺。","登舻指东海，蓬阆穷无垠。","誓把安期袖，看曳飞琼裙。","回风却返棹，未得通殷勤。","下顾浊世士，尘网徒纠棼。","归来雪微止，西山带残曛。","却笑剡溪上，杯水安足云。"]},{"t":"赠朱子价","f":"七言律诗","c":["入洛新传小陆才，通家能为李膺来。","清风坐发幽兰咏，远兴春流曲水杯。","旧树阅人经两世，啼莺向客啭千回。","翩翩彩凤云中翼，徙倚高梧病眼开。"]},{"t":"送王九之入京","f":"七言绝句","c":["澄江馆前江水流，征帆五月下扬州。","玉京台省多知己，会听常何荐马周。"]},{"t":"赠苏州教授钱宏甫二首 其一","f":"七言绝句","c":["传道青鞋入旧京，乱山何处觅经行。","因君却梦西湖色，一夜垂杨满目生。"]},{"t":"赠苏州教授钱宏甫二首 其二","f":"七言绝句","c":["苏湖教法胡安定，汉代醇儒董仲舒。","组绣空文麾旧习，虚无高论大新书。"]},{"t":"书画上赠总宪王公","f":"七言绝句","c":["烟霞地隔青林远，日月天回紫殿深。","浮世行藏非二道，达人忧乐本同心。"]},{"t":"陈九皋将游五岳过余赠诗辄答四韵","f":"七言律诗","c":["白鹤东来毛羽奇，翩跹上国振光仪。","云随五岳仙人仗，锦烂三都才子辞。","过眼江山皆有色，悬壶日月漫无期。","嗟予老病蓬茅下，烟水逍遥剧梦思。"]},{"t":"与王佺","f":"七言绝句","c":["长安季主洞幽明，市肆谈玄折贾生。","抱病老人茆屋下，倚风欹枕听江声。"]},{"t":"和答同年朱君佐邦伯二首 其一","f":"五言律诗","c":["四方纲纪日，夫子耀龙光。","小试关民社，高才失庙廊。","风严松力劲，草盛豆苗荒。","耿耿循良传，千秋数赵张。"]},{"t":"和答同年朱君佐邦伯二首 其二","f":"五言律诗","c":["驰驱空病骨，偃仰负清朝。","独采山中药，期寻海上桥。","怀贤归水镜，忧国望星杓。","千里闻金奏，泠泠胜九韶。"]},{"t":"赠王光禄克明迁北寺","f":"五言古诗","c":["燕山控华夏，中天开紫京。","圣皇握宸极，万国朝繁星。","金陵旧丰镐，庶府罗公卿。","夫子光禄彦，雄才能发硎。","讨叛奋南楚，四海驰英名。","五等未儋爵，三命讵为荣。","密勿紫泥诏，宵旰侧席情。","简知由一德，而岂资割烹。","五味济其和，雍雍事调羹。","高爵日以峻，泰阶行且平。","山人伏岩谷，永愿歌德声。"]},{"t":"赠别张汝益还松江","f":"古风","c":["金陵菊黄酒如乳，吴船系在江亭树。","玉尊狼籍犹未收，浮云已暗君行处。","草堂索莫增离愁，羡君高义古人流。","缊袍不耻狐貉立，千金一诺怜交游。","爱而不可见，去亦何时来。","明来挟策朝天去，迟君一醉凤凰台。"]},{"t":"赠邬户部佩之入贺元正","f":"七言律诗","c":["魏阙元正会万方，镐京奉使羡仙郎。","旌旗过岱冲祥雪，冠佩朝天近御香。","龙护衮衣当五位，凤调苍律应三阳。","两都拟就张衡赋，并献丹墀荐寿觞。"]},{"t":"哀歌行吊周封君","f":"古风","c":["君不见太阿铮铮豺虎雠，铅刀绕指矜和柔。","又不见寒松苍苍澹无色，桃李荣华耀朝日。","芜阳封君不可起，前辈典刑今遂已。","片言乡党倚泰山，千金散义如流水。","蔡邕不愧有道碑，泾野倾心逸民史。","呜呼故老凋丧人则哀，高门赫赫空成灰。"]},{"t":"寄寿仲宪长与立","f":"七言律诗","c":["淮南小山真得地，洛下耆英最长年。","入竹琴尊明绣服，倚云兰桂布芝田。","门庭旧训乡人法，服食奇方海客传。","后圃种松今已长，称觞应傍老龙边。"]},{"t":"寄寿方佥宪时鸣","f":"七言律诗","c":["清朝早脱惠文冠，石浦云涛拂钓竿。","伯仲大名天下重，行藏全节古人难。","居山岁久松鳞老，闭户秋高桂树团。","青简丹砂皆长物，酒杯花蕊足交欢。"]},{"t":"和女文自寿二首 其一","f":"七言律诗","c":["天印峰头望太空，海天冥漠快高鸿。","烟霞窟宅将俦侣，玉雪襟怀见始终。","曳履那沾东郭雪，枕书长占北窗风。","虚无大药千年鼎，潦倒沧洲一钓翁。"]},{"t":"和女文自寿二首 其二","f":"七言律诗","c":["风尘无路上渔蓑，林壑逍遥乐事多。","花底笙歌传酒赋，水边台榭散行窝。","素心一任浮云变，华发其如大药何。","新买小山皆种桂，绿阴青子任婆娑。"]},{"t":"送谭子羽归真州","f":"五言古诗","c":["乡国富才英，谭生最清发。","众中挺眉宇，开云见华月。","腹笥书峥嵘，罄折口恒讷。","贤关三千士，让尔名突兀。","长江隔家林，定省暂归谒。","槐黄赴秋闱，一战建奇伐。","手持青瑶篇，腾踏献金阙。"]},{"t":"赠斌老","f":"七言绝句","c":["山僧无事睡方浓，夜半何人忽打钟。","背却松阴还露坐，月轮高照殿西峰。"]},{"t":"送徐禹量游溧阳","f":"七言绝句","c":["宝剑青骊照国门，飘飘豪气识王孙。","车前挂得椒浆去，濑渚先浇烈女坟。"]},{"t":"赠孙三","f":"七言律诗","c":["江左孙郎义士风，解披心胆结才雄。","耕田帝力果何有，避地隐沦将尔同。","淮水皛茫云雾外，草堂疏散竹林中。","更怜天印山头月，长照樽前酒不空。"]},{"t":"挽白岩太宰乔公","f":"五言古诗","c":["世业韦门盛，时名魏相优。","铨曹标宿望，留钥领诸侯。","庙议山难转，人才网尽收。","金天高太华，沧海纳群流。","国有蓍龟在，人传藻翰遒。","江山饶赏咏，剑履独行休。","再拟经纶起，俄成汗漫游。","丹青归大化，帷幄罢前筹。","殄瘁邦家恤，风猷史阁修。","旧交纷雨泣，异域眇云愁。","一奠犹无所，相知岂尽酬。","唯应晋川水，遥会海东陬。"]},{"t":"送刘生承恩归太原秋试","f":"古风","c":["麟角凤嘴见者奇，火齐木难光陆离。","太原刘生气殊众，年甫二十高名驰。","韦贤相业更三世，戴圣明经传博士。","白壁风仪不动尘，洪钟扣答如流水。","宝剑腰悬明月光，秋闱小捷何足当。","看拖内殿青丝履，笑踏君家白玉堂。","白玉堂，非难取。","胸中家学贯伊吕，千秋万岁奉明主。"]},{"t":"清旷亭酌酒同许隐君赠别臧子明进士春试","f":"七言律诗","c":["卧病空山孤草亭，玉人高驾扣岩扃。","开樽胜地临千嶂，挥麈清风倒六经。","三月杏园看走马，几年书阁照囊萤。","丈夫事业须强健，羡尔登朝两鬓青。"]},{"t":"和赵克用自寿","f":"七言律诗","c":["高人定性谢韦弦，可怪临书尚作颠。","白发交游多后辈，青山行乐有前缘。","忘机尽散谈棋社，好事仍抄种树篇。","尘海风波终日异，醉乡泉石自年年。"]},{"t":"寿华母","f":"七言律诗","c":["莱妇仍闻住帝城，班姑何必教宫庭。","家规累世传为训，子姓成行颔不名。","舞鹤自能翻寿曲，萱花元解散忧情。","琼筵绣轴寻常事，总让高门孝友声。"]},{"t":"寿徐禹量母","f":"七言律诗","c":["绮阁斑衣呈寿酒，玉山丹实走仙桃。","传诗令子人伦重，开国元功地望高。","河鼓双星争送巧，秋千百索递分曹。","相誇綵线清灯下，閒绣宫云满素袍。"]},{"t":"赠仲庵邬封君","f":"五言古诗","c":["俗士各有营，高人澹无欲。","缔搆青霞居，吟讽紫芝曲。","境空遗安排，形忘破羁束。","庄生赋逍遥，老氏捐殆辱。","杖屦金焦峰，梦寐江树绿。","有子奉滫瀡，无烦问瓶粟。"]},{"t":"赠顾生斯道","f":"五言古诗","c":["昆崙鲜顽璞，丹穴无凡禽。","吾宗著东吴，挺拔皆秀森。","羡尔甫弱冠，器宇遂澄深。","神驹未展足，龙泉敛银镡。","耽玄托雅志，和众敞虚襟。","古称黄叔度，汪洋浩无浔。","若翁信不忝，克肖生宁馨。","朅来游建业，周览龙虎岑。","高歌临长江，泠泠有馀音。","顾我山中居，慰意良已深。","弹琴对秋月，款语脩竹林。","明朝动归楫，遥悬天末心。"]},{"t":"金元宾自吴赴山中商定王履吉遗藁临别有赠","f":"五言古诗","c":["王子不可作，遗编重南金。","珊瑚逸海底，铁网劳行寻。","元宾奋高义，搜罗逮幽沈。","玉札聚缃帙，虹光耀词林。","玄经不覆瓿，侯芭名至今。","完此连城宝，重尔传灯心。","四海莽寥阔，谁应嗣知音。"]},{"t":"送吴铣入楚","f":"七言律诗","c":["岳阳楼头江月辉，洞庭湖边燕雁飞。","秋深独客兴方远，天际孤帆风正微。","九日他山萸菊酒，百年空谷芰荷衣。","武昌沈约多诗兴，听赋蒹葭赠尔归。"]},{"t":"田舍闻柴京兆致仕","f":"七言律诗","c":["卧病空山秋草深，愁闻京兆谢朝簪。","吾民薄分去慈母，野老独吟伤寸心。","茂树清流从所好，朱弦瑶瑟有遗音。","扁舟东下三江水，极目浮云白日阴。"]},{"t":"和严太宰生日","f":"七言律诗","c":["丰镐几年淹吏省，虞廷多士望朝衣。","台衡地重公何晚，金玉文高世所稀。","共识皇情优且渥，莫疑吾道是邪非。","传闻稷契频推让，黄阁风清正启扉。"]},{"t":"赠陆司谏浚明游金陵还吴","f":"五言古诗","c":["陆子入金陵，飘飘若神仙。","足著远游履，高咏名都篇。","朝攀虎踞石，夕弄汤池泉。","穷搜六代迹，下拍灵运肩。","它人安得近，相携唯惠连。","眷余卧江海，杖策枉茅檐。","会面惊发改，吐心知性偏。","问渠解绶故，举眼睨青天。","呼酒不停饮，竟醉眠花前。","凌晨告别去，往就丹阳船。","浩荡震泽水，相望空云烟。"]},{"t":"山桥候送王道思","f":"五言律诗","c":["念与高人别，郊圻出饯遥。","阳乌先羽节，夏叶暗河桥。","凤起文堪羡，鹏抟势莫招。","愿敷邹鲁化，终赞圣明朝。"]},{"t":"寿杨山人","f":"七言律诗","c":["巾舄飘飘山泽臞，偶然游戏入皇都。","花前丝竹堪陶写，橘里棋枰绝叫呼。","旧说登仙多鹤骨，谁家生子尽龙驹。","汉廷丞相张苍老，羡尔能传大药垆。"]},{"t":"题印空卷赠楷僧","f":"七言律诗","c":["皎月天空那有影，寒潭风动始生鳞。","心从定后离尘劫，眼在无中见法身。","可信住山元是幻，也知荒殿不须新。","须弥亦合俱推倒，临济曹溪若个亲。"]},{"t":"赠施子仁入汴二首 其一","f":"七言绝句","c":["君上夷门瞰大河，绕城秋色起洪波。","梁王宾客知谁在，莫唱蓬池阮籍歌。"]},{"t":"赠施子仁入汴二首 其二","f":"七言绝句","c":["熊轓皂盖大梁游，回首金陵二十秋。","闻道西关子城下，雁鸿飞尽水空流。"]},{"t":"郊居寄陈九皋","f":"五言律诗","c":["高人栖道院，逸思满秋山。","鹤立天坛净，梧飞露井斑。","幽探行独影，丽句动群颜。","可信金陵胜，皇居紫翠环。"]},{"t":"陆浚明再游金陵","f":"七言律诗","c":["一片行旌去复来，名山千叠系高怀。","不辞淮水迎风棹，要纵秋台玩月杯。","李白绮裘人竞看，谢安歌扇客重开。","雄豪今古知谁识，玉笛胡床漫自哀。"]},{"t":"赠张济民","f":"五言古诗","c":["长桑饮上池，能见垣一方。","华陀得神授，为人涤肝肠。","岂不绝尘轨，终然称谲狂。","张生仲景后，起自秦越乡。","少年读素问，淹贯灵枢章。","执脉炳内照，先几决存亡。","声名彻四海，岂独传维扬。","访余空山曲，相留但壶觞。","形骸委大化，何心扣灾祥。","唯有好山癖，所愿足力强。","囊中有灵药，请授一匕尝。"]},{"t":"送陈九皋还山阴","f":"七言律诗","c":["秦望山人草木衣，能令岩壑动光辉。","远游吴楚诗名大，长揖公卿礼数稀。","摩诘风流兼善画，嵇康豪宕本忘机。","都门不久留君住，手把幽兰赋式微。"]},{"t":"赠别张矩还真州","f":"古风","c":["长江水如一匹练，与子隔江少相见。","春来对酒花满枝，冬去寒林积冰霰。","人生万事在少年，功名早奋三才前。","旧穿杨叶有妙手，此飞便合冲青天。","尔不见汉家文学称扬雄，晚诋词赋为雕虫。","它时得路展经济，后有韩范前夔龙。"]},{"t":"哀摄泉居士三首 其一","f":"五言律诗","c":["天意真难测，仁人竟不延。","长辞淮水月，何赖摄山泉。","尊满仍馀酒，囊空岂剩钱。","想应生灭际，已悟大乘禅。"]},{"t":"哀摄泉居士三首 其二","f":"五言律诗","c":["玄度先朝露，逢时辄损欢。","城春花月惨，江晚水云寒。","苦调悲邻笛，清风忆素冠。","山南多旧寺，那忍过长干。"]},{"t":"哀摄泉居士三首 其三","f":"五言律诗","c":["感激投胶契，酸凄属纩言。","白头馀积恨，黄壤誓酬恩。","往事成今古，交情接子孙。","独怜孤凤羽，能慰九泉魂。"]},{"t":"答蔡九逵新春旅怀见投一首","f":"七言律诗","c":["把耒空山学治生，雪寒人静始归城。","倏惊江槛新梅色，犹记春梁乳燕声。","过眼岁华添老鬓，闭门交态任浮情。","中郎好古翻多事，爨下仍听朽木鸣。"]},{"t":"寿张时琢","f":"五言古诗","c":["海翁醇儒冠，文艺乃馀事。","岿然英宪朝，海内勤仰企。","天人骑箕归，龙种发神骥。","伯仲忝周旋，晚交属其季。","诗名动岩壑，家鸡习书字。","穆穆孝友姿，五常白眉异。","庭阶衍芝兰，诸孙更妩媚。","西来乞我词，献寿为遥致。","既惊瑶环相，益叹箕裘世。","大德享未终，后嗣宜尔炽。","祝君寿千年，孙子据高位。","源源馀庆流，乃尽天报意。"]},{"t":"送杨晋卿赴桐乡","f":"七言律诗","c":["飘飘黄绶早临民，乡国高才每羡君。","官棹近连藩省水，县斋长对甑山云。","蛟龙遇物多濡泽，奇骥追风自出群。","世德循良应不忝，祇今台省重求勋。"]},{"t":"以铁冠寿徐子仁","f":"五言古诗","c":["干将鍊神剑，遗我铁一丸。","道逢洪厓公，为制头上冠。","形模半月偃，金波错微澜。","晶荧金天气，照耀素发寒。","赠子介眉寿，缀之瑶华簪。","偃蹇青林侧，魑魅焉可干。"]},{"t":"题丛篁白兔图赠乔太宰公","f":"七言绝句","c":["千岁灵毛雪点乾，九秋仙杵玉声寒。","为怀脩竹长洲苑，暂下天边明月团。"]},{"t":"咏幻住庵辛夷花寄袁尚之","f":"七言律诗","c":["野寺春风二月馀，辛夷著花红锦舒。","诗人梦把一采笔，佛海幻出秋芙蕖。","芳菲宛入右丞坞，馨香儗载灵均车。","明年欲棹酒船去，袁宏雅兴终何如。"]},{"t":"瓜","f":"七言绝句","c":["青门子母互勾连，五色如云亦可怜。","试问故侯提剑舞，何如高垄枕锄眠。"]},{"t":"题许经历词所藏杂画册","f":"古风","c":["画山贵生气，画水如欲流。","哲匠精思得神解，俗工乃向丹青求。","僧繇以来到马夏，一变精工入萧洒。","后来沿袭失本真，卷轴颠狂恣粗野。","许君天机深，爱画得玄理。","收摭满缃囊，笔力尽奇诡。","层岩叠嶂通杳冥，草木生态俱含情。","神游飘飘凌八极，紫芝宫阙芙蓉城。","由来妙艺贵赏识，如君精鉴不易得。","君不闻中郎不向柯亭宿，龙枝终然作枯竹。"]},{"t":"赋陈中丞家杂画五首 其一","f":"五言绝句","c":["骏马在异骨，权奇插面高。","人间那乏此，难遇九方皋。"]},{"t":"赋陈中丞家杂画五首 其二","f":"五言绝句","c":["牛可理百亩，书能知经纶。","耕罢究千古，阿衡果何人。"]},{"t":"赋陈中丞家杂画五首 其三","f":"五言绝句","c":["作诗惊百代，何辞苦雕裁。","方与元化冥，岂知轩车来。"]},{"t":"赋陈中丞家杂画五首 其四","f":"五言绝句","c":["山中千岁鹿，毛如白雪花。","御尔恣来往，稳于蒲轮车。"]},{"t":"赋陈中丞家杂画五首 其五","f":"七言绝句","c":["海上鳌峰万叠青，归来铁杖带龙腥。","黄尘世事如翻掌，都付仙公几梦醒。"]},{"t":"红梅素帐","f":"古风","c":["皎皎吴绫雪瑩，累累梅蕊红殷。","五夜瑶台素月，千群玉女朱颜。"]},{"t":"脩竹吟和邬户曹佩之十二首 其一","f":"七言绝句","c":["二月金陵桃李花，春风吹醉五侯家。","脩脩画省筼筜谷，玉气蒸云化碧霞。"]},{"t":"脩竹吟和邬户曹佩之十二首 其二","f":"七言绝句","c":["蓬水浮筠路何许，月明共接飞仙语。","云边青凤去无声，绕遍幽庭独愁伫。"]},{"t":"脩竹吟和邬户曹佩之十二首 其三","f":"七言绝句","c":["落花风雨逗馀寒，春恨诗成醉懒看。","晓起前庭新竹长，墨华书满翠琅玕。"]},{"t":"脩竹吟和邬户曹佩之十二首 其四","f":"七言绝句","c":["出墙初见雨梢齐，拂石还怜露叶低。","清影静摇明月苑，碧沙寒漾浣花溪。"]},{"t":"脩竹吟和邬户曹佩之十二首 其五","f":"七言绝句","c":["摊书独据乌皮几，洗砚时临墨池水。","日斜何处散幽情，散发行吟脩竹里。"]},{"t":"脩竹吟和邬户曹佩之十二首 其六","f":"七言绝句","c":["纤纤细竹映虚廊，紫笋穿苔自布行。","时有高人来啸咏，他山十丈漫为长。"]},{"t":"脩竹吟和邬户曹佩之十二首 其七","f":"七言绝句","c":["空堂三伏转清秋，满院重阴泻碧流。","竿溜素霜寒挺挺，叶含轻吹晚飕飕。"]},{"t":"脩竹吟和邬户曹佩之十二首 其八","f":"七言绝句","c":["荒云漠漠荆江浒，霜霰萧条残野䇢。","堪羡仙台尺五天，枝枝碧玉承春雨。"]},{"t":"脩竹吟和邬户曹佩之十二首 其九","f":"七言绝句","c":["籊籊淇园青竹竿，移栽华省映朱栏。","吟空鸾凤清风远，堕地龙蛇白昼寒。"]},{"t":"脩竹吟和邬户曹佩之十二首 其十","f":"七言绝句","c":["灵女双双下紫霄，踏歌江渚采兰苕。","凭将嶰谷伶伦管，送入钧天协凤韶。"]},{"t":"脩竹吟和邬户曹佩之十二首 其十一","f":"七言绝句","c":["竹君不及花奴色，可惜相知眼中少。","阮籍元非曲糵徒，王猷独擅人伦表。"]},{"t":"脩竹吟和邬户曹佩之十二首 其十二","f":"七言绝句","c":["小径中林宛转通，薇花秋晚堕疏红。","三三五五含香侣，耐可婆娑退自公。"]},{"t":"寄题文徵仲玉磬山房二首 其一","f":"七言律诗","c":["曲房平向广堂分，壁立端如礼器陈。","拊瑟便应来凤鸟，折腰那肯揖时人。","词华价并金声赋，寿酒欢生玉树春。","法象泗滨真不忝，画梁文藻翠光匀。"]},{"t":"寄题文徵仲玉磬山房二首 其二","f":"七言律诗","c":["小搆山房护竹垣，道人行坐自云宽。","湘帘散映图书乱，石枕横支梦寐安。","世禄后先三曳绶，诗怀今古一凭阑。","堪怜海月经檐白，正照前溪绿水寒。"]},{"t":"题宜男便面寄朱铭甫二首 其一","f":"七言绝句","c":["宜男照耀后庭春，笑杂兰芽插鬓唇。","良夜绣帷传吉梦，双双抱送玉麒麟。"]},{"t":"题宜男便面寄朱铭甫二首 其二","f":"七言绝句","c":["北堂灵草忘忧种，南省尚书积庆家。","欲颂螽斯歌子姓，试开纨扇数丛葩。"]},{"t":"丹泉歌赠顾生","f":"七言古诗","c":["葛翁炼药吴山巅，丹砂入井流丹泉。","洞门一闭绿苔灭，至今宝气横青天。","山人筑室幽涧东，飞泉洒壁秋霞红。","饮之不饥复不渴，碧眼渐换为方瞳。","买药金陵未归去，月明猿鹤空延伫。","束取阴符向白云，烧丹直傍泉飞处。"]},{"t":"宗伯严公御书楼三首 其一","f":"七言律诗","c":["宗伯楼成气概雄，赐书遥拜渥恩隆。","千年圣泽传金版，五夜文光贯玉虹。","稽古桓荣元好学，谈经刘向独输忠。","欣承明主崇儒日，一体君臣志业同。"]},{"t":"宗伯严公御书楼三首 其二","f":"七言律诗","c":["重楼高揭楚云低，中有图书护紫泥。","子姓传家开阀阅，山灵潜地守封题。","芸箱积架无残蠹，月案研朱有降藜。","恩宠自天光价重，邺侯遗事岂能齐。"]},{"t":"宗伯严公御书楼三首 其三","f":"七言律诗","c":["楼上新藏万卷馀，法筵元是旧陈书。","虞廷际会风云合，孔道光辉日月舒。","未许旁人誇宠数，自怜家世得菑畬。","遭逢却叹千年事，空使孙通起汉初。"]},{"t":"严子寅小阁","f":"五言律诗","c":["幽栖易为足，容膝岂愿馀。","日览陶谢篇，时临苏董书。","乐此永昕夕，自顾无斗储。","往往赋佳句，驰声满乡闾。"]},{"t":"周臣为余写水墨山水大障徐子仁特赏其妙口占谢之","f":"七言律诗","c":["峥嵘华岳三神峰，移置草堂云雾浓。","泉飞树挺气生动，羽人彷佛中林逢。","周生作此特神妙，髯仙见之欲狂叫。","眼中失却梅花翁，人间岂乏钟期老。"]},{"t":"刻丝梨花","f":"七言绝句","c":["素娥春舞翠绡衣，宴罢梁园月影微。","水底灵鲛何处见，却偷娇艳入仙机。"]},{"t":"牧牛图二首 其一","f":"五言律诗","c":["牛背泽且适，牛肩高嶙峋。","登之挽其角，欢如就文茵。","原草被雨绿，芳树夏叶新。","行歌重阴外，何羡輶轩尘。"]},{"t":"牧牛图二首 其二","f":"五言律诗","c":["牧儿三尺箠，乌犍唯所使。","吻渴不及泉，奔逸顾乃尔。","大德在顺情，民物同一理。","驭众有安危，毋谓悉由己。"]},{"t":"施子仁湖山画障歌","f":"七言古诗","c":["吴趋祇誇金阊丽，何如震泽东山美。","夏后旧导三江流，范蠡初逃五湖水。","波心罗列七十峰，蓬壶散插碧海中。","尘寰断绝烟岛远，灵桥上与银河通。","栖岩架壑多隐居，楼悬阁转傍青虚。","侯封共指千秋橘，饱饭仍兼万顷鱼。","此中遗逸盛才杰，乐志披心任交结。","春申宾客广文词，庆忌后人能射猎。","人生有缘生福地，有酒长对包山醉。","但持绿鬓傲林泉，何用青衫走城市。","不到山中三十年，忽开图画兴翻然。","春来裹茗摇烟艇，与尔先尝悟道泉。"]},{"t":"鹤泉歌为王伟纯赋","f":"古风","c":["白鹤夜啄飞霞峰，山头泉飞如玉龙。","泉鸣鹤唳天地肃，长风吼彻千岩松。","泉上高人毛骨灵，十年洗心笺六经。","文词出口戛金石，已却烟火辞膻腥。","当今圣人出，礼乐昭典刑，尔栖林泉胡自宁。","巍巍阿阁五云上，试展垂天彩凤翎。"]},{"t":"栋塘行赠李封君","f":"古风","c":["山翁种栋野塘上，岁久根株如邓林。","高标上拂星汉迥，长枝下盖千人阴。","气凌风雨力排荡，根盘厚地穷幽深。","甬水回波恣润泽，龙山飞翠连萧森。","玄蚁移封不敢近，游龙挂影时兴霖。","白鹤生子于其上，露下青天扬远音。","山翁依之结茆屋，百里亭亭望乔木。","手校诗书课子孙，身备人伦化乡曲。","万石何惭古朴风，太丘善变浇漓俗。","憩阴看山谁与语，投竿取鱼非所欲。","有子乘骢清四方，顾此讴吟意恒足。","君不闻陶令五柳垂清风，王氏植槐生上公。","李翁之栋兼二美，家声世泽何终穷。"]},{"t":"阳湖曲赠王礼部直夫十首 其一","f":"五言绝句","c":["阳湖在何许，乃在娄门西。","云水相澹泊，能令高士迷。"]},{"t":"阳湖曲赠王礼部直夫十首 其二","f":"五言绝句","c":["阳湖媚烟霏，不减欹湖道。","宛转子夜歌，赓酬有同好。"]},{"t":"阳湖曲赠王礼部直夫十首 其三","f":"五言绝句","c":["扁舟荡双桨，琴床兼砚几。","旖旎傍丹铅，笑杀鸱夷子。"]},{"t":"阳湖曲赠王礼部直夫十首 其四","f":"五言绝句","c":["鸂鶒对人浴，鵁鶄夹船飞。","物性各有适，幽怀澹忘机。"]},{"t":"阳湖曲赠王礼部直夫十首 其五","f":"五言绝句","c":["生事在湖水，与世了无陵。","浅渚拾紫芡，深潭挦碧菱。"]},{"t":"阳湖曲赠王礼部直夫十首 其六","f":"五言绝句","c":["阳湖信自好，五月荷花鲜。","移舟就杨柳，惊问游女船。"]},{"t":"阳湖曲赠王礼部直夫十首 其七","f":"五言绝句","c":["震泽浩无涯，三江风浪恶。","瀰瀰阳湖水，艇子随住著。"]},{"t":"阳湖曲赠王礼部直夫十首 其八","f":"五言绝句","c":["长洲不复苑，齐云那有楼。","阳湖清浅水，千载长悠悠。"]},{"t":"阳湖曲赠王礼部直夫十首 其九","f":"五言绝句","c":["舟居无往来，端坐披白帢。","閒钓季鹰鲈，戏牧龟蒙鸭。"]},{"t":"阳湖曲赠王礼部直夫十首 其十","f":"五言绝句","c":["明湖落天影，澹澍古城边。","春风艳阳月，满镜百花然。"]},{"t":"金陵八咏和湛宗伯 其一 牛首山","f":"七言绝句","c":["天开双阙定神京，罗立千峰拱卫成。","形胜金汤誇百二，紫烟长抱日华生。"]},{"t":"金陵八咏和湛宗伯 其二 观音岩","f":"七言绝句","c":["江横北郭水浮天，拔起灵岩紫翠悬。","夜向空冥歌海唱，鱼龙掀舞佛楼前。"]},{"t":"金陵八咏和湛宗伯 其三 灵谷寺","f":"七言绝句","c":["曾是前朝古佛坛，天皇留此侍金棺。","松杉十里苍云暗，陵寝千秋玉露团。"]},{"t":"金陵八咏和湛宗伯 其四 雨花台","f":"七言绝句","c":["古台开士说金经，传道天花落紫冥。","广舌不来尘海变，春风唯见草青青。"]},{"t":"金陵八咏和湛宗伯 其五 东山","f":"七言绝句","c":["相公游时花满蹊，尽道秦淮胜剡溪。","回首洛阳轻一掷，江南花月使人迷。"]},{"t":"金陵八咏和湛宗伯 其六 梅花水","f":"七言绝句","c":["泉生石底无泥滓，复映梅花清可怜。","山人濯缨明月下，一夜高咏蕊珠篇。"]},{"t":"金陵八咏和湛宗伯 其七 清凉寺","f":"七言绝句","c":["禅宫远嵌碧山幽，亭榭凌风居上头。","举酒天边赊月色，振衣林表拂江流。"]},{"t":"金陵八咏和湛宗伯 其八 鸡鸣山","f":"七言绝句","c":["金陵佳丽四方闻，鸡岭平窥锦绣文。","万井烟花缠碧树，九天楼阁护彤云。"]},{"t":"谢许司徒惠金露酒","f":"五言律诗","c":["莲城名酝美，走送荷情亲。","芳露承仙掌，清风近圣人。","药和宜老病，梅赏称先春。","野客惭空腹，陶然得醉醇。"]},{"t":"和陈鲁南遂初斋四首 其一","f":"五言律诗","c":["地萦淮水曲，门枕市桥头。","城郭烟花绕，山川紫翠浮。","开林通鹤径，架槛弄鱼钩。","兴洽蓬壶外，飘飘赋远游。"]},{"t":"和陈鲁南遂初斋四首 其二","f":"五言律诗","c":["涉世齐诸妄，冥心近四禅。","有言皆象外，无物远尊前。","古帖临池拓，春酲枕石眠。","悬车自吾志，何必问行年。"]},{"t":"和陈鲁南遂初斋四首 其三","f":"五言律诗","c":["旷志高云上，浮荣逝水东。","狂歌随楚老，力稼习豳风。","道盛宾长满，心清室屡空。","挥毫多妙墨，谁谓晚疏慵。"]},{"t":"和陈鲁南遂初斋四首 其四","f":"五言律诗","c":["洒落陶元亮，孤高管幼安。","葛巾逢酒漉，木榻借书看。","嘉树光风转，遥山积雪残。","苦吟近成癖，终日懒衣冠。"]},{"t":"以紫珉瓜杯寿女文侑之以诗","f":"五言古诗","c":["东陵五色瓜，精彩化云英。","堕地结紫玉，流光烛岩扃。","仙人夜采掇，剖之为巨觥。","神工谢雕琢，朴质疑生成。","泻以丹霞浆，日月炫晶荧。","长跪献翁寿，雄饮吞长鲸。","五内忻灌沃，上药资流行。","三载换绿髓，十年骨尽轻。","出入紫烟表，寿与天齐倾。"]},{"t":"谢顾新之惠绿萼梅","f":"七言绝句","c":["阆苑仙人萼绿华，天风吹送蔡经家。","烟纨夜透冰肌白，正映西墙素月斜。"]},{"t":"题徐翁仙老障子","f":"七言古诗","c":["长松并立摩高空，深山何日无清风。","倚树不语者谁子，眉发似是商山翁。","白石可饭泉可饮，下视浊世飞尘红。"]},{"t":"水仙","f":"七言绝句","c":["翠罗裙带玉搔头，渺渺湘波素月流。","莫遣紫箫吹断续，碧天寒露不胜愁。"]},{"t":"题画","f":"古风","c":["千峰流云送鸣雨，万壑长风战高树。","拥盖山人何处归，林深野寒日将暮。","日将暮，行路苦。","天地阴阳倏忽殊，山人慎勿轻出户。"]},{"t":"题徵仲云山","f":"五言绝句","c":["江声喧草阁，雨气湿枫林。","云外青螺影，匡庐几许深。"]},{"t":"以藤枕赠鲁南辱谢四韵次答","f":"七言律诗","c":["石床筠簟斗清芬，把赠应知薄绮纁。","虚质含风延爽气，碧丝萦雾动波文。","琅玕比德应无玷，玛瑙论材漫有文。","卧向北窗魂梦稳，海涛千里隔南云。"]},{"t":"梦中天子命咏玉觉后记","f":"七言律诗","c":["至宝终难璞里藏，琢磨今始见蟾肪。","连城共重千金价，陈器还增九庙光。","独秉圭璋勤对越，时摇佩璲动琳琅。","愿教圣主崇明德，大鼎神龟共久长。"]},{"t":"汪中丞乃子子睿秀才持西湖图索赋长句","f":"七言古诗","c":["同人昔汎西湖水，锦缆牵船镜光里。","云雾难穷夹岸山，楼台乱拥前朝寺。","吹箫夜登保叔楼，青林明月影倒浮。","远窥天竺西方景，近指蓬莱东海游。","当庭挥翰疾如雨，簿书不得妨歌舞。","风流苏白疑可招，意气雷陈暗相许。","鸾鹄分飞西复东，尊酒放歌难再同。","汪生提画忽示我，伫立感叹怀高风。","看生豪气吞四方，转眼便登冰玉堂。","承家节操岂相忝，东人歌颂长洋洋。","穷岩旧诗如可识，为掬湖波洗苔壁。"]},{"t":"题王凤梅小画","f":"七言绝句","c":["草阁柴扉映水开，云松不着市朝埃。","扁舟载得蒹葭兴，何必溪山雪后来。"]},{"t":"寄题张希孟都阃隐居四首 其一 石门精舍","f":"七言绝句","c":["石出江门蹲玉龙，白云横束括苍峰。","幽林坐啸无人见，祇听鸾音振万松。"]},{"t":"寄题张希孟都阃隐居四首 其二 水心别业","f":"七言绝句","c":["永嘉城北水心寺，寺下高人凿石居。","向老拈杯浑懒慢，满床抛散六韬书。"]},{"t":"寄题张希孟都阃隐居四首 其三 东溪","f":"七言绝句","c":["山夹回溪抱日流，荷花百里锦云浮。","人间掷却黄金印，长破苍烟弄钓舟。"]},{"t":"寄题张希孟都阃隐居四首 其四 逍遥亭","f":"七言绝句","c":["龙湫瀑水远闻声，鹤岭仙云变采呈。","瑶草满亭抽碧玉，道人趺坐学无生。"]},{"t":"丽卿宅观灯席上赋","f":"七言律诗","c":["美酒华灯乐此宵，词人高会庆清朝。","条风累日春初动，明月千门雪半消。","未许峭寒欺鹤氅，且传新曲度鸾箫。","江南旧胜依稀在，罗绮尘香十二桥。"]},{"t":"赋料丝灯","f":"七言律诗","c":["画架高悬宝炬红，文绡光透綵毬空。","云霞巧织天孙缕，水火潜输鬼国功。","珠箔玲珑宜映月，玉屏虚薄自含风。","殷勤万里提携意，消得词林赋咏工。"]},{"t":"简亭为殷奉常赋","f":"五言古诗","c":["山人苦多事，却走林中居。","孤亭结疏竹，一榻了无馀。","手抚陶公琴，口诵庄生书。","赤足不裹袜，直钩时钓鱼。","客来自倾壶，醉卧方蘧蘧。","毋劳问名氏，葛天之民与。"]},{"t":"寄题袁永之列岫楼","f":"五言古诗","c":["高楼隔金阊，乃瞰横塘水。","画栋切云浮，雕题翼风起。","旷望临大荒，川原敞千里。","洞庭七十峰，罗列窗户里。","矧兹灵岩近，松桧森可指。","美人楼中居，懒慢谢冠履。","轻举希灵仙，高卧儗豪士。","支颐对青苍，傲然薄城市。","林烟润琴丝，湖月漾书几。","举酒歌慨慷，神游荡无涘。","玄晖傥可作，讵羡郡斋美。"]},{"t":"薛吏部君采园四诗 其一 牡丹亭","f":"五言古诗","c":["朝下天老堂，夕归卧丘樊。","挥金买花种，长恨不满园。","牡丹花之王，千本岂厌繁。","火齐大盈尺，锦障罗成藩。","日张金谷宴，娙娥满前轩。","丹粉艳华色，含情各无言。","但觉麝兰薰，潜恼蜂蝶魂。","此时对美酒，春风散微暄。","高歌清平曲，竟坐空百尊。","谁能逐驹隙，束带游朱门。"]},{"t":"薛吏部君采园四诗 其二 瑩心亭","f":"五言古诗","c":["秋至金气肃，池水日澄停。","游氛夜消尽，彻底青天明。","道人心源寂，尘事了莫婴。","饭馀隐几坐，兴起缘池行。","鸥鸟飞相亲，鯈鱼乐无惊。","群动各自得，生理澹且平。","与尔两无取，谁复思濯缨。"]},{"t":"薛吏部君采园四诗 其三 大宁斋","f":"古风","c":["众人皆弃我，我始有一身。","百年握重宝，何事殉他人。","伊尹乐兼善，引世以自任。","阿衡虽达志，五就亦艰辛。","列禦忧五?，老聃西出秦。","放形无何有，混混泯疏亲。","松柏中栋梁，丹雘损其真。","朴?山中樗，庶以全吾神。"]},{"t":"薛吏部君采园四诗 其四 退乐园","f":"五言古诗","c":["薛子蚤登朝，吐辞惊众人。","蛾眉遭众妒，局蹐长不伸。","自从返初服，遂与渔樵邻。","心清故无累，迹远乃遗尘。","开园当近郭，树艺招阳春。","时卉循节改，亲交叙情亲。","列席藉芳草，漉酒脱絺巾。","醉来任聚散，岂复知主宾。","寄言谢当世，结束非吾真。"]},{"t":"于按察泉庄杂咏十四首 其一 左山","f":"五言绝句","c":["青苍万古色，日日落吾几。","吾已忘吾生，山乎尔谁氏。"]},{"t":"于按察泉庄杂咏十四首 其二 上泉","f":"五言绝句","c":["错落万顷田，潺湲百丈泉。","山人日秉耒，饱饭对山眠。"]},{"t":"于按察泉庄杂咏十四首 其三 清流关","f":"五言绝句","c":["颇笑古函谷，晓出鸡鸣客。","四海今一家，岩关石门坼。"]},{"t":"于按察泉庄杂咏十四首 其四 赤湖","f":"五言绝句","c":["古邑今为田，城闉复何有。","时见遗世人，长歌一回首。"]},{"t":"于按察泉庄杂咏十四首 其五 云屋","f":"五言绝句","c":["茅屋依青嶂，松枝拂户低。","鹤来休便住，留著白云栖。"]},{"t":"于按察泉庄杂咏十四首 其六 月池","f":"五言绝句","c":["清池如半璧，下浸青天月。","依稀玉兔边，侧露金银阙。"]},{"t":"于按察泉庄杂咏十四首 其七 院卉","f":"五言绝句","c":["园花满百种，种种足春光。","百年春尽醉，才得九千场。"]},{"t":"于按察泉庄杂咏十四首 其八 园蔬","f":"五言绝句","c":["盥口就晨飧，青菘间黄独。","还闻石家厨，啖乳荐豚肉。"]},{"t":"于按察泉庄杂咏十四首 其九 远嶂","f":"五言绝句","c":["窗中列远岫，傲杀谢玄晖。","地是烟霞窟，身仍薜荔衣。"]},{"t":"于按察泉庄杂咏十四首 其十 平峦","f":"五言绝句","c":["翠屏高千尺，行坐日相对。","宇内有红尘，尽在岩峦背。"]},{"t":"于按察泉庄杂咏十四首 其十一 鱼沼","f":"五言绝句","c":["众鱼聚浅水，谁谓鳞甲微。","中有赤色鲤，雨即随龙飞。"]},{"t":"于按察泉庄杂咏十四首 其十二 雁畴","f":"五言绝句","c":["昔飞远塞外，映月落虚弦。","今向仁人侧，随阳宿野田。"]},{"t":"于按察泉庄杂咏十四首 其十三 柳堤","f":"五言绝句","c":["手种春杨柳，盈盈绿满堤。","居人不自觉，过客竟须迷。"]},{"t":"于按察泉庄杂咏十四首 其十四 篁径","f":"五言绝句","c":["竹下有幽径，本为裘羊开。","清风满庭户，时闻抱琴来。"]},{"t":"对菊十首和鲁南 其一","f":"五言律诗","c":["群芳摇落候，生意独欣欣。","欲趁霜前赏，曾劳雨后分。","黄金开正色，紫麝散奇薰。","愿以兰为友，那知竹是君。"]},{"t":"对菊十首和鲁南 其二","f":"五言律诗","c":["幽丛多傍砌，净植故当轩。","叶抱孤根起，花分五色繁。","石湖方勒谱，栗里漫开园。","请看东篱下，成蹊岂待言。"]},{"t":"对菊十首和鲁南 其三","f":"五言律诗","c":["种来分小径，护处插疏篱。","郁郁凌霜叶，亭亭阁月枝。","气清浑绝俗，香远更忘私。","本爱金风爽，谁云独后时。"]},{"t":"对菊十首和鲁南 其四","f":"五言律诗","c":["漫尔称花品，天然谢俗妆。","金精应太白，土德正中黄。","雅韵宜丘壑，贞心傲雪霜。","颓龄如可制，永愿荐壶觞。"]},{"t":"对菊十首和鲁南 其五","f":"五言律诗","c":["丹桂香残后，名花见亦稀。","一枝零晓露，三径总芬菲。","饮水人多寿，餐英世已违。","唯馀黄染色，犹近内家衣。"]},{"t":"对菊十首和鲁南 其六","f":"五言律诗","c":["孤标霜莫祟，弱植露多恩。","为问重阳月，谁言芍药尊。","品奇千里致，根老隔年存。","千古知心地，萧萧五柳门。"]},{"t":"对菊十首和鲁南 其七","f":"五言律诗","c":["浊酒嗟何至，清吟幸可酬。","独怜盈把色，掇取一篱秋。","制枕功偏永，缄书意更幽。","骚人歌令德，兰蕙本同流。"]},{"t":"对菊十首和鲁南 其八","f":"五言律诗","c":["斗种矜多叶，临开爱独枝。","名高隐君行，情远逐臣词。","惨冽神逾王，摧残性岂移。","不随梅共落，玉笛任君吹。"]},{"t":"对菊十首和鲁南 其九","f":"五言律诗","c":["直干依孤竹，繁丛混众蒿。","幽香一散漫，秋意失萧骚。","落帽山人醉，移尊使者劳。","郊居日相对，随兴坐亭皋。"]},{"t":"对菊十首和鲁南 其十","f":"五言律诗","c":["黄菊真宜晚，霜寒色转鲜。","栽培元得地，服食拟登仙。","丹粉休论色，笙歌别有天。","杜陵憔悴客，相伴草堂前。"]},{"t":"赋陈鹤飞来山房","f":"七言绝句","c":["何年泰岳峰头石，飞落东溟海上沙。","云气抟成丈人影，霞标开出隐侯家。"]},{"t":"题徐禹量画上","f":"七言绝句","c":["山人学稼筑郊居，已与人间万事疏。","走狗飞鹰身手倦，独临残照看农书。"]},{"t":"雪","f":"七言律诗","c":["白雪吹花散草堂，晚檐争舞北风狂。","微阳力战重阴候，素影潜回午夜光。","高步即思行鹤氅，清酣无谢荐羔羊。","郊原万木皆摇落，独见中林古柏苍。"]},{"t":"雪和鲁南二首 其一","f":"五言律诗","c":["雪积寒城晓，人眠野屋深。","二仪元气合，万木早春临。","白掩群峰色，青含寸草心。","潭冰知彻底，犹有冻龙吟。"]},{"t":"雪和鲁南二首 其二","f":"五言律诗","c":["雪飘何所似，玉树落晴菲。","杂霰融还冻，因风集更飞。","糟床催猛注，书幌借馀辉。","灞上骑驴者，红炉肯漫依。"]},{"t":"绣毬花","f":"五言绝句","c":["不惜荆山玉，装成素锦毬。","春风解怜汝，抛掷与谁收。"]},{"t":"白芍药","f":"五言绝句","c":["绣幄千金种，朱门百宝阑。","一枝烟月影，偏耐道人看。"]},{"t":"和鲁南后腊月六日对雪三首 其一","f":"五言律诗","c":["岁暮风仍积，春临雪并来。","寒声偏恋竹，阳信早传梅。","点树疑花缀，迎风学絮回。","捲帘同客赏，还爱蚁浮杯。"]},{"t":"和鲁南后腊月六日对雪三首 其二","f":"五言律诗","c":["向老年增腊，多情雪媚人。","神京移白玉，绝调抗阳春。","润麦欢成泽，凝阶幸灭尘。","最怜丰稔瑞，先慰草莱臣。"]},{"t":"和鲁南后腊月六日对雪三首 其三","f":"五言律诗","c":["地远平能布，帘疏巧解寻。","云低围素野，松劲擢青林。","食尽乌难下，池融水渐深。","闭门僵卧客，何有畏寒心。"]},{"t":"夜雪","f":"五言律诗","c":["色换虚窗曙，寒侵陋室穷。","雁迷天一色，鸡唱夜方中。","客棹帆应重，薰笼火不空。","此时钟岳影，白昼宛疑同。"]},{"t":"题蕃王阅马图","f":"七言古诗","c":["辽西番儿好鞍马，一生射猎长城下。","权奇岳耸汗血沟，不惜千金斗高价。","蕃王虽老心未衰，沙场爱养蛟龙姿。","日中牵出自阅视，剪騣刷尾调奚师。","屏间美人誇眼力，能按马身知马德。","就中选出千里蹄，左右相看俱动色。","祇今朔漠净风尘，良马皆充上国珍。","番儿不敢向南牧，岁岁来称献马臣。"]},{"t":"竹泉诗为邵正甫作","f":"七言律诗","c":["南山青青脩竹园，下有泉水流其根。","云中有源深且远，涧底无泥清不浑。","月明似见鸾凤浴，风过忽听笙竽喧。","道人睡起自洗耳，散发石上开清尊。"]},{"t":"木兰花慢 答介溪礼书二首 其一","f":"古风","c":["望紫云宫阙，曾出入、更行游。","向凤阁挥毫，龙墀曳履，籍甚清幽。","千载明良庆会，天地德独抱寸心酬。","鲁史专行笔削，虞廷迭和歌讴。","华旃日侍岂番休。","殿东头。","朱扉黄阁，班行回回，岁月悠悠。","遥想而今乐事，西苑畔碧树正清秋。","玉醴长沾凤斝，绣袍紧趁龙辀。"]},{"t":"木兰花慢 答介溪礼书二首 其二","f":"古风","c":["慨山人老矣，逃涧谷、息朋游。","尽细竹成园，寒松夹坞，自占岩幽。","天与清风皓月，从受用不费一钱酬。","管领匡床石枕，安排野调村讴。","馀生莫更赋行休。","眼前头。","清閒滋味，无何境界，尽已悠悠。","莫笑先生太赸，些个物相伴度春秋。","浊酒新烹郭索，閒窗静听钩辀。"]},{"t":"点绛唇 元日阴","f":"古风","c":["残雪明阶，扑帘微雨东风峭。","狐裘貂帽。","可信春曾到。","令节神京，合遣阳光照。","天公拗。","煖颠寒倒。","一任梅花恼。"]},{"t":"意难忘 鹭洲宅赏灯","f":"古风","c":["光烂红灯。","正珠帘尽下，玉斝高擎。","银屏烘夜影，火树迸春星。","人散诞、岁丰登。","对伟丽神京。","雪尚凝、微风料峭，澹月疏明。","那堪主客多情。","任铜壶漏水，报过三更。","传香添鸭鼎，选曲度鸾笙。","连夜醉、不须醒。","更告与良朋。","尽元宵、都无十日，莫拣阴晴。"]},{"t":"玉连环 和石亭赏灯","f":"古风","c":["綵棚灯障千花簇。","影摇红烛。","更阑客醉且淹留，月影在、阑干曲。","满座锦衣花幞。","雅吟追逐。","不须檀板共金钗，如此乐、今生足。"]},{"t":"出蒲圻饮廖学士山庄留赠","f":"七言律诗","c":["云峰缭绕午桥庄，学士邀宾坐草堂。","细指江山论气槩，久瞻星斗焕文章。","青霞覆道干旄润，丹桂飘庭语笑香。","大石岩岩堪下拜，野人休讶米公狂。"]},{"t":"谢马户曹饮别桃花山下","f":"七言律诗","c":["旗亭嘉树露华清，征马投南恋别鸣。","十里壶觞劳晓饯，一川禾黍快秋成。","桃峰路接烟霄色，石道风飘鼓角声。","老卧东山空再起，了无分寸答苍生。"]},{"t":"通城山中赴岳阳","f":"五言律诗","c":["本作观风使，何辞度坂行。","干旄惟帝命，田野有民情。","石出泉争响，林幽树漫生。","那逢古召杜，罗列在连城。"]},{"t":"九日风雨同昆山张水部诚之饮岳阳行台","f":"七言律诗","c":["霜台对酌重阳酒，同在他乡似故乡。","万里江湖楼阁迥，百年家国鬓毛苍。","鸿飞岂为秋田下，菊绽从知旧径荒。","雾雨君山登未得，西风休为孟嘉狂。"]},{"t":"雨中旅怀用前韵","f":"七言律诗","c":["南天九月披重褐，可信寒生自水乡。","多病怕逢秋雨积，小晴欣见暮山苍。","云迷巴国行来远，江涨吴田别后荒。","自理行藏还自笑，接舆谁道是真狂。"]},{"t":"观湖二首 其一","f":"五言律诗","c":["来为荆楚使，爱览洞庭湖。","一水天高下，诸方地有无。","行舟随鸟尽，飞阁带云孤。","忧乐平生志，阴晴任尔殊。"]},{"t":"观湖二首 其二","f":"五言律诗","c":["七泽名何辨，三湘水既同。","影摇坤轴动，形凿楚疆空。","浩荡吞南徼，平成赖禹功。","中流操楫者，破浪慎长风。"]},{"t":"观洞庭张水军","f":"七言古诗","c":["楚南洞庭天下险，寇盗不与潢池同。","干城颇设诸将在，格斗正赖三军雄。","秋高日晴水如掌，传令千艘出湖上。","画鹢分张羽士林，青龙独拥中军帐。","旌旗照水云锦明，鱼龙下伏不敢惊。","三步五步一齐止，左哨右哨连行营。","健儿使船如使马，变化风霆殊整暇。","须臾一舸远飞回，戏缚生俘献麾下。","船头将军红绣袍，横弩坐射波间鳌。","两行金鼓震水府，万夫大喝江云高。","吴王馀皇诚可嗟，黄盖艨艟未足誇。","若将远较昆明水，定数威雄胜汉家。"]},{"t":"自大荆驿往平江","f":"五言古诗","c":["霜重林木疏，日出山雾豁。","襜帷发荒馆，鸣鸡乱相聒。","岂不惮险艰，我职在咨度。","穷岩蔽白日，幽隐难自达。","吏鲜拔薤能，单羸困豪夺。","赤子堕眢井，陫痛焉可遏。","拔剑淬清水，为尔试一割。"]},{"t":"平江江边马上作","f":"七言绝句","c":["信马微吟野水边，水光人意静相怜。","祗今吹角归城府，何似持竿入钓船。"]},{"t":"翠华岭","f":"五言律诗","c":["叠岭各殊状，翠华云霭霏。","深溪鱼下见，半壁鸟平飞。","磴路客行少，野人生事微。","林峦虽满眼，佳处亦逢稀。"]},{"t":"晓发有感","f":"七言绝句","c":["荒林昨夜试新霜，晓起桑榆一半黄。","行子不知身是客，白头犹自别家乡。"]},{"t":"浏阳山中","f":"七言律诗","c":["老来重作宦游身，车马空岩起路尘。","日出寒云犹恋岫，地偏幽鸟不疑人。","行藏已被青山笑，税敛空悲白屋贫。","安得简书无一事，壤歌相伴葛天民。"]},{"t":"山行有感","f":"七言绝句","c":["草径缘山百折回，霜台旌旆几人来。","可怜万丈幽岩外，白日无光冻馁哀。"]},{"t":"漫兴","f":"七言律诗","c":["劳生浮世已苍颜，习静空门又出关。","身被朱衣惭再命，手持黄纸历千山。","林庐乞火征徒饭，寺阁鸣钟宿鸟还。","莫怕尘缨无处濯，半厓悬涧碧潺潺。"]},{"t":"喜山中幽槩","f":"七言律诗","c":["楚山秋色满熊轓，涉涧攀岩不弹烦。","菊放那逢元亮酒，竹深空爱辟疆园。","村墟尽理桑麻地，老稚稀闻市井言。","鸡犬数声云雾里，祗应风景是桃园。"]},{"t":"解嘲","f":"七言律诗","c":["三千道路内台臣，六十光阴旧逸民。","烟雾窟中行画障，简书丛里布阳春。","身将许国那堪老，性惯耕田岂厌贫。","寄向钟山猿鹤道，暂时相远莫相嗔。"]},{"t":"再过蕉溪岭往长沙","f":"七言律诗","c":["云梯石磴细盘旋，人蚁成行上九天。","霜叶点林时五色，岩泉飞涧只孤悬。","风烟百粤虚无里，舟楫三湘指顾前。","追忆旧游惊鬓雪，独馀狂兴似当年。"]},{"t":"野饭","f":"五言律诗","c":["轻车度岭歇，野饭趁墟烟。","半席小茅舍，一杯幽涧泉。","民情怀使节，露积喜丰年。","宝剑冰三尺，豺狼尔莫前。"]},{"t":"入长沙","f":"七言律诗","c":["岩城鼓角拥储胥，郡将横戈导隼旟。","汉国提封存万户，楚骚哀怨起三闾。","清朝礼乐无荒远，内史巡行自古初。","衡岳动摇应愧尔，召南歌咏正愁予。"]},{"t":"重到岳麓书院","f":"七言绝句","c":["不到书堂二十年，浮湘迁客已华颠。","惟应岳麓山前树，曾记哦诗曲水边。"]},{"t":"贾太传宅","f":"五言古诗","c":["汉文亦令主，胡乃弃贤人。","本志苟非合，多言徒累身。","贾生八九策，绛灌固宜嗔。","长沙一谪宦，旧宅遗千春。","清泠井泉水，孰谓非公神。"]},{"t":"长沙陶公祠","f":"古风","c":["典午厄阳九，强臣犯京阙。","匪慑勤王师，社稷几沦没。","桓桓长沙公，上游秉旄钺。","志虽屈扫除，功已安?杌。","旧邦仰遗灵，明祀耿无歇。"]},{"t":"岳麓书院","f":"五言古诗","c":["大道隐浮华，稽疑在明哲。","心交限千里，命驾勇所决。","幽讨向空山，三月语未辍。","微言世非远，横议今复烈。","愿因江汉流，一濯永清澈。"]},{"t":"熊湘阁","f":"五言古诗","c":["天运将移易，孤城安自全。","家辱等身辱，十口同时捐。","义士舞白刃，烈火扬朱烟。","伤哉熊湘阁，浩气横云天。","江山今中土，四望风凄然。"]},{"t":"独燎","f":"五言律诗","c":["冬巡仍野宿，独燎向更深。","报国将何事，临民负此心。","风灯摇短晕，霜角袅哀音。","百感方无那，猿啼况近林。"]},{"t":"荷塘馆晓发","f":"七言律诗","c":["戍鼓沈沈漏短长，百年浮迹此荷塘。","三更早报荒鸡月，独树寒翻野鹊霜。","人影候门排节钺，邮程呼烛倒衣裳。","此时天上朱门客，高卧方添燕寝香。"]},{"t":"杂兴六言六首 其一","f":"古风","c":["碧水澄溪日瑩，黄茅覆陇霜乾。","鸟下平原片雪，人登峻岭千盘。"]},{"t":"杂兴六言六首 其二","f":"古风","c":["古寺厓悬叠阁，危桥涧架孤亭。","泉水归池始静，墟烟过树犹凝。"]},{"t":"杂兴六言六首 其三","f":"古风","c":["路绝每稽厨传，山深罕识行旌。","人过荒村犬闹，笳嘶远岫云惊。"]},{"t":"杂兴六言六首 其四","f":"古风","c":["轩冕煌煌独贵，干旄孑孑谁贤。","正恐五浆先馈，空令一榻长悬。"]},{"t":"杂兴六言六首 其五","f":"古风","c":["境向静馀生动，身从冗地求清。","嘉树阴边听讼，流泉声里传更。"]},{"t":"杂兴六言六首 其六","f":"古风","c":["光阴逝者皆客，行藏寄也非吾。","野宿身仍畎亩，乡心梦失江湖。"]},{"t":"怀学稼郊居","f":"五言古诗","c":["中岁抱微痾，乞骸归林下。","衣食寡所营，因之学耕稼。","披蓑唾老手，鞭牛自芸耙。","四体虽力勤，丰稔荷天借。","壅瓜复畦芋，妻孥获存藉。","岂云偕隐沦，聊取禦冬夏。","今春应诏起，楚台策高驾。","法家贵深严，迂疏非流亚。","黔黎苟无补，安用积罪骂。","次且答皇情，归与旧茆舍。"]},{"t":"怀松坞草堂","f":"五言古诗","c":["先公埋玉山，种松千万株。","直干老龙立，清阴高盖敷。","逶迤石冈南，秀色缠灵区。","肯堂仅数楹，养痾遂閒居。","著书托游息，种黍给朝哺。","虽乏鸡豚产，颇辨杞菊厨。","嘉宾或至止，雅歌每倾壶。","柴门锁秋雨，菊径将无芜。"]},{"t":"怀屏山小隐","f":"五言古诗","c":["爱山久城癖，筑室依山阿。","指山作屏障，日玩青嵯峨。","春夏云霞色，秋冬霜雪柯。","荣悴虽殊观，我心矢靡它。","荣名果何物，委身任风波。","缨冕困微官，无乃损天和。","请辨主宾分，所得谁为多。"]},{"t":"怀息园","f":"五言古诗","c":["我非仲长统，乐志开家园。","邻人助幽胜，陂池广无藩。","鱼鸟以类聚，花木逐年繁。","种梅亦结子，种竹亦生孙。","居家每涉趣，近市复辞喧。","煌煌都城侧，寂尔成丘樊。","丘樊不自爱，乃从兼善言。","兼善本大义，无施成素餐。","孟轲去已久，此义当谁论。"]},{"t":"六忆 其一 罗印冈","f":"五言古诗","c":["忆昔观光初，群龙起乡国。","骏马联华镳，出入动生色。","升沈四十年，风波转倾仄。","存者仅三人，华发亦衰逼。","刘公去吴兴，独幸奉君侧。","芝兰晚逾馨，金玉久无忒。","枵然野人腹，恒饱君子德。","为别甫踰时，言念靡终食。","惠书竟长纸，在远心益恻。","谅哉岁寒交，终古不多得。"]},{"t":"六忆 其二 陈石亭","f":"五言古诗","c":["流观文章苑，君才如锦机。","触手生万象，五采腾清辉。","神情既效能，理性亦洞微。","蜚声天壤内，调绝和益希。","蹇余朴拙资，磨琢夙有依。","瓦缶附黄钟，巨细本相违。","欣欣里中儿，谬许谐音徽。","韩孟岂其伍，皮陆是邪非。","所幸山水际，时从萝薜衣。","赋咏尽花竹，游衍遍岩扉。","临衰忽分散，梦想恒渔矶。","微念早相遂，白首终同归。"]},{"t":"六忆 其三 赵雪岩","f":"五言古诗","c":["年殊交匪僭，道合意自谐。","吾慕淮阳公，抗俗敞高怀。","山岳凝莫动，江海荡无涯。","不言与不笑，一静众妙该。","冲夷自为宝，任取世嫌猜。","乡闾称长者，翕尔归于䰄。","蹇劣愧非偶，狂斐得所裁。","温温琼瑶泽，时获沾尊罍。","不见倏三月，鄙吝萌旧荄。","安得一披对，青天云雾开。","可念不可即，展转令心哀。"]},{"t":"六忆 其四 邵前川","f":"五言古诗","c":["邵公神仙人，中散或可偶。","攀龙翔九霄，误落风云后。","浊世糠秕目，何足识琼玖。","拂衣早归来，万事付杯酒。","时过竹林园，兄弟共宾友。","顾典千金裘，多多备瓶甊。","激烈梁甫吟，烂醉时在口。","好携两玉童，清歌击秦缶。","长使蛙黾肠，慷慨容十斗。","别来念此乐，几欲弃官走。","赋诗遥寄之，请君试翘首。","人生有真怀，捐佩当不久。"]},{"t":"六忆 其五 赵鹭洲","f":"五言古诗","c":["鹭洲情坦夷，与物澹无竞。","两世早弃官，金绯一门映。","萧然就耕稼，素业乐清净。","生男真圣童，诗书发天性。","我生寡徒侣，爱君岂面敬。","弱女虽非才，丝萝托嘉庆。","匪祗终交期，实欲通子姓。","形骸无尔汝，岁月有衰盛。","愿言慎眠食，永以娱寿命。"]},{"t":"六忆 其六 徐九峰","f":"五言古诗","c":["篆法久衰绝，中兴有徐翁。","铁笔渍膏泽，屹尔缠蛟龙。","李斯作者圣，后世安与同。","得意且遗象，举世乃归工。","商鼎款识古，孔碑额画丰。","迩来出新制，彷佛传遗风。","惜哉翁已老，无金铸其躬。","洞庭水之大，衡岳山之崇。","安得置其间，大书刻穹窿。","东望乏鹏翼，浩歌意何穷。"]},{"t":"寄内","f":"五言古诗","c":["与子为夫妇，侵及五十春。","糟糠逮鼎食，同事白发亲。","儿女俨成行，孙枝复侁侁。","顾瞻亲交内，偕老几何人。","世短恩义长，千金当一晨。","如何衰暮年，离别各艰辛。","钟鼎难自期，金石非我身。","念之不自慰，将思解朝绅。"]},{"t":"寄诸儿","f":"五言古诗","c":["居常理家教，怪尔远诗书。","对面起嗔恚，恩情乖本初。","朅来远离别，音耗閒居诸。","岂无公家饭，念尔靡来胥。","童孙及稚子，渐已分龙猪。","苟能应门户，岂必乘轩车。","天意难预识，多忧徒自拘。","采衣但在目，至乐固无馀。"]},{"t":"寄诸弟","f":"五言古诗","c":["我顾本著姓，家运递衰荣。","逮我封君行，隐德益休明。","爰及昆季列，英英萃瑶璚。","孝友笃同气，文藻各驰声。","林竹交晚翠，池草竞春生。","今兹大江右，隐起王谢名。","我衰复干禄，尔乐俱躬耕。","愿申止足义，终谐孔怀情。"]},{"t":"至日雨坐","f":"七言律诗","c":["冬至野城逢冱阴，万山云隔雨声深。","吹葭谷底寒灰湿，校线宫中昼景沈。","阳道愿随君子长，岁华愁向老人侵。","閒情恐被苍生误，万里烟波滞客心。"]},{"t":"问讯全公","f":"五言古诗","c":["禅有大知识，圆明乃其奥。","累劫脩性灵，凡士讵易造。","早脱梦幻尘，期觅安乐道。","南山逢全公，澹泊颇同好。","招邀无碍子，结社恣高蹈。","作佛无妄想，习静有真操。","空岩小茆斋，旬月常一到。","逍遥数年馀，已觉平竞躁。","朅来秉台麾，静念每潜悼。","行藏有机宜，勿谓吾已耄。"]},{"t":"独坐","f":"五言律诗","c":["家远三千道，年衰六十秋。","残躯馀畎亩，荣望岂公侯。","古昔观风政，迂疏学道谋。","倘输分寸力，归去老狐丘。"]},{"t":"岁晏","f":"七言律诗","c":["宋玉长嗟秋气悲，天寒岁晏益凄其。","浮云一望江湖远，短日微明草木衰。","实少阳春祛雪霰，虚令羸老拜旌麾。","埋轮揽辔俱前哲，转愧迂疏负盛时。"]},{"t":"茶陵山行值雨","f":"五言律诗","c":["山行殊跋涉，急雨况纷纷。","涧水横侵道，墟烟重积云。","马羸鞭不起，鸡远听微分。","数问邮亭憩，应怜仆从勤。"]},{"t":"雨中观云阳秀色","f":"七言古诗","c":["灵峰出云昼濛濛，秀色不与他山同。","望之紫翠拂天起，宛转数叠青屏风。","单车飘飘转山麓，寒水盈盈带冰绿。","冠缨相傍尘自清，十里搴帷意难足。","灵药定隐韩伯康，白石或放初平羊。","待余捐佩游五岳，此地愿借开丹房。"]},{"t":"赋云阳绝句拟作灵光亭","f":"七言绝句","c":["玉琢云阳练折溪，虚无灵气隐虹霓。","山川未许含光燄，化出天宫太乙藜。"]},{"t":"车中杂言十首 其一","f":"五言绝句","c":["前鱼弃龙阳，馀桃罪子瑕。","请看恩易尽，毋矜色胜花。"]},{"t":"车中杂言十首 其二","f":"五言绝句","c":["虎背危可骑，龙鳞逆堪折。","宛转母子间，亦掉茅焦舌。"]},{"t":"车中杂言十首 其三","f":"五言绝句","c":["西域开何益，雄哉汉武才。","殷勤谕父老，书生非本怀。"]},{"t":"车中杂言十首 其四","f":"五言绝句","c":["耕莘起三聘，钓渭载后车。","遇合非汤文，终然老农渔。"]},{"t":"车中杂言十首 其五","f":"五言绝句","c":["本无戒饮意，累月断开壶。","怪得阮嗣宗，祗念黄公垆。"]},{"t":"车中杂言十首 其六","f":"五言绝句","c":["山鸟啄山果，飞鸣高下丛。","适性乃真乐，岂羡黄金笼。"]},{"t":"车中杂言十首 其七","f":"五言绝句","c":["事向动中至，思从静馀生。","昼夜每递代，内境何由清。"]},{"t":"车中杂言十首 其八","f":"五言绝句","c":["一日脩一事，王官森如林。","逝矣运甓子，谁哉念分阴。"]},{"t":"车中杂言十首 其九","f":"五言绝句","c":["穷岩数椽屋，名姓系王民。","穷年办租税，不见官府仁。"]},{"t":"车中杂言十首 其十","f":"五言绝句","c":["襜帷稳于榻，行炉火微温。","不知外寒暖，侧听舆人言。"]},{"t":"新晴","f":"五言律诗","c":["积雨寒生冻，新晴令借春。","日穿深树白，雪点远峰新。","马足偏宜道，狐裘不恋人。","崔巍衡岳上，堪礼祝融神。"]},{"t":"自叹","f":"五言律诗","c":["自叹百年客，离尘复入尘。","关山南徼路，风雨独行身。","向物情俱淡，还家梦已频。","须知千白璧，难买一阳春。"]},{"t":"安仁晓发","f":"七言律诗","c":["扬旌伐鼓晓匆匆，三五明星碧汉东。","寒日映霜浮白雾，长林穿谷起鸣风。","舟车路绕天涯遍，簿领期催岁序终。","苦竭衰羸元不惜，祗愁民社竟无功。"]},{"t":"看山词","f":"古风","c":["生在江南地，始游湖南山。","江南看山山在地，湖南山在青天间。","高者大岳衡山灵，散为诸山无尽青。","天门玉帝窥彷佛，旌节导引龙鸾形。","飞泉喷薄石齿齿，洞房窈窕云冥冥。","忽然浩荡开巨壑，万顷波涛摇洞庭。","邈哉鬻熊开国年，昭平丧乱殊纷然。","伍员申胥小竖子，国运兴败随之迁。","仲尼书社竟难就，白公岂知日月贤。","接舆识威凤，乃歌灵德衰。","河滨鸣犊不相待，却望龟蒙归去来。"]},{"t":"谒岳神庙 其一","f":"七言律诗","c":["万山如马赴湘沅，衡岳超腾势独尊。","派别昆崙蟠楚蜀，位均嵩岱奠乾坤。","车书一统提封远，云雨诸方德泽存。","七十二峰高屏翰，天皇元自重南藩。"]},{"t":"谒岳神庙 其二","f":"七言律诗","c":["九成台殿神居迥，百里松杉石道赊。","海内名山惟五岳，天南星汉此孤槎。","来随使节脩禋祀，愿祝威灵保帝家。","主器皇储新定位，千秋万岁乐无涯。"]},{"t":"登祝融峰宿上封寺 其一","f":"七言律诗","c":["人间长望祝融峰，天上今登赤帝宫。","山势总朝星极北，海门遥见日华东。","清严辛借千林雪，浩荡真披万里风。","莫笑题名岩石畔，高情聊尽百年中。"]},{"t":"登祝融峰宿上封寺 其二","f":"七言律诗","c":["芒屩桃筇踏紫岑，蔚蓝天外快幽寻。","烟霄逼近星临大，海色微茫日出深。","下界俯看惟一气，浮名回首澹无心。","神仙总谓非灵骨，岩穴真看敞素襟。"]},{"t":"登祝融峰宿上封寺 其三","f":"七言律诗","c":["冰雪高岩树半残，罡风侵夜不胜寒。","斋临老衲翻经石，步上仙人礼斗坛。","望远正须峰万丈，探奇何惮路千盘。","清欢窃荷皇天惠，强健衰年最所难。"]},{"t":"上下诸峰间作 其一","f":"七言律诗","c":["紫盖峰头弄白云，朱陵洞口谒玄君。","湘妃竹点苍梧泪，神禹碑传玉薤文。","未遂著书藏石室，空嗟提剑傍人群。","中林散发何由得，徙倚西岩到日曛。"]},{"t":"上下诸峰间作 其二","f":"七言律诗","c":["蓝舆晓御八风轻，重叠青山接续迎。","画壁倚空看石势，玉琴喧涧得泉声。","人疑天上重开地，峰向云中自现名。","试傍紫霄瞻绛阙，崔巍如见九重城。"]},{"t":"上下诸峰间作 其三","f":"七言律诗","c":["岩松挺挺大夫身，石涧泠泠静者神。","云盖不迷韩刺史，书堂曾隐李山人。","英贤旧迹风俱逝，旌节初游雪正新。","唤取邹阳吹暖律，愿教寒谷转阳春。"]},{"t":"上下诸峰间作 其四","f":"七言律诗","c":["丹山碧水傲仙真，绝涧荒途隔世尘。","道学共尊胡父子，衣冠能避晋君臣。","长镵采药知何日，白发游峰有夙因。","肯许移家分一壑，为君当面解朝绅。"]},{"t":"上下诸峰间作 其五","f":"七言律诗","c":["南岩元居大火功，霜寒松桂自青苍。","穿林马踏烟霞色，煮涧茶分药草香。","天畔星缠窥翼轸，雪馀风景忆朱张。","衰残万事皆慵懒，独有登临兴尚狂。"]},{"t":"上下诸峰间作 其六","f":"七言律诗","c":["玉书金箓纪先贤，野老都无一二传。","石上剜苔寻古刻，岩阴开雪引灵泉。","销沈盛事堪长叹，料理閒情只自怜。","问讯邺侯三万轴，不知埋向若峰前。"]},{"t":"方广寺 其一","f":"七言律诗","c":["寒溪十里带残晖，古木阴阴一径微。","僧饭汲泉和雪煮，客堂明烛见云飞。","田开白石分千叠，山拥青屏匝四围。","行尽衡峰多佛宇，无如此地好归依。"]},{"t":"方广寺 其二","f":"七言律诗","c":["一宿霞门便出山，泉声雪色送君还。","金书尚荷君王宠，石髓难医俗士颜。","洞府逍遥尘土外，冠裳惭愧去留间。","武皇亦说捐妻子，何事吾人过尔悭。"]},{"t":"往来道中漫兴 其一","f":"古风","c":["青山夹道引行舆，百叠屏风步步殊。","雾窟尽容玄豹隐，风林时听白?呼。","赋传台岭行仍远，啸比苏门兴更孤。","安得龙眠李居士，写余衡岳访真图。"]},{"t":"往来道中漫兴 其二","f":"七言律诗","c":["糁径清霜午未消，背岩寒日照难交。","天分福地藏朱鸟，地拔危峰出紫霄。","虞舜巡来群后会，祝融居处百灵朝。","江湖满眼千山小，始信人间五岳高。"]},{"t":"往来道中漫兴 其三","f":"七言律诗","c":["壮观平生属此游，快心真胜拜通侯。","虚空秀岭呈丹凤，陆地仙人隐率牛。","木食草衣那送老，酒瓢诗版暂忘忧。","不知曲曲寒溪水，洗耳何人据上流。"]},{"t":"往来道中漫兴 其四","f":"七言律诗","c":["登山不自见奇峰，平地方怜紫翠重。","石壁半含残雪冷，烟林斜映夕阳浓。","深溪绝岸危桥接，古洞无仙乱草封。","问法拟投兰若宿，回风先报隔林钟。"]},{"t":"往来道中漫兴 其五","f":"七言律诗","c":["水木相牵野念兴，草堂归梦绕钟陵。","久知白石饥堪赖，况说青山盗不憎。","老陟乌台真失计，生图麟阁本非能。","锄瓜壅芋生涯在，底用求田向越僧。"]},{"t":"往来道中漫兴 其六","f":"七言律诗","c":["晴峰早布雪迎人，归路仍飘雨浥尘。","地主莫言乘暇日，山灵真为借佳辰。","穷高一览乾坤小，志怪初惊耳目新。","信道宣尼登泰岳，吴门白马望皆真。"]},{"t":"衡台对雪有怀","f":"七言律诗","c":["衡山吹雪散瑶华，且喜湖南岁事嘉。","云暗高峰回旅雁，水寒平野噪饥鸦。","殊方腊尽仍为客，好景情多倍忆家。","江左故人金帐底，听歌谁肯念天涯。"]},{"t":"排山晓发","f":"七言律诗","c":["五更吹角起征夫，百里传餐戒晚厨。","乌府自惭成忝窃，熊轓那敢惜驰驱。","尘埃长远云生榻，瘴疠全消雪满须。","惠爱倘闻千里洽，江湖从遣一身孤。"]},{"t":"冒雪往会钱邢二使君","f":"五言律诗","c":["五更吹角起，征夫均有程。","祗今湘水棹，何异剡溪情。","瑞采千林雪，皇华万里旌。","天涯分袂意，留语记芝城。"]},{"t":"祁阳道中雪 其一","f":"七言律诗","c":["南雪常传到地消，湘东今见踏琼瑶。","水铺练带平争白，树簇银花静不摇。","野色倍添梅萼宠，土膏先动草心骄。","天涯莫自伤迟暮，早报丰穰慰寂寥。"]},{"t":"祁阳道中雪 其二","f":"七言律诗","c":["潇湘之景清且妍，雪中行吟更可怜。","乱峰插地万圭出，高鸟背云孤鹤鶱。","连林古木各生意，一望江天弥素烟。","惜哉相如未始见，作赋漫为梁园传。"]},{"t":"熊罴岭望雪","f":"七言绝句","c":["熊罴岭头望雪花，千林万壑玉交加。","若为扫尽浮云色，夜拥狐裘看月华。"]},{"t":"夜至祁阳以录囚行","f":"七言绝句","c":["篝火荧荧夹道明，夜江寒浸百家城。","天王不弃南荒远，直布阳和及死生。"]},{"t":"祁阳怀故通参程德和","f":"五言律诗","c":["特达千人俊，醇良万石君。","遗书留学阁，宿草满荒云。","后辈推耆旧，南曹奉德薰。","颇伤身后事，不愧墓前文。"]},{"t":"题笑岘亭","f":"七言绝句","c":["浯山窃笑岘山碑，也自磨厓向水涯。","陵谷变迁皆瞬息，不缘金石有名垂。"]},{"t":"污尊","f":"五言绝句","c":["元公古天民，污尊表其德。","堂堂刺史身，甘隐漫郎宅。"]},{"t":"元颜书院用钱给事韵","f":"五言律诗","c":["元颜惊代杰，精爽结灵云。","运屈英雄力，山垂琬琰文。","皇图天自远，世变雪徒纷。","倚杖看碑客，悽然仰德芬。"]},{"t":"漫郎宅用邢侍御韵","f":"五言律诗","c":["炯炯舂陵作，丹心白日明。","几人能体国，遗爱在专城。","使节临湘楚，心香仰法程。","看公流浪迹，宠辱底须惊。"]},{"t":"辱奉钱邢二使君高山寺留别","f":"五言律诗","c":["别思凭高集，征途向粤遥。","岭梅春候转，湘浦雪痕消。","斧钺随王命，蛮夷拱圣朝。","澄清联辔去，双璧听新谣。"]},{"t":"朝阳岩奉饯钱邢二使君","f":"五言律诗","c":["水府攀跻险，云房结构重。","晴筵移瓮蚁，胜侣得人龙。","古刻曾谁在，今游不易逢。","黄昏仍秉烛，明发有离踪。"]},{"t":"十二月念六日出永州值迎春新霁","f":"七言律诗","c":["江城鸣鼓晓迎春，霁日和风应候新。","苍帝早矜时令正，紫微元握斗枢均。","梅花弄粉相将出，柳眼舒青太剧真。","曝背老翁皆报罢，莫愁穷谷有悬鹑。"]},{"t":"全州唐宗周文世范访于芝城行台","f":"七言律诗","c":["雪后扁舟拨棹来，湘江何减剡溪怀。","灯前软语浓于酒，庭下春光早报梅。","棠树尚留听讼处，柳山长忆读书台。","殷勤白首相逢地，不尽行台五夜杯。"]},{"t":"澹岩题石","f":"古风","c":["玄云结宇，白日回光。","神灵所辟，仙真斯藏。"]},{"t":"游澹岩","f":"五言古诗","c":["楚南多名洞，澹岩绝幽奇。","崇山豁中空，石壁支云欹。","匪伊神灵凿，讵备房栊施。","夹径周窈窕，盘折乃尽窥。","天窗白日皎，百用宛相宜。","初闻避世士，倾家乐兹移。","世往祗虚宇，好事纷游嬉。","森罗尽深刻，漫读知为谁。","唯输振代豪，屹尔高名垂。","以兹叹物理，不朽由人为。","微生亦蛙黾，难与千古期。"]},{"t":"潇江泛舟入道州","f":"五言古诗","c":["潇江清且驶，舍车泛轻舠。","稍恬荡漾趣，暂谢登顿劳。","石脚插潭腹，危峰叠争高。","牵夫不可度，孤猿攀树号。","滩水日倾泻，触石怒成涛。","游鱼掷影过，尾赤惮所遭。","绝流百具备，嗟尔将焉逃。","信哉法网密，民生始嗷嗷。","周公有令典，无取斯鞅曹。"]},{"t":"丁酉除日道州作二首 其一","f":"五言律诗","c":["驱驰惊道远，衰白感年除。","浮世皆为客，他乡亦可居。","酒杯从仆进，风物向春舒。","眷恋残更漏，挑灯展旧书。"]},{"t":"丁酉除日道州作二首 其二","f":"五言律诗","c":["老来怜岁月，除夕每题诗。","正自悲摇落，那堪怨别离。","家园繁节物，耆旧俨光仪。","赋就宜春帖，淋漓映户施。"]},{"t":"戊戌元日道州作二首 其一","f":"五言律诗","c":["圣寿冈陵固，蛮荒岁序新。","熊轓随使节，虎拜庆王春。","礼乐周天洽，阳和播物均。","愿明四门目，照尔万方人。"]},{"t":"戊戌元日道州作二首 其二","f":"五言律诗","c":["潇水碧于玉，潇山青满天。","褰帷临胜地，驻节度新年。","岭近梅花盛，林和桂叶妍。","空庭无讼牒，端坐咏诗篇。"]},{"t":"舂陵怀古二首 其一","f":"五言律诗","c":["道丧馀千载，天南得异人。","玄图开太极，绝学指迷津。","庭草长交翠，池莲不断春。","愿因风月地，潇洒挹公神。"]},{"t":"舂陵怀古二首 其二","f":"五言律诗","c":["舂陵贼退作，洒血示中襟。","狼狈干戈际，勤惓禹稷心。","溪清甘寄宅，运去阻为霖。","工部惟良语，仁贤痛至今。"]},{"t":"全州蒋司空景明来会于道州白鸡营","f":"五言律诗","c":["虎榜同袍旧，鱼书隔岁盟。","关山千里驾，鸡黍百年情。","容鬓非前少，勋名属晚成。","湘南谢安石，早出为苍生。"]},{"t":"新晴","f":"五言律诗","c":["献岁晴偏好，新晴暖即随。","树怜迟旭映，草爱惠风吹。","远岫分青霭，平池荡绿漪。","缘原车马健，偏与省方宜。"]},{"t":"月岩","f":"五言律诗","c":["灵岩象唯月，盈昃巧为妍。","正揭团圆影，旁分上下弦。","龙开厓畔石，日转窍中天。","雕琢须神力，伊谁测帝先。"]},{"t":"人日宁远山行三首 其一","f":"七言绝句","c":["人日轻云漏日华，高山晴景应吹笳。","东皇挈取阳和气，散满衡湘十万家。"]},{"t":"人日宁远山行三首 其二","f":"七言绝句","c":["万岭千峰蔽楚天，盘厓石路马啼穿。","秦人住向桃源里，犹想重华问俗年。"]},{"t":"人日宁远山行三首 其三","f":"七言绝句","c":["上下邮程祗在山，白云苍雾苦跻攀。","閒情独被梅花觉，引领春风破客颜。"]},{"t":"谷日桂阳山行雨","f":"五言律诗","c":["谷日风兼雨，农家抱岁忧。","占书期不验，王政戒先脩。","野色抽寒麦，春声唤暝鸠。","行人本田父，荷笠爱驱牛。"]},{"t":"郴州十三夜试灯","f":"七言律诗","c":["今夕何夕春灯明，此乡何乡非我城。","物华满眼各殊态，月色映阶无限情。","梅花乍逢已烂熳，萱草欲发初分明。","却忆故园诸酒伴，锦屏围夜坐吹笙。"]},{"t":"元夕","f":"七言律诗","c":["上元佳节在山城，逝水流年忽自惊。","灯火殊方同节候，歌钟何处起春声。","衰残断酒江梅笑，飘泊怀乡鬓雪生。","四海幸逢阳道泰，官曹端坐咏升平。"]},{"t":"郴台官梅","f":"七言律诗","c":["郴州行台风日妍，官梅两株清可怜。","祗缘老干临高榭，故著繁花媚远天。","绕院蜂声喧不去，隔江鱼素渺谁传。","脩篁怪石俱无赖，点缀幽情向客边。"]},{"t":"至郴访司马李贻教同年夜话二首 其一","f":"五言律诗","c":["仄叠郴阳坂，怀君夙驾过。","风神清不减，著作老仍多。","饮量开江海，幽栖脱网罗。","素丝劳枉赠，疲薾奈吾何。"]},{"t":"至郴访司马李贻教同年夜话二首 其二","f":"五言律诗","c":["屈指分携久，披心旧好谐。","悬灯如梦里，接席自天来。","世变秋云改，民穷泽雁哀。","莫嗔无酒兴，深语阻衔杯。"]},{"t":"乍暖","f":"七言绝句","c":["阴厓春令几时回，即有山花映路开。","冰雪祗今无处著，柳丝桃萼莫疑猜。"]},{"t":"度岭赴耒阳三首 其一","f":"五言绝句","c":["斜日半岩阴，回溪百丈深。","蹬危元借石，叶老不辞林。"]},{"t":"度岭赴耒阳三首 其二","f":"五言绝句","c":["元夕村村鼓，春山处处花。","韶光宜对酒，行客倍思家。"]},{"t":"度岭赴耒阳三首 其三","f":"五言绝句","c":["椒团黄粉腻，柳染翠丝匀。","献颂宜新岁，攀条怆远人。"]},{"t":"口占次郑时明国学梅花诗韵二首 其一","f":"七言律诗","c":["玉体珠衣岂洛神，前生姑射是元真。","芳菲管领先天气，风格依稀绝粒人。","明月池台横浅水，艳阳桃李隔红尘。","广平见说心如铁，别有调羹万斛春。"]},{"t":"口占次郑时明国学梅花诗韵二首 其二","f":"七言律诗","c":["閒将标格品花神，独许梅花自有真。","雪里清香无俗艳，水边潇散一高人。","盟心特挺冰霜节，透骨那薰脑麝尘。","招引东皇回淑气，任教红紫领馀春。"]},{"t":"耒江夜行","f":"五言律诗","c":["耒江春浩荡，兰棹夜夷犹。","风止灯花喜，天空角响愁。","滩流嗽欹石，岸犬吠行舟。","累月劳车骑，篷窗得暂休。"]},{"t":"重到石鼓书院","f":"七言绝句","c":["石鼓灵踪渺不存，朱陵仙洞已无门。","洋洋弦诵歌邹鲁，只仰朱张道学尊。"]},{"t":"花药寺","f":"五言律诗","c":["古佛祗阇苑，前朝帝子居。","龟龙缠石碣，虎豹守松庐。","尘海波翻覆，人天事有无。","想临烦恼障，应悔就金舆。"]},{"t":"春意三首 其一","f":"七言绝句","c":["正月垂杨绿映堤，傍山新溜碧澄溪。","暖风消尽寒岩雪，换得黄鹂向客啼。"]},{"t":"春意三首 其二","f":"七言绝句","c":["日满高原云满汀，天涯随处草青青。","山茶落尽樱桃发，遥忆家园载酒亭。"]},{"t":"春意三首 其三","f":"七言绝句","c":["郴南周览几山城，更向澬州问客程。","春色平铺三百里，梅花千树伴经行。"]},{"t":"远笔铺夜坐待药","f":"五言律诗","c":["老境形神减，征途药饵随。","长勤应损寿，多病渐通医。","公事谁能了，仙人不可期。","凭将行止意，清夜叩灵龟。"]},{"t":"大云山","f":"五言律诗","c":["衡岳有馀秀，大云如削成。","春烟浓染树，晴嶂曲连城。","采药怀仙隐，经丘畅野情。","飘飘霞外赏，真薄世间名。"]},{"t":"高楼寺二首 其一","f":"五言律诗","c":["静夜宿高云，心清远世氛。","奇峰移座得，鸣涧下阶闻。","瓶注杨枝水，灯翻贝叶文。","经年尘土面，借尔妙香薰。"]},{"t":"高楼寺二首 其二","f":"五言律诗","c":["萝径冲云入，松房听雨眠。","佛幡摇殿吹，野火照蛮烟。","院静那成梦，形劳不近禅。","闾阎苟无补，空使负林泉。"]},{"t":"宝庆府澬江之上有石矶焉当水之冲甚峭特旧固无名余偶登之题曰砥柱矶系四韵","f":"五言律诗","c":["昆崙一卷石，飞落碧江漘。","尽日浮佳气，中流立此身。","楼台悬峭景，桃李点芳春。","阅尽狂澜色，何须顾水神。"]},{"t":"出宝庆四首 其一","f":"七言绝句","c":["十日澬城未出门，登车芳草暗平原。","深红浅白花无赖，转为春光一断魂。"]},{"t":"出宝庆四首 其二","f":"七言绝句","c":["过雨泉声绕树来，隔云山色映花开。","吏人若过桥东少，唤取村翁共酒杯。"]},{"t":"出宝庆四首 其三","f":"七言绝句","c":["树树桐花素雪披，行台迎暖试罗衣。","逢春到老能多少，一度韶华忽已违。"]},{"t":"出宝庆四首 其四","f":"七言绝句","c":["细雨沾衣不见飞，隔墙桃李雾中微。","家园酒熟梅如豆，稚子应怜客未归。"]},{"t":"禽言六首 其一 行不得哥哥","f":"古风","c":["楚山造天，楚水扬波。","轻舟良马，败亦孔多。","二物不备，将奈楚何。","行得不得，寄言尔哥。"]},{"t":"禽言六首 其二 不如归去","f":"古风","c":["置酒高堂，佳殽且庶。","白日未晡，有狂者倨。","我性亶愚，惧不我与。","不我与，将必有处。","不如俛首，及昼归去。"]},{"t":"禽言六首 其三 姑恶","f":"楚辞体","c":["姑兮我母，胡宁我虐。","弗慎于仪，衅自下作。","母也尔容，姑乃义合。","上行其义，怨者归薄。","是究是图，诚匪姑恶。"]},{"t":"禽言六首 其四 泥滑滑","f":"古风","c":["终风发发，周道如刷。","零雨沾之，足不得劄。","匪足不劄，覆车及辖。","尔行弗时，勿谓泥滑。"]},{"t":"禽言六首 其五 婆饼焦","f":"古风","c":["阿姥作饵，妇也烧之。","承令弗虔，火则燎之。","古有顺妇，叱犬摽之。","尔婆有饼，宜尔妇焦之。"]},{"t":"禽言六首 其六 看蚕看火","f":"古风","c":["蚕生于原，匪温斯瘅。","火以炀之，烈则杀我。","尔将崇利，毋贻我祸。","既看我蚕，请看尔火。"]},{"t":"武冈道中雨二首 其二","f":"五言律诗","c":["风狂花片轻，春事恼閒情。","急雨潜鱼起，新雷乳鸭惊。","浮生悲代谢，大造剧生成。","笑断杯中物，来干身后名。"]},{"t":"宿兰桥山馆大雨","f":"七言绝句","c":["山雷划辗长空过，檐雨平添积水深。","去住总关神物算，阴晴何与道人心。"]},{"t":"雨度车轮岭二首 其一","f":"五言律诗","c":["野馆三更雨，山溪一尺泥。","王尊驰折坂，马援下蛮溪。","高举羞鸿翮，长途厄马啼。","圣朝方用壮，冉冉独庞眉。"]},{"t":"雨度车轮岭二首 其二","f":"五言律诗","c":["山泼风前雨，人浮道上波。","农家戒耕作，行者答劳歌。","云暗遥峰少，春深缘树多。","行藏两孤负，身世转蹉跎。"]},{"t":"宿西桥铺听雨旧有西桥月色之榜","f":"七言绝句","c":["西桥月色昔人游，南楚春光野客收。","堪笑地灵多爱惜，一宵鸣雨送羁愁。"]},{"t":"空山","f":"七言绝句","c":["空山行尽不逢人，三户曾传旧楚贫。","幽冀如山收贡税，丹砂仍备尚方珍。"]},{"t":"至武冈望云山可爱因忆金陵东郊武冈山甚动乡思","f":"七言律诗","c":["楚国春花伤客情，台居频梦秣陵城。","名山忽向殊方得，客路如从故里行。","碧水护田生野兴，黄鹂穿竹送歌声。","归时若上崇冈望，正想南云万里横。"]},{"t":"自武冈行边往靖州","f":"七言律诗","c":["清昼行边列校随，貔貅十队拥军麾。","青山得云美如画，骏马当路平堪驰。","泉明宝剑悬金甲，风引崇牙飏绣旗。","老手十年椎钝极，更来横槊一裁诗。"]},{"t":"饭山口堡","f":"七言绝句","c":["平峦高捧百夫城，四野花开战垒平。","饭罢独行观戍卒，枕戈閒调凯歌声。"]},{"t":"岭傍深溪见花柳甚幽","f":"七言绝句","c":["孤峰天畔绝人家，山杏山桃夹路花。","欲访韩终求石髓，洞门深锁一溪霞。"]},{"t":"出武冈关","f":"七言律诗","c":["连岭横天白日微，溪流下堑客行稀。","山花照水开还落，野雉出林鸣且飞。","万里承恩虚仗钺，九重柔远正垂衣。","巡行本欲输筋力，敢谓乘春布德威。"]},{"t":"度磨石岭","f":"七言绝句","c":["磨石岭头春日晴，白云如絮绕车生。","前生似得丹砂力，长向青天掉臂行。"]},{"t":"度火甲诸小岭","f":"七言绝句","c":["大岭何如小岭多，车如鸟翼倏经过。","千岩万壑穷奇状，阆水蓬山更若何。"]},{"t":"度退田安乐诸坡三首 其一","f":"七言绝句","c":["平峦绝顶路逶迤，飞盖青霄引画旗。","只恐人从千里见，误传旌节降云师。"]},{"t":"度退田安乐诸坡三首 其二","f":"七言绝句","c":["千仞峰头见日光，起挥袍袖拂青苍。","蛮天且喜浮云尽，拭目长安紫极傍。"]},{"t":"度退田安乐诸坡三首 其三","f":"七言绝句","c":["仰随飞鸟起高天，俯逐游鱼坠九渊。","若遣王阳经此地，定知中道即回鞭。"]},{"t":"青靛山","f":"五言律诗","c":["望望青瑶柱，登登碧汉梯。","石角垂高壁，泉流响暗溪。","朱萍仍布沼，紫蕨乍生荑。","好寻黄石约，相傍偓佺栖。"]},{"t":"靖州吊宋义卿","f":"七言律诗","c":["皇天不吊颜公死，湘水无情屈子沈。","彊圉一身关国体，忠贞千古动人心。","精魂白日涛犹怒，祠庙空山柏已森。","宿草孤坟何处奠，只馀清泪洒衣襟。"]},{"t":"靖州阅武","f":"五言古诗","c":["圣代舆图广，襟包及夜郎。","连城严屏翰，万旅肃封疆。","星驾行春远，霜台校武强。","六韬呈战略，五善肃边防。","花暖蛮烟息，风雄士气扬。","戈鋋寒雪色，旗帜锦云光。","力羡争超距，材精许擅场。","射雕飞迅镝，走马背长枪。","本藉皇威大，还资国器良。","辕门推毂重，帷幄运筹长。","羽扇吾真忝，干城尔各当。","紫宸宵旰虑，应免顾南荒。"]},{"t":"登飞山","f":"五言古诗","c":["渠阳众山内，飞山郁岧峣。","平嶂蟠近郭，孤峰插层霄。","仰攀万丈梯，弱袂飞狂飙。","股栗不能定，地轴如动摇。","云房妥明神，百灵俨相传。","风雷在左右，倏忽应招邀。","丰凶非所遗，祈报争喧哓。","苗夷伏石陛，犦牲时献膋。","磴边数小树，野火不敢烧。","谁云俗尚鬼，实以威灵昭。","神道可设教，勿谓同昏妖。"]},{"t":"谒鹤山祠","f":"五言古诗","c":["魏公圣人徒，志比曾闵肩。","讲道振西蜀，学子从如烟。","一朝动九重，黄纸飞传宣。","郡吏俛负弩，小夫争执鞭。","持议或矛盾，风云俄变迁。","时相既侧目，众口森戈鋋。","汉世锢党人，唐贤投浊川。","渠阳一掬水，岂纵蛟龙旋。","所赖坦荡怀，安土乐其天。","福坡采秋薇，书堂酌星泉。","教覃儒化远，身老士节坚。","啾啾鬼蜮辈，粪壤何足捐。","空堂仰遗像，清风犹洒然。","残编等白璧，愿为浮世传。"]},{"t":"下双厓岭入会同","f":"五言古诗","c":["双厓分剑门，石道中贯出。","危如坠渊下，经过已非一。","所荷皇天慈，惠我得晴日。","翩翩转轻舆，荦确千怵惕。","嗟尔冰雪晨，行者慎其术。"]},{"t":"下松厓岭入黔阳","f":"七言绝句","c":["荒云莽苍石厓横，不见青松但有名。","嗟来诛求贫到骨，肯容材木遂生成。"]},{"t":"石亭寄诗和答","f":"七言律诗","c":["休官独向山中住，久厌疏狂学孟公。","盘薄解衣时作画，跏趺临水亦谈空。","松萝野兴宜明月，海岳文光贯彩虹。","愧我离君走尘土，高情徒寄梦魂中。"]},{"t":"舟晓","f":"五言律诗","c":["溪流涨新绿，稍浣尘中衣。","岸草媚春色，林霞开曙晖。","樯燕惊忽去，水烟晴渐微。","倚篷悟节改，轻风飞絮稀。"]},{"t":"舟午","f":"五言律诗","c":["窗中日气暖，杜若花微芬。","舟轻后浪迈，野晴前嶂分。","炊烟隔浦见，莺声临岸闻。","兰桡兢利涉，界破波心云。"]},{"t":"舟晚","f":"五言律诗","c":["扬帆背落日，云昏半溪阴。","归鸦已喧噪，游凫尚浮沈。","奔程促橹节，警戍悲笳音。","龙标夕烟暗，悠悠伤客心。"]},{"t":"舟夜","f":"五言律诗","c":["道人爱夜寂，习静虚舟中。","开帘恐辜月，系缆讵忧风。","眼鸥恋暖渚，归雁喧晴空。","乡心不及水，坐驰徒向东。"]},{"t":"自沅溪拥小队汎舟向辰","f":"七言律诗","c":["双橹夹船鹅鹳鸣，五溪春日照行营。","朱旗耀水翻风影，画鼓凭厓殷谷声。","蛮洞卉裳趋使节，辕门花帽拥儒生。","当年铜柱劳筋力，此日轻裘凛甲兵。"]},{"t":"黔阳顺流下滩","f":"七言绝句","c":["云锼岭脚跨盘涡，怪石浮沈万骆驼。","一片轻舟飞箭过，却疑槎影渡天河。"]},{"t":"寄寿陈石亭","f":"七言律诗","c":["梦里钟山万仞青，江天东望少微星。","当朝旧擅扬雄赋，有子新传卜氏经。","止酒先生逃净社，焚鱼学士住岩扃。","遥怜耆旧称觞会，独少尘容在画屏。"]},{"t":"五溪曲六首 其一","f":"五言古诗","c":["皇天辨下土，夷夏各有防。","冠冕与椎祼，人兽本殊方。","三五圣哲代，建国但中疆。","有苗或侮予，干羽舞阶隍。","悠悠七旬内，卉服歌来王。"]},{"t":"五溪曲六首 其二","f":"五言古诗","c":["五溪何滔滔，夷落限穷岑。","天王主岳渎，衡山屹南临。","秦皇苦多事，汉武志亦淫。","楼船渡牂牁，铜柱开郁林。","舆图自此广，戈矛长见寻。"]},{"t":"五溪曲六首 其三","f":"五言古诗","c":["殷宗伐鬼方，三年始休兵。","淮南谏南征，瘴疠哀群生。","山多蛇虺毒，水有含沙腥。","苟非蛮种类，白骨死榛荆。","寄言兵家子，勿与绝域争。"]},{"t":"五溪曲六首 其四","f":"五言古诗","c":["白金如流水，丹砂血色殷。","羌儿急衣食，关市委丘山。","珍异虽云贵，采掇良艰难。","不见乳穴记，戕生犹等閒。","所宝在五谷，远物何足悭。"]},{"t":"五溪曲六首 其五","f":"五言古诗","c":["百里屯一军，五十置一堡。","舂陵达酉溪，士卒联部伍。","财粟日转输，外禦苗夷侮。","况复粤巂间，岁益征戍苦。","楚人今凋残，请勿拓边土。"]},{"t":"五溪曲六首 其六","f":"五言古诗","c":["孤戍高山颠，鸣角夜呜呜。","月明尚苦颜，况临风雨途。","主将位日贵，重帷锦模糊。","李牧今去久，谁闻捐市租。","哀哉古人言，一功万骨枯。"]},{"t":"出武溪","f":"七言绝句","c":["龙标远在夜郎西，鼓楫扬歌下武溪。","却笑伏波无猛气，水鸢何事动悲啼。"]},{"t":"见水上飞燕","f":"七言绝句","c":["辰溪燕子点波飞，恰似江南带雨归。","对入画梁相并语，满庭红艳发蔷薇。"]},{"t":"返辰州 其一","f":"七言律诗","c":["生憎江草唤愁生，闷见垂杨暗古城。","隔岁家山仍北望，五溪烟瘴返南征。","闾阎未报宽租税，轩冕空嗟拂性情。","岁岁深岩求大木，不知陵庙几时成。"]},{"t":"返辰州 其二","f":"七言律诗","c":["满江烟浪一官舟，直指巡行遍几州。","楚国封疆通塞徼，庾公江汉盛风流。","飞鸢堕地还苍水，瘴岭愁人易白头。","五柳先生真傲吏，暂来彭泽即归休。"]},{"t":"石壁","f":"七言律诗","c":["一水回流抱古原，两山对起立江门。","崩厓半出溪心渚，古木斜悬石背根。","远见虞罗伤翠鸟，时逢洞穴羡苍猿。","摐金伐鼓劳生地，不及渔竿弄晓昏。"]},{"t":"风作","f":"五言律诗","c":["乘船休谓逸，便有阻风愁。","且任鼋鼍势，谁同鸥鹭谋。","病多休对酒，岸近一登丘。","满目凄凄草，王孙怨薄游。"]},{"t":"大风","f":"七言律诗","c":["白波飞舞雪山摧，苍野喧轰万壑雷。","猛势欲翻坤轴侧，大声遥向昊穹来。","昆阳虎豹寒应慄，瀚海鱼龙倒却回。","有客披襟还借问，此中噫气为谁哀。"]},{"t":"辰沅之间","f":"七言律诗","c":["武陵西上酉溪东，信有仙源不可穷。","峭壁凌空欲飞起，淡烟临午亦空濛。","舟从镜里移丹鹢，水向云边挂白虹。","何处招寻陶谢手，恣渠挥笔竞才雄。"]},{"t":"过壶头山","f":"七言律诗","c":["伏波兵甲驻壶头，南望蛮烟泣楚囚。","马革里尸徒尔尔，兽心回面竟悠悠。","愁闻鬼域凭岩隐，怕见虫蛇出浪游。","万里枉开秦汉土，九围元拱帝王州。"]},{"t":"闻客谈桃源诸仙","f":"七言绝句","c":["瞿桐石上千年树，桃老川边满目花。","钟鼎误人空老去，不如来此学飧霞。"]},{"t":"武溪滩","f":"七言绝句","c":["乱石当流奋虎牙，扁舟飞出浪前花。","瞿塘象马何如此，猿声休自怨三巴。"]},{"t":"江上石峰","f":"七言绝句","c":["江上青峦映碧空，垂岩花叶飐春风。","楼船荡桨开帘去，忘却行人是客中。"]},{"t":"次韵呈陈兵侍高吾杨太仆闻山二年丈兼自述三首 其一","f":"五言律诗","c":["东山归卧久，何日理安车。","待月桥临沼，吟风竹满墟。","道高公望属，心远俗尘袪。","白首枢衡地，经纶力有馀。"]},{"t":"次韵呈陈兵侍高吾杨太仆闻山二年丈兼自述三首 其二","f":"五言律诗","c":["暂辟留侯谷，聊巾陶令车。","清风高省阁，礼俗变乡墟。","庭晓鹤常报，座寒蝇自袪。","峥嵘康济略，仍在笑谈馀。"]},{"t":"次韵呈陈兵侍高吾杨太仆闻山二年丈兼自述三首 其三","f":"五言律诗","c":["偶回驱犊手，来上画熊车。","问俗仍周史，扬旌漫楚墟。","凤麟忻并睹，豺虎叹何袪。","直道三王化，空怀百代馀。"]},{"t":"次韵答闻山 其一","f":"五言律诗","c":["远至逢今雨，相逢叹曙星。","云披瞻北斗，龙卧近南溟。","醒酒无奇石，谈玄只旧亭。","雷陈居接近，笑傲共岩扃。"]},{"t":"次韵答闻山 其二","f":"五言律诗","c":["实少匡时策，虚传拙政声。","中台惭宠命，倒囷负鳏茕。","访旧春生座，论诗雨满城。","最忻高士侧，下榻领深荣。"]},{"t":"再次答高吾 其一","f":"五言律诗","c":["麟阁终当画，鸥波此暂盟。","冥鸿霄汉志，野鹤水云情。","按剑心长远，传经草渐成。","丈夫随出处，终不负平生。"]},{"t":"再次答高吾 其二","f":"五言律诗","c":["不畏羊肠坂，遥寻雁塔盟。","风波悲往事，云月见高情。","技笑飞鼯尽，名嫌画虎成。","还思万松坞，种麦了馀生。"]},{"t":"避洞庭取道安乡山行自嘲","f":"七言律诗","c":["宗悫破浪思长风，而我取道行山中。","人间祸福岂自料，古人意气真豪雄。","何不高挂十幅篷，飞桡直渡冯夷宫。","岳阳楼前望夏口，月明吹笛楚江东。"]},{"t":"安乡晓发","f":"五言律诗","c":["缺月尚中天，残星落落悬。","露寒蛙不噪，草暗蝶犹眠。","病怯春衣减，行妨野水连。","老农乘雨过，相并理畬田。"]},{"t":"次韵寄答九峰徵君","f":"五言律诗","c":["道许心交密，诗传醉墨温。","乡闾称丈行，艺苑服专门。","花月台端瑟，江云树下尊。","何时分一座，谑浪睨乾坤。"]},{"t":"罗简翁去秋梦余赋诗见寄经春始达次韵奉复","f":"七言律诗","c":["题封入手移春月，离别经心属暮年。","交谊拟同泉石老，宦情惭被简书牵。","山中耆旧诗谁健，江上形容梦独悬。","细捲瑶笺藏箧笥，子孙他日会相传。"]},{"t":"华容马上","f":"七言律诗","c":["白马朱幩不动尘，豸袍龙剑照青春。","多忧敢谓先天下，拙用真惭对古人。","万事推移心匪石，百年衰病鬓如银。","经纶本属当朝杰，懒慢终随击壤民。"]},{"t":"岳州临江驿见亡友凌溪子题壁怆然兴怀倚韵追悼 其一","f":"七言律诗","c":["滇海形容老瘴烟，文章惊代已徒然。","谗多城市俄生虎，运去英雄莫问天。","旧学传家今有后，新诗题壁迥无前。","颜回子夏元方驾，何处脩文作地仙。"]},{"t":"岳州临江驿见亡友凌溪子题壁怆然兴怀倚韵追悼 其二","f":"七言律诗","c":["鹦鹉才高失帝庭，人间穷达转冥冥。","久将尘土抛金紫，自慱声华付汗青。","避地盟寒空卜筑，招魂歌就或来听。","笛声莫怆山阳舍，琴操期闻中散灵。"]},{"t":"岳州临江驿见亡友凌溪子题壁怆然兴怀倚韵追悼 其三","f":"七言律诗","c":["词笔飘飘压两都，当年声价许谁俱。","争传庾信雄江左，竟误虞翻落海隅。","友道金兰三世合，诗篇陶冶万人模。","扁舟旧约江门路，千古伤心甓社湖。"]},{"t":"哀按察华容八厓周公","f":"五言古诗","c":["海内诗家流，按察名不细。","仰溯风雅源，俯拾文选例。","词锋捷如神，学海荡无际。","洒翰迅风雨，旁视惊巨丽。","士衡允如流，正平岂停缀。","居诸几何间，充栋积篇系。","奇葩灿繁英，野鹤抗孤唳。","众人恶其上，转面生怒恚。","矧兹豪士怀，高论激当世。","万乘犹可干，岂复避贵势。","铄金每潜机，下石憎毒厉。","青云竟塌翼，黄壤俄挥涕。","楄心愤难平，几欲愬上帝。","观风临德乡，感旧重悲逝。","惨怛堂上容，酸悽草间祭。","结念江汉灵，愁云暗松桂。"]},{"t":"自嘉鱼挂帆归武昌三月晦日也","f":"七言律诗","c":["蒲帆满驾顺流风，黄鹤楼台在眼中。","柳色已经春候尽，城闉何啻故乡同。","尘埃白发空奔走，岩谷苍生自困穷。","万事关心无料理，漫芜瓜地国门东。"]},{"t":"登庐州镇淮楼同项守饮后作","f":"七言律诗","c":["天畔飞楼谁搆成，画栏朱槛倚空明。","江湖一片当窗泻，云雾千重对酒生。","独立淮淝雄旧国，俯听弦诵蔼新声。","夜深灯火同星散，不尽风流地主情。"]},{"t":"坐蕲州西池驿作","f":"五言律诗","c":["衰年重作宦，入楚问民风。","岂谓山川异，还嗟杼轴空。","官常存国典，惠泽自皇躬。","千里旬宣寄，安危仗数公。"]},{"t":"赠郑主事观兑运还京","f":"七言律诗","c":["使君才调出群雄，来试萧何馈饷功。","坐运军储轻在掌，笑吞云梦浩填胸。","南征羽檄飞星过，西涨川波洚水同。","圣主深宫忧万里，归朝何以献民风。"]},{"t":"赠冯巡按孟元得代还朝","f":"七言律诗","c":["君来祇见衡山动，君去犹闻汉水清。","公辅眼中须屈指，别离江外独关情。","霜飞归路秋仍肃，日丽高天道正行。","宣室若承明主问，楚民皆喜罢南征。"]},{"t":"黄鹤楼野望","f":"七言律诗","c":["黄鹤楼高玉笛哀，江声长绕碧窗回。","孙刘去后空残垒，夏鄂登来有壮怀。","重镇旌旄虚窃禄，荒洲词赋独怜才。","乡关只在烟波外，何日扬帆破浪回。"]},{"t":"三弟舜玉六十","f":"五言律诗","c":["仲兄官未罢，爱弟寿仍高。","白首违琼树，青山落布袍。","乡评元独重，酒兴近谁豪。","却恨埙篪会，无因附尔曹。"]},{"t":"喜雨二首 其一","f":"五言律诗","c":["雨声来夜壑，天惠洽秋成。","自有神龙作，那同旱魃争。","白波俄满眼，黄稿尽回生。","六事桑麻责，君王本圣明。"]},{"t":"喜雨二首 其二","f":"五言律诗","c":["儿童沉蜥蜴，道士召风雷。","人事空多枉，天心自欲回。","时非汤世运，地薄楚人哀。","云汉忧方剧，聊输笑口开。"]},{"t":"新竹","f":"五言律诗","c":["犊角初穿地，龙梢倏过墙。","孙枝高胜母，野色翠侵堂。","林许清风入，人将俗抱忘。","难逢嵇阮辈，终日弄壶觞。"]},{"t":"午日以杏实榴花馈开府谭公","f":"七言绝句","c":["蜜脾已酿东林杏，腥血仍妆后苑榴。","莫道端阳浑寂寞，也脩时令荐王侯。"]},{"t":"寄贺李序庵相公新第次浚川公韵","f":"七言律诗","c":["天衢甲第丹霄迥，楼阁虚明望转微。","海日重光开冉冉，宫云五采映霏霏。","喜延宾客时分席，静玩琴书昼掩扉。","退食从容无一事，愿歌隆栋荅垂衣。"]},{"t":"寄贺夏桂洲相公新第次前人","f":"七言律诗","c":["天上神仙居有府，海中楼观净无尘。","檐甍直捧丹霄日，竹树长含碧苑春。","梦兆麒麟生蕙阁，文裁鸾凤赞枫宸。","攸宁实荷周王宠，近市元非晏子真。"]},{"t":"入园偶题","f":"七言绝句","c":["菜陇横斜竹径成，海榴红喷亚枝明。","台居理得山林景，不负衰翁入楚行。"]},{"t":"赠李户部孟川","f":"五言律诗","c":["不识干将利，聊看试象犀。","使君监楚饷，五月渡淮齐。","逸气凌黄鹤，高才亚碧鸡。","襄阳閒点笔，传满白铜鞮。"]},{"t":"旱","f":"五言律诗","c":["楚困那宜旱，雷藏不肯鸣。","苍天乖岁令，赤土废春耕。","巢燕愁泥竭，池鱼怕火生。","不知从政者，何以格神明。"]},{"t":"夜坐见萤火有怀故园","f":"七言律诗","c":["高城萤火夜深飞，带雨中林转细微。","腐草馀光皆物化，乘风高举亦天机。","流年过眼催仍急，浮客怀乡叹未归。","义范堂前皃女小，绕庭团扇扑帘衣。"]},{"t":"过冯子和新亭次答","f":"七言律诗","c":["松筠手种待成阴，高士常怀出世心。","正望蛟龙作霖雨，肯容麋鹿恋丰林。","花烟拂座扶春醉，萝月窥帘伴夜吟。","惭愧西台尘土客，偶来何解抱清琴。"]},{"t":"池上有怀张水部","f":"七言律诗","c":["江涛渺渺暮云阴，南去轻帆怅客心。","雀舫暂停开省阁，骊珠频出动词林。","芝兰并秀参差见，黄鸟相求上下吟。","永日临池空洗耳，迢遥难近子牙琴。"]},{"t":"雨后池亭偶坐","f":"七言律诗","c":["雨过回塘新水平，镜轮圆印碧天明。","贪鱼属玉浑忘去，抱叶蜻蜓忽自惊。","吟处爱当芳树立，兴来思荡小舟行。","台中饱食惭无补，不及垂纶称野情。"]},{"t":"六月六日大雨用前韵","f":"七言绝句","c":["六月六日雨如注，绕庭悬溜决清渠。","不是太阳相避却，祗应知我腹无书。"]},{"t":"古城寺山与东皋公晚酌","f":"五言律诗","c":["寺古仍临水，灯明更泛卮。","共怀临海作，重对白头时。","往事浮云变，生平皎日知。","殷勤家国语，不记下山迟。"]},{"t":"赠润夫黄门","f":"五言律诗","c":["昔爱仁人政，今传直谏名。","采衣归暂乐，青琐贵非荣。","门阀灵椿茂，才华汉水清。","论交千载上，吾愿取西京。"]},{"t":"仰止吟为黎师召兵侍作","f":"古风","c":["眼中磥砢万文峰，俨立大贤为世宗。","丈夫有灵塞天地，肯不拔地争巃嵷。","朝亦一仰止，夕亦一仰止。","平生积小以高大，巍乎山哉何愧尔。","呜呼武公九十犹勉㫋，愿献他日攻玉篇。"]},{"t":"南江吟为孙从一按察作 其一","f":"七言绝句","c":["汉水东流散百湖，家家悬镜写菰蒲。","锦袍独坐扁舟去，月里垂竿钓鳜鲈。"]},{"t":"南江吟为孙从一按察作 其二","f":"七言绝句","c":["承天楼阁似京华，江上人烟簇锦花。","直到东头高柳里，孤撑草阁伴渔家。"]},{"t":"南江吟为孙从一按察作 其三","f":"七言绝句","c":["汉江龙起万方清，旧渚何殊兴庆名。","使君家在新丰社，长沐枌榆雨露荣。"]},{"t":"南江吟为孙从一按察作 其四","f":"七言绝句","c":["文武遗风江汉流，水滨游女绝思求。","观风今值黄虞世，唯见溪翁击壤游。"]},{"t":"南江吟为孙从一按察作 其五","f":"七言绝句","c":["入郢雄心笑子胥，仲尼书社总成虚。","不如载取中山酒，来就江心丙穴鱼。"]},{"t":"南江吟为孙从一按察作 其六","f":"七言绝句","c":["四面方城开楚都，凭将汉水壮雄图。","神灵一统归今代，散与高人作五湖。"]},{"t":"南江吟为孙从一按察作 其七","f":"七言绝句","c":["西上襄阳百里程，摇船买酒醉樊城。","接䍦堕却无心拾，杜预碑犹水底横。"]},{"t":"南江吟为孙从一按察作 其八","f":"七言绝句","c":["我爱前贤太白豪，欲呼此水变春醪。","四海清平身不老，与君终日醉蒲萄。"]},{"t":"南江吟为孙从一按察作 其九","f":"七言绝句","c":["洪波吞却内方山，大别都来一掌间。","伏腊移舟祠大禹，鱼龙窟里棹歌还。"]},{"t":"南江吟为孙从一按察作 其十","f":"七言绝句","c":["我泛南江望汉阳，碧波千顷浩汪洋。","使君度量元相似，何物艨艟不可藏。"]},{"t":"江雨","f":"五言绝句","c":["江流愁太溢，更遣雨添波。","气逐阴阳变，天公奈尔何。"]},{"t":"寄梁俭庵罢司徒归乡","f":"七言律诗","c":["诏下天门许罢官，明王亲赐老臣安。","十年大计黄金贱，六省清风白日寒。","直道功名元自得，野人征税复谁宽。","东门瓜地相邻并，欲拟投簪续旧欢。"]},{"t":"寄唐渔石司寇赐告归养","f":"七言律诗","c":["横玉纡朱八座身，重闱列鼎百年亲。","君王孝理先三事，司寇高风动万人。","平法正资于定国，陈情偏奈范纯仁。","中堂问寝馀清夜，还向深山礼北辰。"]},{"t":"汉江独汎 其一","f":"七言绝句","c":["水云蒸日楚天浮，满眼江湖伴客愁。","三国雄豪何处问，捲帘犹自见荆州。"]},{"t":"汉江独汎 其二","f":"七言绝句","c":["郑生风骨岂超尘，水府能逢解佩人。","青鸟去来烟漠漠，渚兰汀芷自含颦。"]},{"t":"汉江独汎 其三","f":"七言绝句","c":["三日楼船听棹歌，江湖归兴满渔蓑。","功无铜柱长为客，浪笑壶头马伏波。"]},{"t":"汉江独汎 其四","f":"七言绝句","c":["郢城遥向武昌还，千里风帆三日间。","直到汉阳聊舣棹，推篷先措八分山。"]},{"t":"所见 其一","f":"七言绝句","c":["襄河西溃水连天，禾黍翻成鱼鳖渊。","鬻却儿童脩网罟，移家江口就渔船。"]},{"t":"所见 其二","f":"七言绝句","c":["贾客牵船入郢遥，泥行千里水齐腰。","青楼锦瑟谁家子，一醉挥金太剧骄。"]},{"t":"所见 其三","f":"七言绝句","c":["鬼薪白粲动成群，刀笔铦锋自舞文。","郑国不缘诛邓析，孙侨黑白讵能分。"]},{"t":"蝶恋花 巴陵山行","f":"古风","c":["秋色那知行近远。","翠竹丹榆，递换撩人眼。","导骑才随山麓转。","渔舟又渡溪流浅。","数过奇峰千万点。","野兴疏狂，转逗身轻健。","悬崖绝涧皆平坦。","寰中只奈人心险。"]},{"t":"蓦山溪 平江马上","f":"古风","c":["肩舆谢却，旷野独鞭骢马。","县令小家，风似道、桥翁疏野。","笑渠岂解，潇洒念本来，旧面目，无虚假，不在官高下。","当年庾亮，玩月荆州夜。","酾酒向江楼，顾官属、与之同把。","而今遥想，此老兴飘飘，风流尽，堪模写，莫对时人话。"]},{"t":"潇湘逢故人慢 过浏阳石洞岭","f":"古风","c":["山城晓发，正初阳微暖，宿雾方消。","林涧路迢遥。","爱云峰翠滴，霜叶红烧。","旌旗宛转，又何知、步入丹霄。","回望处、江湖满地，不禁烟浪滔滔。","村墟远，几家烟火道迩来，闾阎生计萧条。","试说向当朝。","正海晏河清，雨顺风调。","知他甚事，掇薪火、漫燎鬓毛焦。","且休谈、观风设教，烦公少损征徭。"]},{"t":"望江南 离思","f":"古风","c":["澄江水，别后几回潮。","黄鹤笛声愁里咽，青龙山色梦中遥。","秋空正泬寥。","记来时，杨柳暗河桥。","箫鼓临风喧祖帐，旌旗和月引征轺。","离愁何日销。"]},{"t":"如梦令 晓行","f":"古风","c":["红日海东乍吐。","消尽千山宿雾。","无数暗栖鸦，历乱林梢飞去。","安步。","安步。","锦石碧沙江路。"]},{"t":"满庭芳 见村社","f":"古风","c":["黄菊摧残，霜寒云冷，村墟别有风情。","白蘋红蓼，相映水痕清。","且喜时和盗息，是人家、仓廪丰盈。","击社鼓，迎神答愿，儿女笑歌声。","茅堂开浊酒，橙苞剖密，芋乳堆璚。","任相逢，简礼烂醉呼名。","爱杀人间真乐，休打算、宪府神京。","推恩念，几时酬却，归伴草堂灵。"]},{"t":"水龙吟 见水田乐之","f":"古风","c":["潺潺碧涧归田，山人自识山家趣。","开春阳动，土膏融暖，便脩农务。","黄犊翻泥，青秧刺水，爱逢时雨。","但完官两税，供家八口，万事何、思何虑。","细数古来豪杰。","犁锄边、尽多乐处。","伊尹深耕，孔明薄种，甚生出处。","江左夷吾，终南捷径，岂堪俦侣。","判穷达由天，卷舒在我，證却此、生公据。"]},{"t":"烛影摇红 攸县山行遇雨","f":"古风","c":["微雨空濛，青山一带如烟隔。","绿杨霜后正凋枯，特地蒙恩泽。","野草何知喜悦。","谓春转、江湘二月。","冻云覆水，朔吹鸣条，较来还别。","仄径游泥，马蹄滑处频蹉跌。","天时人事好商量，合变峰头雪。","大地园林寒彻。","尽飞起、滕王蛱蝶。","衡山南去，报个丰年，腊前三白。"]},{"t":"疏帘淡月 攸县冬至风雨","f":"古风","c":["深沈台院，独自在他乡，怕逢佳节。","春尽离家忽地，一阳时月。","雁书不到衡阳外，盼关山、几多重叠。","满城寒雨，一庭衰草，助人愁切。","想儿女、家园欢笑，道而翁拥旄，持节体国。","勤民揭天勋业。","吾衰不似当年矣，对大川、怅无舟楫。","竹篱茅舍，不如归去，当家温热。"]},{"t":"如梦令 雨怀","f":"古风","c":["夜静猛风将雨。","落尽紫榆千树。","行客忆江南，渺渺碧天穷处。","无绪。","无绪。","独与寒灯宾主。"]},{"t":"少年游 念往","f":"古风","c":["南山豆陇，东门瓜地，天与十年间。","傍水栽松，向风调鹤，俗事了无关。","东君送上观风驾，逗留几时还。","薄暮浮云，清宵明月，目断过江山。"]},{"t":"忆秦娥 旅思","f":"古风","c":["王程迫。","旌旗催度金陵陌。","金陵陌。","一番回首，一番头白。","飞篷远逐天涯客。","江梅又报年华隔。","年华隔。","莫教孤负，旧京春色。"]},{"t":"长相思 同前","f":"古风","c":["山花香。","水花香。","宛转湖南官路长。","怕见早梅芳。","愁三湘。","度三湘。","烟水无边是此方。","登楼堪断肠。"]},{"t":"玉烛新 寄俞鲁用","f":"古风","c":["飘飘黄绶客。","向溟海东边，参陪凫舄。","从来短簿，非凡事、认取凤凰毛翮。","春秋满腹，舌澜翻曾倾词席。","数斗后、豪气凌云，看舞玉龙三尺。","今栖枳棘丛中，且奔走风尘，奉行条格。","丈夫舒卷。","随时耳、聊布苍生膏泽。","鸡群野鹤。","当自有知音求索。","从容展、经济雄才，治安长策。"]},{"t":"渡江云 寄徐君叙","f":"古风","c":["葛巾新折角，道衣儒履，谁识旧王孙。","帝城高隐处，寂静槐庭，碧柳暗朱门。","鸿儒上客，长不断、载酒论文。","尽永日、调琴对局，生怕鼓钟喧。","堪惭。","一身潦倒，两世攀援，但柴车每造。","桂亭深、醉来自散，坐久忘言。","春风一别江门路，剧相思、最是黄昏。","更无奈、楚山暮雨啼猿。"]},{"t":"过秦楼 寄王子新","f":"古风","c":["虎卧天门，龙腾凤阙，书法王家元妙。","画烂衣襟，磨乾池水，透得旧来关窍。","更狂僧醉圣，探奇掇隽，纵横颠倒。","爱青年方盛，高名歘起，万人称好。","叹拙手勉强挑戈，依稀拨镫那识，就中天巧。","欲取金丹，并携洛赋，子细从君论讨。","只恐挥毫，迟留迅疾，肘腕不禁衰老。","判千金买纸如山，倩渠长扫。"]},{"t":"虞美人 自嘲","f":"古风","c":["少日功名蹉跌过。","老去还将那。","楚台风采竟如何。","堪恨笔端无力、挽颓波。","澄清四海男儿事。","李范今谁是。","曾看舞袖笑郎当。","请公当筵自问、短和长。"]},{"t":"谒金门 雨声","f":"古风","c":["声滴滴。","似近小窗偏急。","独客羁怀正愁寂。","谢君撺断力。","夜静颠风寥历。","飒飒几番如织。","家远长凭归梦觅。","此宵归未得。"]},{"t":"苏幕遮 晚行","f":"古风","c":["日西沈，寒又作。","掠面斜风，欺负征袍薄。","远近村墟烟漠漠。","宿鸟归林，何事閒喧聒。","算归期，无定着。","腊尽春回，客意偏寥落。","向老重教名利缚。","雪月风花，白地成担搁。"]},{"t":"倦寻芳慢 书怀","f":"古风","c":["閒穷往古，万变荣枯，总归无有。","乐善安常，本是自家操守。","马革功名蕉覆鹿，麟台画像刍成狗。","太虚中，看彩云浊雾，谁工谁丑。","堪笑杀、子兰谮毁，廉蔺交欢，枉多生受。","坎止流行，物理本无纷糅。","天日清和聊散步，风波变动须回首。","牢把定，此心中外，一生前后。"]},{"t":"花犯 冒雾往郴","f":"古风","c":["晓鸡鸣，登车就道，残星尚明灭。","水雾山云，偷晓弄阴晴，四望凝结。","太阳高起青天上，有光难下彻。","更莫论、奇峰佳树，一槩浑遮隔。","阳回时候想南园，绿草意欣欣，思换春色。","愿净扫，昏霾满、地飞蝴蝶。","喜行客、身躯粗拙，请毒瘴、蛮烟休见嚇。","三饭外、清心寡欲，任尔天寒热。"]},{"t":"兰陵王 武冈春晴","f":"古风","c":["晴光好。","正映李花秾缟。","连朝怪，山雨林风，适与东皇助工巧。","染垂杨野草，布满青青行道。","升平世，遍五岭三湘，处处韶华动欢笑。","谁家儿女闹。","竞院落秋千，彩绳飞袅。","江南此景知多少。","轻风南陌上，宝马穿花，金龟换酒恣颠倒。","祗愁城闭早。","烦恼。","想当日，拉酒伴诗朋，着意寻讨。","青鞋踏遍閒亭沼。","自背却乡井，一齐都扫。","商量出处谁胜，休只恋旌纛。"]},{"t":"白苧 浴起","f":"古风","c":["浴兰汤，起坐向，芝房桂室。","薰蒸百体，顿觉形神和适。","视盘铭、警戒安能及。","且落。","得清泉，疏瀹尽三冬垢积。","聊抖擞白袷单衣，更换着、飞云旧舄。","焚香静憩，相与澄观定息。","量浴沂、此怀能几人窥测。","堪惜。","灵均作赋，谢客传图，火风假合，妄比金身玉质。","岂解识虚空，来去消息。","神奇臭腐，从何生五蕴，翻腾声色。","古有形骸，土木嵇康，让他知得。","更羡庄生，直认身为客。"]},{"t":"减字木兰花 春画二首 其一","f":"古风","c":["绿阴亭沼。","天南二月春归早。","起觅残红。","万点随风西复东。","檐牙乳雀。","啄破苔花新试角。","柳外黄鹂。","欲弄新声不住飞。"]},{"t":"减字木兰花 春画二首 其二","f":"古风","c":["柔萱如带。","轻风粉蝶狂无奈。","院静人间。","坐数行云度远山。","惊心节序。","满庭忽见吹飞絮。","莫忆家乡。","碧水无情千里长。"]},{"t":"瑞龙吟 辰溪舟行","f":"古风","c":["辰溪水，想是银汉分流，桃源旧沚。","楚中胜槩奇观，潇湘云梦，参差难比。","峰峦美。","可信舟移天上，人行图里。","稍经蕙浦兰汀，忽惹閒鸥，一双飞起。","曾访苏公赤壁，柳侯黄庙，而今荒矣。","岂似万丈丹梯，千重云垒。","天翻地覆，紫翠无成毁。","试捲起、疏帘危坐，游丝飞絮，亦为春风喜。","清明两岸开桃李。","戏作穿花士。","笑伏波衰萎。","向门生哀咏，自伤边鄙。"]},{"t":"眼儿媚 舟雨","f":"古风","c":["逍遥老子怕閒愁。","冒雨荡孤舟。","烟开柳岸，风生桃浪，人渡兰洲。","青山万点分浓淡，云气学波流。","倚窗无事，吟残飞燕，数遍眠鸥。"]},{"t":"蝶恋花 舟雨","f":"古风","c":["画舫轻摇风外橹。","带雨声微，乍似新莺语。","午梦遥随江燕去。","醒来尚绕青枫浦。","羁游枉却流年度。","故国桃花，落尽长松坞。","载酒何人来扣户。","残红踏遍亭前土。"]},{"t":"菩萨蛮 舟雨二首 其一","f":"古风","c":["青山雨洗精神出。","趁得帘开飞送入。","鸂?逞毛衣。","船来故不飞。","落絮生萍叶。","水面留轻蝶。","沿溪菜吐花。","池塘鸣乱蛙。"]},{"t":"菩萨蛮 舟雨二首 其二","f":"古风","c":["溪行五日逢城郭。","耳静愁闻喧鼓角。","到岸喜新晴。","登台却趁情。","杜宇无幽绪。","唤得春归去。","春归了不关。","花开元耐看。"]},{"t":"寄和三弟舜玉六十自寿 其一","f":"七言律诗","c":["壶头空老伏波公，款段乡园羡尔雄。","隐者风流高物外，诞辰家庆正天中。","身强阅世初称寿，诗好逢人不讳穷。","俯仰乾坤俱白发，趋庭犹记两儿童。"]},{"t":"寄和三弟舜玉六十自寿 其二","f":"七言律诗","c":["紫气青牛远度关，华阳近在秣陵间。","久怀松坞同烧药，且喜丹砂已驻颜。","脩竹林深春酒缘，棠花楼晚布衾斑。","优游群从追欢地，应笑衰翁独未閒。"]},{"t":"寄和三弟舜玉六十自寿 其三","f":"七言律诗","c":["閒身爱向醉乡眠，百亩唯营种秫田。","尽有莺花娱胜日，不须牛酒赐高年。","园开涉趣常携客，志在逃名莫问天。","王衍元憎阿堵物，床前聊免积馀钱。"]},{"t":"寄和三弟舜玉六十自寿 其四","f":"七言律诗","c":["鸿宝传来石枕函，悬壶久矣脱尘凡。","紫霞自酿山中酒，青鸟时通海上缄。","万事虚舟何解怒，一官腐鼠不生惭。","吾今苦忆林泉好，为剪秋荷制短衫。"]},{"t":"雨过","f":"五言律诗","c":["风雨秋随至，园林气一苏。","院凉蛩独语，巢晚鹊相呼。","客意疏团扇，山光近酒壶。","满庭飘落叶，能不忆莼鲈。"]},{"t":"寄七弟瑮","f":"五言古诗","c":["士龙富文薮，子由蓄词锋。","平生伯仲间，敛手让精工。","世人贵齿发，恣口妄雌雄。","矧兹盛德士，乃示外愚蒙。","吾家惠连氏，马群一蛟龙。","浩气腾虹霓，耻随蛇与虫。","仕宦十五载，囊橐唯屡空。","吐论忤当路，拂衣甘困穷。","悬室无儋石，反关卧雪中。","插架十万轴，伊吟日填胸。","下笔掩前古，只字无雷同。","金玉苦珍秘，四海虚承风。","饭糗似黔娄，嗜酒非扬雄。","太息天壤间，何人测深衷。"]},{"t":"赠文徵仲","f":"五言古诗","c":["志士厉高节，夫君狷者流。","举足唯大道，邪径焉肯由。","田仁甫弱冠，却赙矜清脩。","元城寡内欲，亦自既壮秋。","掩面过行女，闭门拒王侯。","天然冰玉操，不与思虑谋。","师资快吾党，少长咸低头。","五车聚腹笥，发咏崇温柔。","鲜云澹华泽，美玉辞雕锼。","待诏入金马，玩世存薄游。","脱冠挂神武，遂返莼鲈舟。","颐神击磬室，放歌埋剑丘。","掉笔弄图画，尽掩松雪俦。","乃惊铁石肠，遗韵仍绸缪。","伯阳信龙物，变化不可求。"]},{"t":"赠蔡九达","f":"五言古诗","c":["文章有神秀，譬彼造物宰。","变发云霞章，焕为日星采。","自非研精人，妙解讵能逮。","糟粕莽成苴，疮疣祗增痗。","蔡君事钻攻，搦管四十载。","攀危屡登天，会极已归海。","谓兹耀烂间，乃有黯者在。","玄珠得罔象，至味失鼎鼐。","翻然恣挥洒，涂辙忽而改。","天机互奔凑，神化绝需待。","有灵驱万象，无色备五彩。","遂使郊岛徒，总获刻薄罪。","蹇予离群久，索居益荒猥。","日诵林屋编，充然慰饥馁。"]},{"t":"和荅冯三石劝其此上二首 其一","f":"五言律诗","c":["勿薄淮阳守，家居竟隔年。","颇闻宣室召，将起贾生贤。","郡政冰霜体，词林锦绣篇。","青云公望远，玄发万人怜。"]},{"t":"和荅冯三石劝其此上二首 其二","f":"五言律诗","c":["金玉千钧价，人间有至公。","仁心多政拙，直道岂诗穷。","入相需黄霸，推贤愧郑崇。","虞廷车服宠，明试待论功。"]},{"t":"邵前川纳妾","f":"七言律诗","c":["灿烂衾裯展洞房，双星秋夜渡河梁。","玉台固是老奴物，金屋雅宜娇女妆。","云发绕鬟光可鉴，蚌珠归梦兆应祥。","华筵汤饼休偏我，已办犀钱贺弄璋。"]},{"t":"赠陈行人邦脩","f":"五言古诗","c":["末俗滥文词，华盛本先拨。","宁知昭苏化，本自渊静达。","二曜天地精，沈晦乃真括。","向使恒照临，光应有时夺。","陈君起天南，理性早疏豁。","探玄自太始，析微辨毫末。","阎浮烦恼障，勇猛归一喝。","乃知英明人，灵根本来活。","楚台三日谈，泠泠慰饥渴。","情缘多纠缠，慧剑资剸割。","学道岂在年，所贵知解脱。"]},{"t":"谏议润夫使君自应城数百里访余武昌适值中秋风雨大作且公私见夺不克夜叙殊负良晤明日送于黄鹤楼匆匆别去意所难尽缀以短诗","f":"五言古诗","c":["隔面倏十载，枉寻适中秋。","况临江汉渚，聚兹黄鹤楼。","明月好负人，光暗鹦鹉洲。","凄然作风雨，翻为别离谋。","携樽晓出饯，挂帆且须留。","缱绻故旧情，隐轸江湖忧。","同心语难竟，何啻胶漆投。","君行侍青琐，献替匡宸旒。","云霄树鸿业，映楚诸前修。","吾衰忆林壑，旦夕归狐丘。","进酒莫拒满，后会良悠悠。"]},{"t":"赠沈君华甫赴常州别驾故南京人","f":"七言律诗","c":["武昌二沈推难弟，别驾毗陵岂足多。","千里分符看制锦，万言挥笔诧悬河。","王畿密迩官仍贵，民力东南困若何。","经过故都寻往迹，应招耆旧一长歌。"]},{"t":"赠苏州节推陈君天祐赴任","f":"五言律诗","c":["星文高执法，地望切专城。","司马家风峻，王畿宦籍荣。","吴都包海阔，震泽际天清。","此去悬霜月，偏临万户明。"]},{"t":"秋日同总镇二公饮黄鹤楼三首 其一","f":"七言律诗","c":["虎帐同分圣主忧，时平聊共赋高秋。","江经神禹多平土，山去仙人有故楼。","风起鱼龙还自骇，醉来弦管欲生愁。","亭前石镜知何在，明月依然照白头。"]},{"t":"秋日同总镇二公饮黄鹤楼三首 其二","f":"七言律诗","c":["高楼骋望楚天宽，千古閒情一倚阑。","黄孟史家称最孝，孙刘王业恨偏安。","休怜往事成翻掌，且对秋风一正冠。","说与幽人应愧杀，渔歌遥起蓼花滩。"]},{"t":"秋日同总镇二公饮黄鹤楼三首 其三","f":"七言律诗","c":["楼前野色散秋容，楼下浮烟晚更浓。","江汉水深龙窟宅，衡庐天远楚提封。","蒹葭白露愁归客，禾黍黄云慰老农。","宾从满筵笳鼓急，庾公那得任疏慵。"]},{"t":"朱侍御子宜别山亭","f":"五言古诗","c":["高人厌嚣閧，结搆临幽深。","井络仅尺咫，窈然得山林。","江清动城表，竹密罗庭阴。","风籁浣尘听，野容延赏心。","上奉白发欢，春酒时开襟。","下偕连枝乐，埙篪和且湛。","闭阁复晏坐，累遣虑已沉。","漱齿诵玄书，焚香挥玉琴。","冥鸿渺天末，悠悠遗我音。"]},{"t":"汉川道中六言二首次郭雨山中丞屏间韵 其一","f":"古风","c":["空林残照啼鸦，远水寒烟飞鹜。","春风何日归来，吹煖野田茅屋。"]},{"t":"汉川道中六言二首次郭雨山中丞屏间韵 其二","f":"古风","c":["绿橘霜寒已熟，黄花岁晚初香。","可惜山人野兴，不逢故里秋光。"]},{"t":"应城晓发","f":"五言律诗","c":["秉烛通窗暗，披衣起漏残。","乌啼台树晓，蛩咽井芜寒。","向老嗟行役，为官愧素餐。","循良求不易，冻馁待谁安。"]},{"t":"景陵五华山","f":"七言绝句","c":["五华山顶炼丹台，方士虚传太皞开。","未悟先天真水火，却依炉鼎拨残灰。"]},{"t":"吊司成鲁公振之已有园 其一","f":"七言绝句","c":["郢水秋风入草堂，仙人归去白云乡。","莎衣芒履难重遇，唯有中林橘柚香。"]},{"t":"吊司成鲁公振之已有园 其二","f":"七言绝句","c":["苍凫散尽水盈洲，白鹤那因陇稻留。","两两凤雏毛五色，背人常自宿丹邱。"]},{"t":"野田见菊","f":"七言绝句","c":["陶令柴桑菊满阑，得钱呼酒每盘桓。","熊轓虎节成何事，却引黄花道上看。"]},{"t":"沔阳湖滨","f":"五言律诗","c":["苍菼暗湖云，长杨夹径分。","风晴宜蝶性，水断失鸥群。","举目堪垂钓，劳生漫学文。","钟山旧猿鹤，应笑老徵君。"]},{"t":"赠北村路中丞赴晋阳","f":"五言古诗","c":["路公廊庙器，特达瑩圭璋。","学道出邹鲁，雕文陋班扬。","举政必王道，岂随俗士行。","手挈万黔首，盎然履虞唐。","初提北门钥，燕冀尘不扬。","再拥南邓麾，按堵清四疆。","天子爱雄才，三命迁晋阳。","譬如大旱雨，所至民悦康。","韩范在边重，何如立朝堂。","谋国有深意，中外非公量。"]},{"t":"议修沔阳堤垸览童司成士畴河防志示官吏","f":"五言古诗","c":["汉沔古沃壤，凋残慨今兹。","禹书竟谁修，洚水仍尧时。","鳞鳞烟火居，化为鱼鳖池。","惰吏诿天运，素餐寂无施。","我行践淤泽，流亡痛仳㒧。","兴言乘橇绩，永叹涕泪滋。","载考太史编，河防炯然垂。","伟哉维扬守，长疏列安危。","屯膏罔终惠，徒劳叫天墀。","感之起中夜，墨檄纷四驰。","版锸及冬举，贵不病农时。","丁宁戒群吏，开岁期耘耔。","匪躬乃臣职，勿间灾祥疑。"]},{"t":"又别北村","f":"五言古诗","c":["结交三十载，会面苦不易。","相逢郧楚间，复判三晋辔。","昔见犹朱颜，今并黄发次。","唯公展经纶，麟凤见灵异。","神化俟丹青，台鼎有馀地。","蹇余耕牧身，中台本非位。","倚玉联旌麾，日抱鳏旷愧。","终当乞骸归，初服返荷芰。","愿公加餐饭，力任天下事。"]},{"t":"垂泪一首","f":"七言律诗","c":["十月南湖水拍天，屋庐漂尽少人烟。","河防不救柴林院，王赋谁蠲汉上田。","疏排后代无神禹，生息何方有计然。","衰老空垂忧国泪，几曾恩惠及颠连。"]},{"t":"行汉水堤上大似秦淮风景因念俞鲁用之亡","f":"七言绝句","c":["汉江江上玩晴波，恰似秦淮月下过。","归去扁舟载箫管，谁人复唱采莲歌。"]},{"t":"望湖滨红蓼甚丽","f":"七言绝句","c":["湖外秋容淡晚霞，桃源何处泛来花。","西风也自嫌寥落，点缀芳菲付水涯。"]},{"t":"湖滨作","f":"七言律诗","c":["雾渚烟汀散客愁，江南佳丽梦中游。","群飞白鹭浑翻雪，翠滴垂杨不受秋。","凶岁萧条伤稼穑，野情摇曳傍渔舟。","年年负却莼鲈约，岂为人间斗米谋。"]},{"t":"汉沔诸湖二首 其一","f":"五言古诗","c":["神禹导江流，东归入沧海。","三澨阻大别，旷壤实潴汇。","鬻熊开荆疆，纵猎固斯在。","坤舆获所安，流峙各无改。","云胡后代人，邑聚擅高垲。","曲防破先制，鱼鳖遭俎醢。","履亩料租庸，妄言广财贿。","籍定牢弗刊，始重黔首痗。","水至循故区，往往归岁罪。","岂知小智私，祗以增冻馁。","何当铲纵横，一洗谢真宰。"]},{"t":"汉沔诸湖二首 其二","f":"五言古诗","c":["大哉云梦泽，浩荡吞荆襄。","分为百湖陂，委折各有防。","水阔混云日，鱼多聚鹙鸧。","天寒见洲渚，网罟映地张。","扁舟垂纶叟，楚歌乐洋洋。","昔闻汉阴老，无乃斯人行。","西伯苟不遇，六韬沉渭阳。"]},{"t":"赠水部张诚之采木南楚有功擢山东宪副","f":"五言古诗","c":["圣王御六合，孝敬百礼崇。","祠坛及寝殿，如天开法宫。","大木出南楚，肃诏腾雷风。","层厓伐梓楠，斧声震高穹。","万牛痏肩领，巨筏亘长虹。","山灵献材异，波侯开道通。","贤哉张使君，来秉玉节雄。","岂不念王事，而哀切民穷。","献谋广财用，厚直来商工。","优优播慈令，蹇蹇竭匪躬。","譬如求才俊，杰者必登庸。","梁栋入内苑，巀嶪起天中。","巍然睹巨丽，伟绩归司空。","落成大庆赉，锡命先有功。","曰君冰玉操，风纪责所隆。","煌煌獬豸衣，执宪山之东。","授官副雅望，万口称嘉同。","青云快翔翥，展翼随鹓鸿。","台斗岂足践，令誉歌永终。"]},{"t":"沙阳晓渡","f":"五言律诗","c":["水阔残星小，汀寒宿雾沈。","马声喧橹乱，灯影照江深。","汉沔非吾土，风霜滞客心。","驱驰何敢惮，筋力尔须任。"]},{"t":"马上见霜","f":"七言律诗","c":["十月繁霜满原草，汉南柳枝犹自青。","长路独怜尘滚滚，老人休怪鬓星星。","从来沙苑皆骐骥，何处松根少茯苓。","终岁簿书催物役，几时还续太玄经。"]},{"t":"小江口","f":"五言律诗","c":["汉水霜前落，微波一苇通。","沙然红蓼色，岸袅白茅风。","兴在烟霏际，年销马迹中。","浮云休蔽目，流盻送归鸿。"]},{"t":"落日过白鹤寺山僧邀读元将破宋碑","f":"七言绝句","c":["慨息元军破宋诗，老僧邀请读残碑。","山中竹院堪幽赏，无奈斜阳欲下时。"]},{"t":"饭旧口","f":"七言绝句","c":["霜舟乍渡沙阳水，午饭仍趋旧口烟。","楚国山川行欲遍，祗凭诗兴送流年。"]},{"t":"登阳春台","f":"五言古诗","c":["楚客歌阳春，和者才数人。","调高少知己，绝德难为邻。","荒台满碧草，四顾伤我神。","不知当年士，果为何国宾。","慷慨三闾子，离骚风雅陈。","明明君臣义，照耀天地新。","斯人虽沉湘，万古仰芳尘。","荒哉高唐赋，淫哇何足珍。","与君登高台，瞻望郢城树。","龙飞登九天，故宫莽云雾。","日月相蔽亏，江湖各奔注。","优游丰沛间，父老日歌舞。","先皇流仁风，桥陵万神护。","蛟龙缠穹碑，金字勒长赋。","草木藉华滋，新冬岂寒冱。","唯兹盘石崇，乾坤永同固。","徘徊咏丰芑，日暮更延伫。"]},{"t":"与王司礼焘马司谏汝彰卢氏园宴坐言别","f":"五言古诗","c":["台居倦文牒，野步惬园田。","既偕金宫彦，复招青琐贤。","旅泛暂聚合，心赏相夤缘。","疏罗罥高壁，密竹媚清涟。","岁晏众芳歇，时菊亦解颜。","共伤节序改，况轸别念牵。","去任殊道路，南北间山川。","引觞竞浮白，临乐恶繁弦。","感此羁游情，慨余薄暮年。","终当解龟组，农圃安自然。"]},{"t":"郢中对雪十月二十二日","f":"五言古诗","c":["我游郢中地，孟冬风凄凄。","不闻白雪曲，徒见白雪飞。","羁旅节忽改，自顾寒无衣。","四境遭水潦，黔首况啼饥。","帑廪率空匮，漂荡靡托栖。","政理属舒卷，咎责果安归。","将反牛羊牧，俛焉歌式微。"]},{"t":"哭陈石亭","f":"五言古诗","c":["吴楚天一方，书至每不易。","哀鸿从东来，属我墓间志。","痛哭裂肝肠，天道乃乖戾。","平生金石交，中心两无异。","公今弃我去，如丧左右臂。","哀哉遂初堂，庭树日憔悴。","他时一杯酒，空洒林下泪。"]},{"t":"哭徐九峰","f":"五言古诗","c":["宇宙同一寓，死者为过客。","公年岂不高，痛惜如夭折。","乡国信多才，雅道洞明哲。","古篆今不存，高辞难再得。","吾生有幽抱，出户谁与说。","不闻子期亡，伯牙弦遂绝。","知音古来重，日月增哽咽。"]},{"t":"哭金子有","f":"五言古诗","c":["后来骐骥群，金生千里驹。","云衢虽未骋，剪剔毛骨殊。","一经发乡荐，俊气盖九区。","穆穆孝友姿，允为邦国模。","造物常忌才，玉树望秋枯。","颜渊竟短命，黄宪乃先殂。","异地空泣血，何由奠生刍。"]},{"t":"黎司空山堂对雪","f":"七言律诗","c":["高筵对雪多清兴，况复江天落草堂。","漠漠冻云低野树，霏霏风絮过山墙。","寒疑点缀侵帘影，坐判虚明映烛光。","莫怪夜深吟不就，旧歌元让郢人强。"]},{"t":"过云台山闻山中有普明寺未至","f":"七言绝句","c":["云台路接短长亭，十里烟林不断青。","说有禅宫如海藏，山僧来现老龙形。"]},{"t":"丰乐河","f":"七言绝句","c":["丰乐河边杨柳疏，半黄浑似早春初。","晴风不著行人面，欲问桃花开也无。"]},{"t":"黄宪墓","f":"五言古诗","c":["尔年昔不永，尔墓今犹存。","英英弱冠子，谁遽探清浑。","广哉郭有道，成美由片言。"]},{"t":"淳于髡墓","f":"五言古诗","c":["笼鹄诚谲诞，斗酒亦颠狂。","谈言虽微中，滑稽令人伤。","不如鬼谷子，默默能深藏。"]},{"t":"马上忆曩在全州送孟望之归汝有襄阳骑马之句今亡久矣长途独暮凄然沾襟","f":"七言绝句","c":["湘国题诗赠使君，襄阳归马踏归云。","垂鞭此日斜阳道，泪雨遥凝汝水坟。"]},{"t":"入襄阳 其一","f":"七言绝句","c":["黄龙山北树含烟，白马亭东水拍天。","传道樊城风景好，酒家楼阁镜中悬。"]},{"t":"入襄阳 其二","f":"七言绝句","c":["庞公爱就鹿门居，孟子愁封北阙书。","此地高人多隐德，青山应笑碧油车。"]},{"t":"大堤曲","f":"五言古诗","c":["大堤多美女，颜色春花殊。","逢人解巧笑，但笑秦罗敷。","传道楚王宫，细腰金屋中。","自甘馁为鬼，争效体如风。","大贾千黄金，买面不买心。","东家登墙者，绣履蹋罗衾。","婀娜堕马妆，谁言近不祥。","客性喜逐臭，唯誇鲍最芳。","白石映寒冰，徒矜汉水清。","游鱼不肯住，空名何足荣。"]},{"t":"羊侯祠","f":"五言古诗","c":["叔子不鸩人，敌国亦信之。","赤心动金石，黔首岂相疑。","千秋堕泪者，何必见墓碑。"]},{"t":"习家池","f":"五言古诗","c":["山简游习池，长携葛强儿。","民牧多政理，倒载亦何为。","怪底彊仕年，不为家翁知。"]},{"t":"襄阳镇南楼","f":"七言律诗","c":["高楼特起镇南邦，城郭飞云度碧窗。","东流汉水声长绕，西踞郧山势总降。","望里封疆分汝邓，古来耆旧有诸庞。","吾衰不及秦公子，伟观浑无健笔扛。"]},{"t":"十一月二日自襄阳赴谷城将游太岳","f":"五言古诗","c":["晓出襄阳郭，暮投谷城徼。","地势益高衍，山形稍奔峭。","风霁云雾豁，残阳露微照。","天乎借良辰，人也谐宿好。","明登崒嵂间，千里骋遐眺。"]},{"t":"界山","f":"五言律诗","c":["山巘隔尘氛，入山皆碧云。","清涧饮猿父，白石起羊群。","物华暄寒异，世界人天分。","将邀东方子，同会上元君。"]},{"t":"入山","f":"七言律诗","c":["万山西来高武当，灵区物物非寻常。","溪边石黛转争碧，霜后草花犹自黄。","栖岩人共鸟鼠穴，行空马逐鹓鸿行。","不知王烈在何许，明朝可逢石髓尝。"]},{"t":"山行绝句十三首 其一","f":"五言绝句","c":["开户霜如雪，登车日胜春。","举目见千里，独慰游山人。"]},{"t":"山行绝句十三首 其二","f":"五言绝句","c":["天如碧玉版，群山各写形。","高空无障翳，龙凤互鶱腾。"]},{"t":"山行绝句十三首 其三","f":"五言绝句","c":["青山八百里，蟠结千蛟龙。","头角忽耸起，秀出云间峰。"]},{"t":"山行绝句十三首 其四","f":"五言绝句","c":["高低度岭频，清浅涉涧屡。","恐已入天宫，山空无人语。"]},{"t":"山行绝句十三首 其五","f":"五言绝句","c":["涧口架飞梁，山腰束微路。","悬厓有茅屋，尽是赍粮户。"]},{"t":"山行绝句十三首 其六","f":"五言绝句","c":["开山种云子，汲涧探乳泉。","可羡岩穴民，得养龟鹤年。"]},{"t":"山行绝句十三首 其七","f":"五言绝句","c":["山风一披拂，千林舞寒叶。","恍如艳阳时，花丛闹狂蝶。"]},{"t":"山行绝句十三首 其八","f":"五言绝句","c":["苍厓切云高，深涧万丈下。","低头听泉声，风雨号静夜。"]},{"t":"山行绝句十三首 其九","f":"五言绝句","c":["径踏云边石，衣飘树杪风。","绣鞍行一马，玉管引双童。"]},{"t":"山行绝句十三首 其十","f":"五言绝句","c":["胡然掠云起，忽尔落涧行。","幽丛不见底，潏潏闻水声。"]},{"t":"山行绝句十三首 其十一","f":"五言绝句","c":["涧道苍杉林，云寒白日阴。","石壁相映起，肃穆愁人心。"]},{"t":"山行绝句十三首 其十三","f":"五言绝句","c":["磈砢万石底，滴沥泉一泓。","裹茗欲煮尝，未有龙头铛。"]},{"t":"遇真宫","f":"五言古诗","c":["唐皇礼果老，汉帝延河公。","金门一遗步，玄圃渺烟鸿。","冥冥三仹子，轩圣慕其风。","使轺穷沧海，灵岳虚瑶宫。","青鸟竟不来，鼎湖恨何穷。"]},{"t":"玉虚岩","f":"五言古诗","c":["九渡越清涧，七盘转层厓。","高树落馀雪，阴壑青夏苔。","云龛举步险，风穴流音哀。","方隅问屡眩，昏旦候莫谐。","路尽益岑寂，俗驾何因来。"]},{"t":"题玉虚岩四句","f":"古风","c":["苍云抉肤，碧玉琢肋。","真宰运斤，成此仙宅。"]},{"t":"紫霄太子岩","f":"五言古诗","c":["王子炼神鼎，乃逃高岩居。","金银结真气，天人传玉书。","磨针悟志苦，插梅知化殊。","千乘虽云贵，九霄乐有馀。","长令电露子，怅望龙鸾车。"]},{"t":"南岩雷神洞","f":"五言古诗","c":["雷神栖何所，岩洞深杳冥。","幽林蔽日影，寒涧馀龙腥。","经年尚留雪，当午仍见星。","石奇出变相，境胜通神灵。","谲怪山海事，流传信前经。"]},{"t":"五龙宫","f":"五言律诗","c":["日出雪仍积，林深路不分。","行过千涧道，来谒五龙君。","仙人馀故宅，玉简空灵文。","对此烟雾窟，徒然惭垢氛。"]},{"t":"五龙隐仙岩","f":"五言古诗","c":["寻真极玄览，访古穷荒遐。","载凌青虚界，遥扣洪厓家。","往古列仙人，悉此炼丹砂。","经台照白日，石洞空桃花。","何时遂辟谷，漱齿来餐霞。"]},{"t":"登天柱峰次路北村院长旧韵","f":"七言律诗","c":["天柱峰高白日晴，华嵩相对最分明。","扶桑倒射东溟影，银汉平流上界声。","空里金宫陈帝座，云边铁锁度人行。","不缘旌节巡方岳，孤负尘埃过此生。"]},{"t":"进士蒋君养孚会余天柱峰下授宗伯公移","f":"七言律诗","c":["仙山高处幸逢君，缥缈宫袍五色云。","身到峰头金殿里，手持天上紫泥文。","诗成似有神灵助，境胜休传俗客闻。","好取姓名深篆刻，长令岩壑借清芬。"]},{"t":"赠蒋佥宪芝赴云南","f":"五言古诗","c":["爱言干将器，利刃能吹毛。","武昌盘错地，断割手不劳。","尽令十万家，同口兴歌谣。","我持行台政，舒惨赖所操。","岂唯逭罪咎，实已弘甄陶。","每思四域内，安得皆君曹。","如古元道州，独重工部褒。","天官论嘉绩，奏授獬豸袍。","乃不奠三楚，复秉滇南旄。","远人何足平，早愿归中朝。","别我郧襄野，徵言意忉忉。","行囊无所赠，独解王祥刀。"]},{"t":"郧洲晓发时已膺司寇之命二首 其一","f":"五言律诗","c":["解缆郧洲雾，开窗汉水清。","乱山舒野望，急浪快归程。","摇落岁华晚，驰驱使绩成。","东风何日至，弭棹石头城。"]},{"t":"郧洲晓发时已膺司寇之命二首 其二","f":"五言律诗","c":["天青江雾重，霜白石林疏。","官满抛公事，情閒悦道书。","试论麟节贵，何似鹿门居。","再过襄阳去，羞逢庞老锄。"]},{"t":"郧江张帆","f":"五言古诗","c":["两崖倚列障，一水中逶迤。","挂帆沿流行，日影互迁移。","石濑扬飞湍，风潭蹙文漪。","瞬息踰百里，长年岂知疲。","导舸角鸣乐，悠悠转朱旗。","游目恬野趣，浩荡忘前期。"]},{"t":"登岘首","f":"五言古诗","c":["岘首瞰长江，高深属遥睇。","两仪拓雄观，况值风日霁。","水浅别洲渚，林寒出松桂。","旷然洽今欢，遑以悼先逝。","羊公经世人，兴怀局千岁。","立德竟长泯，长闻泣遗惠。"]},{"t":"同路中丞登鹿门山颠","f":"五言古诗","c":["维舟访嘉隐，凌崄跻峻巅。","远水浮白日，叠岭霾苍烟。","庞公去已久，讵识躬耕田。","何功勒钟鼎，卒使高名传。","赫赫刘荆州，遗安让其贤。","此道今岂有，流尘暗弓旃。"]},{"t":"望隆中山","f":"五言古诗","c":["云山如龙蟠，紫气腾晴空。","缅想诸葛贤，引领望隆中。","间气产王佐，弱冠称英雄。","白水真帝子，三顾屈其躬。","摧曹发妙略，复汉悬精忠。","大业虽不就，兵图传无穷。","君听三峡水，哀响流长风。"]},{"t":"渡襄江怀孟浩然","f":"五言古诗","c":["孟公本远俗，垂钓汉江水。","雅志岂在鱼，玩弄云烟美。","沉浸颜谢场，唐风美新制。","右丞虚荐言，工部实知己。","飘飘鹿门游，何心慕金紫。"]},{"t":"宜城冬至","f":"七言律诗","c":["去年冬至攸城雨，今岁宜城晓日辉。","暮景两年愁作客，故山千里幸言归。","莺花入梦撩春兴，儿女承欢动舞衣。","北阙简书恩似海，老翁非欲羡轻肥。"]},{"t":"至日往荆州一带视水利","f":"五言律诗","c":["葭管阳生日，天门诏下年。","未能辞簿领，何敢厌山川。","禹凿功非旧，民饥食最先。","荆州喉舌地，抚字赖多贤。"]},{"t":"荆州明月楼","f":"五言古诗","c":["楼中望明月，清光白如昼。","寒江回远天，冥鸿掠高宿。","对之逸兴飞，翻然振长袖。","岂无一樽酒，良友不可遘。","缅怀庾征南，风流绝前后。"]},{"t":"曲江楼","f":"五言古诗","c":["曲江黄阁老，滞此天南州。","直道既为衅，谗巧亦易投。","载歌铄金诗，明夷多隐忧。","贤哲通塞地，天运非人谋。","唯馀楼前水，佳名永同流。"]},{"t":"仲宣楼","f":"五言古诗","c":["公子跌宕士，作赋窥才雄。","刘表不解用，遗之归曹公。","君看大厦就，得无资众工。","慷慨从军作，亦足扬魏风。","登楼想高韵，木落寒山空。"]},{"t":"将进酒","f":"古风","c":["今日何日，景媚辰良。","嘉客四五，杂坐高堂。","主人罗广宴，炮兔炙肥羊。","金壶注清酒，放歌笑千场。","安能坐愁郁，徒使须发苍。","君不见阿房峥嵘高入天，楚兵入关三月烟。","又不见柞宫桂馆通沧海，茂陵孤坟竟何在。","不如刘伯伦，杯行到手不肯停。","天地且以为席幕，睨视贵介如螟蛉。","今日乐相乐，急管交繁丝。","清歌声宛转，华烛光参差。","对酒不痛饮，孤负夭桃枝。","拔剑自起舞，向君肝胆披。","黄金去还来，国士难与期。","男儿堕地抱意气，何用碌碌钱刀为。"]},{"t":"扶风豪士歌","f":"古风","c":["蛟龙一勺水，四海观滂沱。","举头笑凤皇，空鸣岐山阿。","扶风贤士昂藏身，中隐磊落之经纶。","时来仗策谒明主，襟期直与夔龙亲。","世事悠悠不自保，反覆浮云变昏晓。","丈夫有志不得伸，抱关老却夷门道。","君不见长沙贾傅称少年，口吐礼乐翻云烟。","堂中绛灌一侧目，枉杀吴公推毂贤。","又不见汉家旧日李将军，百战孤军陷塞垣。","可怜狱吏摇空笔，遂令妻子俱烦冤。","焚却头上冠，且制芙蓉衣。","君看避矰雁，直入青冥飞。","鲁连竟蹈东海水，夷齐独采西山薇。","生乏功名映麟阁，何用失路长依依。","对君解却腰间剑，归觅磻溪旧钓矶。"]},{"t":"羽林郎","f":"五言古诗","c":["胡姬酒家女，年纪十五强。","白日自当垆，肌肤雪色光。","两鬟垂过耳，美目汎清扬。","窈窕衣纨素，珍珠缀香囊。","盈盈曳丝履，红罗双鸳鸯。","自持耿介性，不解闺中藏。","使君且莫近，况复羽林郎。","自有蒲菀席，何用黄金床。","自有清樽酒，何必玉壶浆。","富贵徒旦夕，礼义古所防。","作女苟无体，不如犬与羊。","寄谢道上露，慎勿沾我裳。"]},{"t":"东门行","f":"古风","c":["出东门，拔剑击门关。","唶它人，驾驷马，富贵遨游王侯卿相间。","嗟我独何郁郁，中夜忧晨餐。","生不得五鼎食，死当长逝不愿还。","少妇牵衣悲啼，听妾致一言：舜禹疾走以避位，讴歌颂其贤。","黄头棹郎铸山而饿死，卒不得怀一钱。","伯夷食薇蕨，盗蹠乃炙人肝。","恶来高位，纣杀比干。","万族各各有生命，上悬沧浪之天。","富贵与贫贱，自计诚独难。"]},{"t":"怨歌行","f":"五言古诗","c":["白日何皎皎，浮云变重阴。","忠义虽云烈，谗巧间君心。","子椒毁屈平，宰嚭恶子胥。","怀沙沈湘浦，鸱夷弃五湖。","大义贯金石，何能顾微躯。","居高忽下议，卒受傍人愚。","楚王终俘虏，吴国竟丘墟。","杳杳九泉暮，衔恨当何如。","我欲竟此曲，此曲伤君神。","往者勿复道，寄谢后代人。"]},{"t":"公无渡河","f":"古风","c":["愿公渡沧海，不愿公渡河。","海水有定性，河水多回波。","金堤失上策，瓠子遗悲歌。","山陵且震荡，将柰公身何。","白骨葬黄流，化为鼋与鼍。","不信妾言苦，请观龙门津。","自古断舟楫，公今徒杀身。","杀身亦不易，竟使傍人嗤。","妾言公不听，公心妾不知。","箜篌之曲令人悲。"]},{"t":"善哉行","f":"古风","c":["前有江水，东注其流。","日月出没，直与年雠。","高车驷马，其忧孔多。","握金而泣，孰与行歌。","夷齐抗首，枵腹泉下。","伯阳和光，均谓贤者。","炰羔脍鲤，速我亲交。","以何解忧，唯有游遨。","游遨四方，金门玉堂。","不如羸马，䠥?故乡。"]},{"t":"长歌行","f":"五言古诗","c":["神龙跃溟海，天地生云雷。","猛虎啸深谷，大风山木摧。","灵物固有象，烈士自有怀。","经纶万物理，上与圣哲偕。","三光鉴丹府，百神司形骸。","举手奠山岳，挥霍云雾开。","功成不受赏，长揖归草莱。","嗤彼鼎彝业，琐琐何为哉。"]},{"t":"独不见","f":"五言古诗","c":["忆妾嫁君日，云发未成鬟。","飘摇红罗带，窈窕秦珠环。","董香闭绮阁，对坐春风閒。","许妾心不移，长指门前山。","讵意青楼女，巧笑矜朱颜。","春风忽飘转，一往不可还。","君如云间月，举手杳莫攀。","妾如归海水，日夜空潺湲。"]},{"t":"秦女卷衣","f":"五言律诗","c":["拂拭君王衣，宛转五龙文。","光华动宝席，恐是瑶台云。","贵人金屏侧，天语杳莫闻。","愿持小星义，誓以奉朝曛。"]},{"t":"上之回","f":"古风","c":["回中道，何逶迤。","千乘雾列，万骑云驰。","北历萧关戍，东谒汾阴祠。","金币四方至，牛马尽为牺。","君王劳玉体，侍从敢言疲。"]},{"t":"战城南","f":"五言古诗","c":["严秋朔气至，敌骑寇边城。","军符星流急，中夜起徵兵。","鱼丽按图列，龙韬应机呈。","前军白刃交，格斗声鏦铮。","控弦若满月，飞镝竞先鸣。","流血原草赤，填尸坑谷平。","洗兵下陇水，献捷奏承明。","天威赫神武，戎狄震且惊。","孰知折冲略，乃由一书生。","伐谋贵庙算，匪在多战争。"]},{"t":"塞下曲 其四","f":"七言绝句","c":["破产潜收古湛卢，愿驰西域斩休屠。","十年未拜千夫长，聊试边城牧马奴。"]},{"t":"明妃怨 其一","f":"七言绝句","c":["掩抑哀弦别上都，玉颜那遣嫁匈奴。","人生觌面犹相忽，何况君王隔画图。"]},{"t":"明妃怨 其二","f":"七言绝句","c":["翠娥颦雪度龙沙，欲悔还愁却自嗟。","争似后宫无履迹，此生长拟见中华。"]},{"t":"白苧辞","f":"古风","c":["玉房围冰夏气清。","黄金作柱横鸣筝。","风纨雾縠丽且轻。","君王近前娇不迎。","牵俦顾侣若有情。","情有馀，言不足。","团扇掩唇扬妙曲。","五花绣茵坐相促。"]},{"t":"春江词","f":"五言古诗","c":["荏苒际韶景，缠绵结芳情。","荡舟清江曲，云物丽波明。","夹岸花齐发，间渚草新生。","唼喋游鱼散，差池飞燕轻。","名都胜侣集，终宴众欢并。","衣香袭芳芷，酒影含飞英。","陈词拟吴趋，选乐杂秦声。","讵羡镜湖隐，匪矜龙池荣。","乐莫斯会乐，白日且徐倾。"]},{"t":"懊恼曲效齐梁体","f":"五言古诗","c":["小时闻长沙，说在天尽处。","人言见郎船，已过长沙去。","家鸡各有埘，海燕各有窠。","郎家扑天屋，作底爱风波。","玉刻莲花斝，碧酒湛若空。","与郎双杯送，出门耐霜风。","春风上燕京，秋风下湘渚。","黄鹄有六翮，定自不及汝。"]},{"t":"粤南曲","f":"楚辞体","c":["白豕兮黄羊。","竹挺挺兮茎方。","顾异物兮心潜伤。","我何为兮客殊方。","北风吹衣兮思故乡。"]},{"t":"霖雨歌七首 其一","f":"古风","c":["乾枢尊，坤极静。","人之灵，感斯应。","于皇德，歆帝心。","悯下土，施丼霖。","霖之绝，土膏歇。","物以残，民益慑。","霖之来，天眷回。","物既苏，民乃怀。","霖之沛，汪且濊。","海灵翔，潢泽溃。","霖之足，灵爽伏。","沃八埏，蕃百谷。","人已悦，神益和。","精禋举，戬福多。","昉天邑，流海宇。","国祚隆，永无圮。"]},{"t":"霖雨歌七首 其二","f":"古风","c":["赫赫皇邑，戢戢王基。","亢阳肆烈，下民其咨。","天子有德，百僚师师。","奏假且严，受于神祗。","霖雨既降，百物咸熙。","鞠哉之咏，媲美周诗。"]},{"t":"霖雨歌七首 其三","f":"七言绝句","c":["帝里骄阳三月外，神车灵雨万家中。","为欢解泽周穷壤，共喜皇情达上穹。"]},{"t":"霖雨歌七首 其四","f":"古风","c":["东隅气举，屏翳乘风奔。","龙腾鲸掉，横飞厉天门。","玄泽滂沱，飞湍激昆崙。","如绳如麻，下注广且繁。"]},{"t":"霖雨歌七首 其五","f":"五言律诗","c":["玉宇垂玄液，瑶图纪上祥。","尧云方荟蔚，舜海转汪洋。","气合晨楼暗，声兼夕漏长。","桑林奚用祷，明德迈前王。"]},{"t":"霖雨歌七首 其六","f":"五言律诗","c":["帝载恊天应，王仁同化游。","冬原偃赤魃，春亩茁来麰。","汎舟川可济，濡绠井堪汲。","元功布黔黎，休徵顺皇极。"]},{"t":"霖雨歌七首 其七","f":"楚辞体","c":["招灵师兮海之浒，来无从兮去无所。","溥神功兮被下土，四民阜兮永安堵。"]},{"t":"武皇南巡旧京歌 其三","f":"七言绝句","c":["狂鲸吹雾暗江潭，圣主仁恩似海涵。","聊唱大风过泗上，即飞霖雨洗淮南。"]},{"t":"武皇南巡旧京歌 其五","f":"七言绝句","c":["赵国新裁短后服，汉王遥嗔侧注冠。","且挥神剑清方岳，莫著褒衣聚将坛。"]}]};